  // Endpoint to fix competitor rates in the database directly
  app.post('/api/admin/fix-competitor-rates', async (req: any, res) => {
    try {
      const { clientId: bodyClientId, month: bodyMonth } = req.body || {};

      // If caller supplies a cross-tenant clientId override, verify they are an admin
      let clientId = req.clientId || 'demo';
      if (bodyClientId && bodyClientId !== clientId) {
        const session = req.session as any;
        if (!session?.userId) {
          return res.status(403).json({ error: 'Unauthorized: must be logged in as an admin to override clientId' });
        }
        const userRows = await db.select().from(users).where(eq(users.id, session.userId)).limit(1);
        if (userRows.length === 0 || !userRows[0].username?.endsWith('_admin')) {
          return res.status(403).json({ error: 'Unauthorized: admin privileges required to override clientId' });
        }
        clientId = bodyClientId;
      }

      // Determine the target month: body param → original hardcoded default fallback
      if (bodyMonth && !/^\d{4}-\d{2}$/.test(bodyMonth)) {
        return res.status(400).json({ error: 'Invalid month format; expected YYYY-MM' });
      }
      const latestMonth = bodyMonth || '2025-11';

      console.log(`🔧 Fixing competitor rates in database for clientId=${clientId}, month=${latestMonth}...`);
      
      const { fixCompetitorRates } = await import('./fixCompetitorRates');
      const result = await fixCompetitorRates(clientId);
      
      // After fixing the database, trigger recalculation
      console.log('📊 Now recalculating competitor rates for rent roll...');
      const { processAllUnitsForCompetitorRates } = await import('./services/competitorRateMatching');
      
      const matchingStats = await processAllUnitsForCompetitorRates(latestMonth, clientId);
      
      res.json({
        success: true,
        message: 'Competitor rates fixed successfully',
        fixResults: result,
        recalculationStats: {
          processed: matchingStats.processed,
          updated: matchingStats.updated,
          errors: matchingStats.errors
        }
      });
      
    } catch (error) {
      console.error('Error fixing competitor rates:', error);
      res.status(500).json({
        error: 'Failed to fix competitor rates',
        details: error instanceof Error ? error.message : 'Unknown error'
      });
    }
  });
  
  // One-time cleanup: strip stale occupancyStatus from rules whose trigger uses
  // array-based metric conditions (visual rule builder format) with no occupancy fields.
  app.post('/api/admin/fix-stale-rule-filters', async (req: any, res) => {
    try {
      const OCCUPANCY_FIELDS = new Set(['occupancy', 'campus_occupancy', 'service_line_occupancy', 'room_type_occupancy']);
      const allRules = await storage.getAdjustmentRules();
      const fixedOccupancy: string[] = [];
      const fixedServiceLine: string[] = [];

      for (const rule of allRules) {
        const trigger = rule.trigger as any;
        const action = rule.action as any;

        // Fix 1: stale occupancyStatus filter (existing logic)
        if (Array.isArray(trigger?.conditions) && action?.filters?.occupancyStatus) {
          const hasOccupancyCondition = trigger.conditions.some((c: any) => OCCUPANCY_FIELDS.has(c.field));
          if (!hasOccupancyCondition) {
            const newFilters = { ...action.filters };
            delete newFilters.occupancyStatus;
            await storage.updateAdjustmentRule(rule.id, {
              action: { ...action, filters: newFilters },
            });
            console.log(`[fix-stale-rule-filters] Cleared stale occupancyStatus from rule "${rule.name}" (id=${rule.id})`);
            fixedOccupancy.push(rule.name);
          }
        }

        // Fix 2: stale action.filters.serviceLine that doesn't match rule.serviceLine
        // Affects rules saved before task #336 where filters.serviceLine=['AL'] but
        // rule.serviceLine='AL/MC'. Replace the filter array with [rule.serviceLine].
        if (rule.serviceLine && Array.isArray(action?.filters?.serviceLine)) {
          const filterSL: string[] = action.filters.serviceLine;
          if (!filterSL.includes(rule.serviceLine)) {
            const newFilters = { ...action.filters, serviceLine: [rule.serviceLine] };
            await storage.updateAdjustmentRule(rule.id, {
              action: { ...action, filters: newFilters },
            });
            console.log(`[fix-stale-rule-filters] Repaired serviceLine filter on rule "${rule.name}" (id=${rule.id}): ${JSON.stringify(filterSL)} → [${rule.serviceLine}]`);
            fixedServiceLine.push(rule.name);
          }
        }
      }

      const totalFixed = fixedOccupancy.length + fixedServiceLine.length;
      res.json({
        message: `Fixed ${totalFixed} rule(s)`,
        fixedOccupancy,
        fixedServiceLine,
      });
    } catch (error) {
      console.error('Error fixing stale rule filters:', error);
      res.status(500).json({ error: 'Failed to fix stale rule filters' });
    }
  });

  // Endpoint to recalculate competitor rates with fixed daily-to-monthly conversion
  app.post('/api/admin/recalculate-competitor-rates', async (req: any, res) => {
    try {
      console.log('🔄 Starting competitor rate recalculation with fixed conversion logic...');
      
      // Get optional filters from request
      const { location, serviceLine, uploadMonth, clientId: bodyClientId } = req.body;

      // If caller supplies a cross-tenant clientId override, verify they are an admin
      let clientId = req.clientId || 'demo';
      if (bodyClientId && bodyClientId !== clientId) {
        const session = req.session as any;
        if (!session?.userId) {
          return res.status(403).json({ error: 'Unauthorized: must be logged in as an admin to override clientId' });
        }
        const userRows = await db.select().from(users).where(eq(users.id, session.userId)).limit(1);
        if (userRows.length === 0 || !userRows[0].username?.endsWith('_admin')) {
          return res.status(403).json({ error: 'Unauthorized: admin privileges required to override clientId' });
        }
        clientId = bodyClientId;
      }
      console.log(`🏢 Scoping recalculation to clientId: ${clientId}${bodyClientId && bodyClientId !== (req.clientId || 'demo') ? ' (admin override from request body)' : ' (from session)'}`);
      
      // Import the processing function
      const { processAllUnitsForCompetitorRates } = await import('./services/competitorRateMatching');
      
      // Build filter conditions - always scope by clientId
      const conditions: any[] = [eq(rentRollData.clientId, clientId)];
      if (location) {
        conditions.push(eq(rentRollData.location, location));
        console.log(`Filtering by location: ${location}`);
      }
      if (serviceLine) {
        conditions.push(eq(rentRollData.serviceLine, serviceLine));
        console.log(`Filtering by service line: ${serviceLine}`);
      }
      if (uploadMonth) {
        conditions.push(eq(rentRollData.uploadMonth, uploadMonth));
        console.log(`Filtering by upload month: ${uploadMonth}`);
      }
      
      // Get units to process
      const unitsQuery = db.select().from(rentRollData).where(and(...conditions));
        
      const units = await unitsQuery;
      console.log(`Found ${units.length} units to process`);
      
      // Process in batches to avoid overwhelming the system
      const batchSize = 100;
      let totalProcessed = 0;
      let totalUpdated = 0;
      let totalErrors = 0;
      const updates: any[] = [];
      
      for (let i = 0; i < units.length; i += batchSize) {
        const batch = units.slice(i, i + batchSize);
        console.log(`Processing batch ${Math.floor(i/batchSize) + 1}/${Math.ceil(units.length/batchSize)}`);
        
        // Process this batch
        const stats = await processAllUnitsForCompetitorRates(uploadMonth || undefined, clientId);
        totalProcessed += stats.processed;
        totalUpdated += stats.updated;
        totalErrors += stats.errors;
        
        // Track updates for response
        if (stats.updates && stats.updates.length > 0) {
          updates.push(...stats.updates);
        }
      }
      
      // Get summary of changes (scoped by clientId)
      const changedUnits = await db.select({
        location: rentRollData.location,
        serviceLine: rentRollData.serviceLine,
        roomType: rentRollData.roomType,
        competitorRate: rentRollData.competitorRate,
        competitorFinalRate: rentRollData.competitorFinalRate
      })
      .from(rentRollData)
      .where(and(
        eq(rentRollData.clientId, clientId),
        sql`${rentRollData.competitorRate} IS NOT NULL`,
        sql`${rentRollData.competitorRate} > 0`
      ))
      .limit(20);
      
      console.log('✅ Competitor rate recalculation complete');
      
      res.json({
        success: true,
        message: 'Competitor rates recalculated with fixed daily-to-monthly conversion',
        stats: {
          totalUnits: units.length,
          processed: totalProcessed,
          updated: totalUpdated,
          errors: totalErrors
        },
        conversionRules: {
          HC: 'Rates < $1000 converted from daily to monthly (×30.44)',
          SMC: 'Rates < $1000 converted from daily to monthly (×30.44)',
          AL: 'Rates < $500 converted from daily to monthly (×30.44)',
          SL: 'Rates < $500 converted from daily to monthly (×30.44)',
          VIL: 'Rates < $500 converted from daily to monthly (×30.44)'
        },
        sampleUpdates: changedUnits.slice(0, 10),
        filters: { clientId, location, serviceLine, uploadMonth }
      });
      
    } catch (error) {
      console.error('Error recalculating competitor rates:', error);
      res.status(500).json({ 
        error: 'Failed to recalculate competitor rates',
        details: error instanceof Error ? error.message : 'Unknown error'
      });
    }
  });

