          'Campus': 'Anderson - 112',
          'Department': 'AL/MC',
          'Service Line': 'Memory Care',
          'Room/Bed': '311/B',
          'Last Name': 'Sample',
          'Payer Name': 'Private Pay',
          'Move Event': 'Admission',
          'Move Category': 'New Admission',
