  // Pricing recommendations
  app.get("/api/recommendations", async (req: any, res) => {
    try {
      const clientId = req.clientId || 'demo';
      let rentRollData = await storage.getRentRollData(clientId);
      
      // If no rent roll data exists, return error
      if (rentRollData.length === 0) {
        return res.status(404).json({ error: "No rent roll data available. Please import production data." });
      }
      
      const weights = await storage.getCurrentWeights();

      // Shared care-adjusted market benchmark (task 437 methodology) — never
      // compare against raw per-unit competitor rate averages (room-mix distorted).
      const compBenchmark = await loadCompBenchmark(pool, clientId);

      // Generate recommendations based on algorithm
      const recommendations = await Promise.all(rentRollData.map(async unit => {
        let recommendedRent = unit.streetRate;
        let rationale = "Base rent";
        let mlConfidence = Math.floor(Math.random() * 30) + 70; // 70-99% confidence
        const factors = [];

        // Apply occupancy pressure
        if (!unit.occupiedYN && (unit.daysVacant || 0) > 60) {
          recommendedRent *= 0.92; // 8% reduction for very long vacancy
          factors.push("long vacancy discount");
          mlConfidence -= 5;
        } else if (!unit.occupiedYN && (unit.daysVacant || 0) > 30) {
          recommendedRent *= 0.96; // 4% reduction for moderate vacancy
          factors.push("vacancy adjustment");
        } else if (unit.occupiedYN) {
          recommendedRent *= 1.03; // 3% increase for occupied units
          factors.push("occupancy premium");
          mlConfidence += 5;
        }

        // Apply unit attributes
        if (unit.view && unit.view !== 'Street View') {
          recommendedRent *= 1.05;
          factors.push("premium view");
          mlConfidence += 3;
        }
        if (unit.renovated) {
          recommendedRent *= 1.08;
          factors.push("recently renovated");
          mlConfidence += 5;
        }

        // Apply competitor rates via the shared care-adjusted market benchmark
        const marketBenchmark = compBenchmark.benchmarkFor(unit.location, unit.serviceLine)?.adjusted ?? null;
        if (marketBenchmark && unit.streetRate > 0) {
          const competitorDiff = (marketBenchmark - unit.streetRate) / unit.streetRate;
          if (Math.abs(competitorDiff) > 0.1) { // Significant difference
            recommendedRent += (competitorDiff * recommendedRent * 0.3);
            factors.push(competitorDiff > 0 ? "market premium opportunity" : "competitive pricing");
            mlConfidence += 8;
          }
        }

        // Apply market sentiment using real S&P 500 data
        const sp500Return = await fetchSP500Data();
        if (sp500Return > 2) {
          recommendedRent *= 1.025; // Strong market allows premium
          factors.push("strong market conditions");
          mlConfidence += 3;
        } else if (sp500Return < -2) {
          recommendedRent *= 0.975; // Weak market requires discount
          factors.push("market headwinds");
          mlConfidence -= 3;
        }

        // Apply room type adjustments
        if (unit.roomType === "Memory Care") {
          recommendedRent *= 1.02; // Premium care commands higher rates
          factors.push("specialized care premium");
          mlConfidence += 5;
        }

        // Generate ML suggested rent (slightly different from algorithm)
        const mlVariance = (Math.random() - 0.5) * 0.06; // ±3% variance
        const mlSuggestedRent = Math.round(recommendedRent * (1 + mlVariance));

        // Cap confidence at 95%
        mlConfidence = Math.min(mlConfidence, 95);

        // Create rationale
        rationale = factors.length > 0 ? factors.join(", ") : "market rate analysis";

        return {
          Unit_ID: unit.roomNumber,
          Room_Type: unit.roomType,
          Occupied_YN: unit.occupiedYN ? 'Y' : 'N',
          Days_Vacant: unit.daysVacant || 0,
          Fence_Price: unit.streetRate,
          Competitor_Benchmark_Rate: marketBenchmark,
          Recommended_Rent: Math.round(recommendedRent),
          ML_Suggested_Rent: mlSuggestedRent,
          ML_Confidence: mlConfidence,
          Rationale: rationale
        };
      }));

      res.json({ items: recommendations });
    } catch (error) {
      res.status(500).json({ error: "Failed to generate recommendations" });
    }
  });

  // NOTE: The legacy /api/compare endpoint (room-type comparison from raw
  // per-unit competitor rate averages) was removed — its only consumer was the
  // unrouted pages/dashboard.tsx ComparisonTable, and its market math was
  // room-mix distorted. Use the shared benchmark service (compBenchmark.ts).

  // Publish rates to CSV
  app.post("/api/publish", async (req, res) => {
    try {
      const clientId = req.clientId || 'demo';

      // Find the latest month with data for this client
      const latestMonthResult = await db
        .select({ uploadMonth: rentRollData.uploadMonth })
        .from(rentRollData)
        .where(and(sql`${rentRollData.uploadMonth} IS NOT NULL`, eq(rentRollData.clientId, clientId)))
        .orderBy(sql`${rentRollData.uploadMonth} DESC`)
        .limit(1);
      const latestMonth = latestMonthResult[0]?.uploadMonth;
      if (!latestMonth) {
        return res.status(404).json({ error: "No rent roll data found for this client" });
      }

      // Fetch units for the latest month, joining locations for division.
      // source_room_type stores the raw import string before normalization;
      // it was added via ALTER TABLE migration and may be NULL for records
      // imported before the column existed — fall back to roomType in that case.
      const units = await db
        .select({
          location: rentRollData.location,
          division: locations.division,
          serviceLine: rentRollData.serviceLine,
          roomType: rentRollData.roomType,
          sourceRoomType: sql<string | null>`${rentRollData.sourceRoomType}`,
          streetRate: rentRollData.streetRate,
          moduloSuggestedRate: rentRollData.moduloSuggestedRate,
          ruleAdjustedRate: rentRollData.ruleAdjustedRate,
          appliedRuleName: rentRollData.appliedRuleName,
          aiSuggestedRate: rentRollData.aiSuggestedRate,
        })
        .from(rentRollData)
        .leftJoin(locations, eq(rentRollData.locationId, locations.id))
        .where(
          and(
            eq(rentRollData.uploadMonth, latestMonth),
            eq(rentRollData.clientId, clientId),
            // Include any unit where at least one rate has been calculated (non-null).
            // Removed the > 0 guard so units whose rate was calculated as 0 still appear;
            // empty cells are shown in the CSV where no rate exists.
            sql`(
              ${rentRollData.moduloSuggestedRate} IS NOT NULL
              OR ${rentRollData.ruleAdjustedRate} IS NOT NULL
              OR ${rentRollData.aiSuggestedRate} IS NOT NULL
            )`
          )
        );

      // Format adjustment as signed percentage string
      const formatAdj = (rate: number | null | undefined, street: number | null | undefined): string => {
        if (!rate || !street || street === 0) return '';
        const pct = ((rate - street) / street) * 100;
        const rounded = Math.round(pct * 10) / 10;
        return (rounded >= 0 ? '+' : '') + rounded.toFixed(1) + '%';
      };

      // Helper: compute median of a numeric array (ignoring nulls/zeros) — used for AI rates only
      const median = (values: (number | null | undefined)[]): number | null => {
        const nums = values.filter((v): v is number => v != null && v > 0);
        if (nums.length === 0) return null;
        const sorted = [...nums].sort((a, b) => a - b);
        const mid = Math.floor(sorted.length / 2);
        return sorted.length % 2 === 0
          ? Math.round((sorted[mid - 1] + sorted[mid]) / 2)
          : sorted[mid];
      };

      // Group units by: Division + Location + Service Line + raw Room Type + Recommended Rate.
      // Recommended Rate = ruleAdjustedRate if rules fired, else moduloSuggestedRate (rounded to
      // nearest dollar) — exactly what the Rate Card displays in its "Rules Rate" column.
      // Units sharing the same room type AND the same recommended rate collapse into one row;
      // units with the same room type but a different recommended rate get their own row.
      // Key encoding distinguishes NULL-derived room type keys from populated ones.
      type UnitRow = typeof units[0];
      type GroupEntry = {
        meta: UnitRow;
        roomTypeDisplay: string;
        recommendedRate: number;
        unitCount: number;
        streetRate: number | null;
        appliedRuleNames: Set<string>;
        aiRates: (number | null | undefined)[];
      };
      const groupMap = new Map<string, GroupEntry>();
      for (const u of units) {
        const hasSource = u.sourceRoomType != null && u.sourceRoomType !== '';
        const roomTypeDisplay = hasSource ? u.sourceRoomType! : u.roomType;
        const keyPrefix = hasSource ? 'src' : 'norm';

        // Compute this unit's recommended rate (mirrors Rate Card "Rules Rate" logic)
        const rawRecommended = u.ruleAdjustedRate ?? u.moduloSuggestedRate;
        if (rawRecommended == null) continue; // skip units with no rate at all
        const recommendedRate = Math.round(rawRecommended);

        const key = `${keyPrefix}|${u.division || ''}|${u.location}|${u.serviceLine}|${roomTypeDisplay}|${recommendedRate}`;
        if (!groupMap.has(key)) {
          groupMap.set(key, {
            meta: u,
            roomTypeDisplay,
            recommendedRate,
            unitCount: 0,
            streetRate: u.streetRate != null && u.streetRate > 0 ? u.streetRate : null,
            appliedRuleNames: new Set(),
            aiRates: [],
          });
        }
        const entry = groupMap.get(key)!;
        entry.unitCount += 1;
        if (entry.streetRate == null && u.streetRate != null && u.streetRate > 0) {
          entry.streetRate = u.streetRate;
        }
        if (u.appliedRuleName) entry.appliedRuleNames.add(u.appliedRuleName);
        entry.aiRates.push(u.aiSuggestedRate);
      }

      // Build one CSV row per group, sorted by Location → Service Line → Room Type →
      // Recommended Rate descending.
      const rows = Array.from(groupMap.values())
        .sort((a, b) => {
          const locCmp = (a.meta.location ?? '').localeCompare(b.meta.location ?? '');
          if (locCmp !== 0) return locCmp;
          const slCmp = (a.meta.serviceLine ?? '').localeCompare(b.meta.serviceLine ?? '');
          if (slCmp !== 0) return slCmp;
          const rtCmp = (a.roomTypeDisplay ?? '').localeCompare(b.roomTypeDisplay ?? '');
          if (rtCmp !== 0) return rtCmp;
          return b.recommendedRate - a.recommendedRate; // descending by rate
        })
        .map(({ meta, roomTypeDisplay, recommendedRate, unitCount, streetRate, appliedRuleNames, aiRates }) => {
          const medAI = median(aiRates);
          const appliedRulesStr = appliedRuleNames.size > 0
            ? Array.from(appliedRuleNames).join(' + ')
            : '';
          return {
            'Division': meta.division || '',
            'Location': meta.location,
            'Service Line': meta.serviceLine,
            'Room Type': roomTypeDisplay,
            'Unit Count': unitCount,
            'Current Street Rate': streetRate ?? '',
            'Applied Rules': appliedRulesStr,
            'Recommended Rate': recommendedRate,
            'Adjustment %': formatAdj(recommendedRate, streetRate),
            'Rev Target AI Rate': medAI ?? '',
            'Rev Target AI Adjustment %': formatAdj(medAI, streetRate),
          };
        });

      const csvContent = Papa.unparse(rows);
      const filename = `pricing_recommendations_${new Date().toISOString().split('T')[0]}.csv`;

      res.setHeader('Content-Type', 'text/csv');
      res.setHeader('Content-Disposition', `attachment; filename="${filename}"`);
      res.send(csvContent);
    } catch (error) {
      console.error('Failed to export recommendations CSV:', error);
      res.status(500).json({ error: "Failed to publish CSV" });
    }
  });

