  app.get("/api/competitor-rate-comparison", async (req: any, res) => {
    try {
      const { location, serviceLines } = req.query;
      const clientId = req.clientId || 'demo';
      
      if (!location) {
        return res.json({ data: [], trilogyRates: {} });
      }
      
      const locationName = location as string;
      const serviceLineFilter = serviceLines ? (Array.isArray(serviceLines) ? serviceLines : [serviceLines]) : [];
      
      // Map service lines to competitor types stored in the DB.
      // HC/MC includes legacy 'SMC' records imported before the rename.
      const SERVICE_LINE_TO_COMPETITOR_TYPE: Record<string, string[]> = {
        'HC': ['HC'],
        'HC/MC': ['HC/MC', 'SMC'],
        'AL': ['AL'],
        'AL/MC': ['AL/MC'],
        'SL': ['IL_IL'],
        'VIL': ['IL_Villa']
      };
      
      // Get competitor types to query
      let competitorTypes: string[] = [];
      if (serviceLineFilter.length > 0) {
        competitorTypes = serviceLineFilter.flatMap(sl => SERVICE_LINE_TO_COMPETITOR_TYPE[sl as string] || [sl]).filter(Boolean);
      } else {
        competitorTypes = Object.values(SERVICE_LINE_TO_COMPETITOR_TYPE).flat();
      }
      
      // Remove duplicates
      competitorTypes = [...new Set(competitorTypes)];
      
      // Fetch competitive survey data for this location
      const surveyData = await db.select()
        .from(competitiveSurveyData)
        .where(and(
          eq(competitiveSurveyData.keyStatsLocation, locationName),
          eq(competitiveSurveyData.clientId, clientId),
          competitorTypes.length > 0 ? inArray(competitiveSurveyData.competitorType, competitorTypes) : sql`1=1`
        ))
        .orderBy(competitiveSurveyData.competitorType, competitiveSurveyData.roomType, competitiveSurveyData.competitorName);
      
      // Get latest month for Trilogy rates (filtered by clientId)
      const latestMonthData = await db.select({ uploadMonth: rentRollData.uploadMonth })
        .from(rentRollData)
        .where(eq(rentRollData.clientId, clientId))
        .orderBy(desc(rentRollData.uploadMonth))
        .limit(1);
      const latestMonth = latestMonthData.length > 0 ? latestMonthData[0].uploadMonth : null;
      
      // Get Trilogy's average rates by service line and room type for this location
      const trilogyRates: Record<string, Record<string, number>> = {};
      if (latestMonth) {
        const trilogyData = await db.select({
          serviceLine: rentRollData.serviceLine,
          roomType: rentRollData.roomType,
          avgRate: sql<number>`AVG(CASE WHEN NOT (${rentRollData.serviceLine} IN ('AL', 'AL/MC', 'SL', 'VIL') AND ${rentRollData.roomNumber} ~* '/[B-Zb-z]$') THEN ${rentRollData.streetRate} ELSE NULL END)`
        })
          .from(rentRollData)
          .where(and(
            eq(rentRollData.clientId, clientId),
            eq(rentRollData.uploadMonth, latestMonth),
            eq(rentRollData.location, locationName),
            gt(rentRollData.streetRate, 0)
          ))
          .groupBy(rentRollData.serviceLine, rentRollData.roomType);
        
        for (const row of trilogyData) {
          if (!trilogyRates[row.serviceLine]) {
            trilogyRates[row.serviceLine] = {};
          }
          trilogyRates[row.serviceLine][row.roomType] = row.avgRate || 0;
        }
      }
      
      // Fetch Trilogy's care level 2 rates from care_level_rates for this location
      // Build a map keyed by service line so we can compute the differential in the transformed data
      const trilogyCareRateMap: Record<string, number> = {};
      {
        const locationRecord = await db.select({ id: locations.id })
          .from(locations)
          .where(and(eq(locations.name, locationName), eq(locations.clientId, clientId)))
          .limit(1);
        if (locationRecord.length > 0) {
          const careRates = await db.select({
            serviceLine: careLevelRates.serviceLine,
            level2Rate: careLevelRates.level2Rate
          })
            .from(careLevelRates)
            .where(and(
              eq(careLevelRates.locationId, locationRecord[0].id),
              eq(careLevelRates.clientId, clientId)
            ));
          for (const rate of careRates) {
            trilogyCareRateMap[rate.serviceLine] = rate.level2Rate;
          }
        }
      }

      // Filter to only the most recent survey month (mirrors getCompetitorsWithFilters logic)
      if (surveyData.length > 0) {
        let latestSurveyMonth = '';
        for (const record of surveyData) {
          const month = record.surveyMonth || '';
          if (month > latestSurveyMonth) {
            latestSurveyMonth = month;
          }
        }
        if (latestSurveyMonth) {
          // Keep rows from the latest month OR rows with no survey month (mirrors getCompetitorsWithFilters)
          surveyData.splice(0, surveyData.length, ...surveyData.filter(r => !r.surveyMonth || r.surveyMonth === latestSurveyMonth));
        }
      }

      // Apply weight-based filtering to the survey data
      const parseNoteWeight = (notes: string | null): number => {
        if (!notes) return 0;
        try {
          const parsed = typeof notes === 'string' ? JSON.parse(notes) : notes;
          return parseFloat(String(parsed?.weight ?? '0')) || 0;
        } catch { return 0; }
      };

      const weightedSurveyData = surveyData.filter(r => parseNoteWeight(r.notes) > 0);
      let filteredSurveyData = weightedSurveyData;
      let rateComparisonFallback = false;

      if (weightedSurveyData.length === 0 && surveyData.length > 0) {
        // Fall back to top-5 closest unique competitors
        rateComparisonFallback = true;
        const sorted = [...surveyData].sort((a, b) => (a.distanceMiles || 999) - (b.distanceMiles || 999));
        const top5Names = new Set<string>();
        for (const r of sorted) {
          top5Names.add(r.competitorName || '');
          if (top5Names.size >= 5) break;
        }
        filteredSurveyData = surveyData.filter(r => top5Names.has(r.competitorName || ''));
      }

      // Transform survey data with market position calculations
      const COMPETITOR_TYPE_TO_SERVICE_LINE: Record<string, string> = {
        'HC': 'HC',
        'SMC': 'HC/MC',
        'HC/MC': 'HC/MC',
        'AL': 'AL',
        'AL/MC': 'AL/MC',
        'IL_IL': 'SL',
        'IL_Villa': 'VIL'
      };
      
      // Convert daily rates to monthly for HC/SMC
      const DAYS_PER_MONTH = 30.44;
      
      // Service lines where care level 2 adjustment applies
      const CARE_LEVEL_2_APPLIES: Record<string, boolean> = {
        'HC': true, 'HC/MC': true, 'AL': true, 'AL/MC': true, 'SL': false, 'VIL': false
      };

      const transformedData = filteredSurveyData.map(record => {
        const serviceLine = COMPETITOR_TYPE_TO_SERVICE_LINE[record.competitorType || ''] || record.competitorType;
        let baseRate = record.monthlyRateAvg || 0;
        let careLevel2 = record.careLevel2Rate || 0;
        let medMgmt = record.medicationManagementFee || 0;
        
        // Convert HC/SMC/HC/MC daily rates to monthly if they appear to be daily (< $1000)
        const isHCType = record.competitorType === 'HC' || record.competitorType === 'SMC' || record.competitorType === 'HC/MC';
        if (isHCType && baseRate > 0 && baseRate < 1000) {
          baseRate = baseRate * DAYS_PER_MONTH;
          if (careLevel2 > 0 && careLevel2 < 500) careLevel2 = careLevel2 * DAYS_PER_MONTH;
          if (medMgmt > 0 && medMgmt < 100) medMgmt = medMgmt * DAYS_PER_MONTH;
        }
        
        // Compute care adjustment as differential: competitor care L2 − Trilogy care L2
        // If no entry exists in care_level_rates for this location/service line, apply no care adjustment
        let careAdj = 0;
        if (CARE_LEVEL_2_APPLIES[serviceLine]) {
          const trilogyCareL2 = trilogyCareRateMap[serviceLine];
          if (trilogyCareL2 !== undefined) {
            careAdj = careLevel2 - trilogyCareL2;
          }
          // else: no care_level_rates entry for this service line — no adjustment applied
        }

        const adjustedRate = baseRate + careAdj + medMgmt;
        
        // Get Trilogy rate for comparison
        const trilogyServiceLine = serviceLine === 'AL' ? 'AL' : serviceLine;
        const trilogyRate = trilogyRates[trilogyServiceLine]?.[record.roomType || ''] || 0;
        
        // Calculate market position (Trilogy rate / Competitor rate * 100), 1 decimal place
        // so 99.6% doesn't round to 100% and incorrectly show as "at/above market"
        const marketPosition = adjustedRate > 0 ? parseFloat((trilogyRate / adjustedRate * 100).toFixed(1)) : 0;
        
        return {
          id: record.id,
          competitorName: record.competitorName,
          competitorType: record.competitorType,
          serviceLine,
          roomType: record.roomType,
          distanceMiles: record.distanceMiles,
          baseRate: Math.round(baseRate),
          careLevel2Adjustment: Math.round(careAdj),
          medMgmtAdjustment: Math.round(medMgmt),
          adjustedRate: Math.round(adjustedRate),
          trilogyRate: Math.round(trilogyRate),
          marketPosition,
          occupancyRate: record.occupancyRate
        };
      });
      
      res.json({
        data: transformedData,
        trilogyRates,
        location: locationName,
        usingDistanceFallback: rateComparisonFallback
      });
    } catch (error) {
      console.error('Error fetching competitor rate comparison:', error);
      res.status(500).json({ error: 'Failed to fetch competitor rate comparison' });
    }
  });

  // Inline edit: update rate fields on a competitive survey record
  app.patch("/api/competitive-survey/:id", async (req: any, res) => {
    try {
      const id = req.params.id as string;
      const clientId = req.clientId || 'demo';
      const { baseRate, careLevel2Adjustment, medMgmtFee } = req.body;

      const records = await db.select().from(competitiveSurveyData)
        .where(eq(competitiveSurveyData.id, id)).limit(1);
      if (!records.length) return res.status(404).json({ error: 'Record not found' });
      const record = records[0];

      const updates: Record<string, any> = {};
      if (baseRate !== undefined) updates.monthlyRateAvg = parseFloat(baseRate);
      if (medMgmtFee !== undefined) updates.medicationManagementFee = parseFloat(medMgmtFee);

      if (careLevel2Adjustment !== undefined) {
        // careAdj displayed = competitor.careL2 − trilogy.careL2
        // → competitor.careL2 = careAdj + trilogy.careL2
        const COMP_TO_SL: Record<string, string> = {
          'HC': 'HC', 'SMC': 'HC/MC', 'HC/MC': 'HC/MC',
          'AL': 'AL', 'AL/MC': 'AL/MC', 'IL_IL': 'SL', 'IL_Villa': 'VIL'
        };
        const trilogySL = COMP_TO_SL[record.competitorType || ''] || record.competitorType || '';
        const locRecord = await db.select({ id: locations.id })
          .from(locations)
          .where(and(eq(locations.name, record.keyStatsLocation || ''), eq(locations.clientId, clientId)))
          .limit(1);
        let trilogyCareL2 = 0;
        if (locRecord.length) {
          const careRow = await db.select({ level2Rate: careLevelRates.level2Rate })
            .from(careLevelRates)
            .where(and(
              eq(careLevelRates.locationId, locRecord[0].id),
              eq(careLevelRates.clientId, clientId),
              eq(careLevelRates.serviceLine, trilogySL)
            )).limit(1);
          trilogyCareL2 = careRow[0]?.level2Rate ?? 0;
        }
        updates.careLevel2Rate = parseFloat(careLevel2Adjustment) + trilogyCareL2;
      }

      if (!Object.keys(updates).length) return res.status(400).json({ error: 'Nothing to update' });
      await db.update(competitiveSurveyData).set(updates).where(eq(competitiveSurveyData.id, id));
      res.json({ success: true });
    } catch (error) {
      console.error('Error updating competitive survey record:', error);
      res.status(500).json({ error: 'Update failed' });
    }
  });

  // Job-based competitor rate matching - Start a new job
  app.post("/api/competitor-rates/job/start", async (req: any, res) => {
    try {
      const { uploadMonth, clientId: bodyClientId } = req.body;
      const targetMonth = uploadMonth || '2025-11';
      
      // Default to the session's clientId so the job is always scoped to the caller's tenant.
      // Admins may override with an explicit clientId in the request body to run cross-tenant.
      // Omitting clientId entirely (e.g. scheduled portfolio-wide runs) leaves it unscoped.
      let scopedClientId: string | undefined = req.clientId || undefined;
      if (bodyClientId && bodyClientId !== scopedClientId) {
        const session = req.session as any;
        if (!session?.userId) {
          return res.status(403).json({ error: 'Unauthorized: must be logged in as an admin to override clientId' });
        }
        const userRows = await db.select().from(users).where(eq(users.id, session.userId)).limit(1);
        if (userRows.length === 0 || !userRows[0].username?.endsWith('_admin')) {
          return res.status(403).json({ error: 'Unauthorized: admin privileges required to override clientId' });
        }
        scopedClientId = bodyClientId;
      }

      const result = await startCompetitorRateJob(targetMonth, scopedClientId);
      
      res.json({
        success: true,
        jobId: result.jobId,
        status: result.status,
        message: `Competitor rate job started for ${targetMonth}${scopedClientId ? ` (client: ${scopedClientId})` : ' (all clients)'}. Processing in background.`
      });
    } catch (error) {
      console.error('Error starting competitor rate job:', error);
      res.status(500).json({ error: 'Failed to start competitor rate job' });
    }
  });
  
