  // Get detailed calculation for a specific unit's AI rate
  app.get("/api/ai-calculation/:unitId", async (req: any, res) => {
    try {
      const clientId = req.clientId || 'demo';
      const { unitId } = req.params;
      const unit = await storage.getRentRollDataById(unitId);
      
      if (!unit) {
        return res.status(404).json({ error: 'Unit not found' });
      }

      if (unit.clientId && unit.clientId !== clientId) {
        return res.status(403).json({ error: 'Access denied' });
      }

      // ── Live revenue-target lookup (always fresh, overrides any stale stored value) ──
      let liveRevenueTarget: any = null;
      try {
        // Resolve locationId: prefer stored, fall back to name-based lookup
        let resolvedLocationId = unit.locationId as string | null;
        if (!resolvedLocationId && unit.location) {
          const loc = await storage.getLocationByName(unit.location as string);
          if (loc) resolvedLocationId = loc.id;
        }

        if (resolvedLocationId && unit.serviceLine) {
          const targets = await storage.getRevenueGrowthTargets(resolvedLocationId);
          const target = targets.find(
            (t: any) => t.serviceLine === unit.serviceLine || t.serviceLine === 'All'
          );

          if (target) {
            // Approximate actual YOY growth from rent roll monthly revenue trend
            const allUnits = await storage.getRentRollData(clientId);
            const locUnits = allUnits.filter(
              (u: any) => (u.locationId === resolvedLocationId || u.location === unit.location)
                && u.serviceLine === unit.serviceLine
            );

            // Group by uploadMonth and sum revenue
            const monthRevenue: Record<string, number> = {};
            for (const u of locUnits) {
              if (!u.uploadMonth) continue;
              const rate = u.occupiedYN ? (u.inHouseRate || u.streetRate || 0) : 0;
              monthRevenue[u.uploadMonth] = (monthRevenue[u.uploadMonth] || 0) + rate;
            }
            const sortedMonths = Object.keys(monthRevenue).sort();
            let actualYOYGrowth: number | undefined;
            if (sortedMonths.length >= 2) {
              const latest = monthRevenue[sortedMonths[sortedMonths.length - 1]];
              const oldest = monthRevenue[sortedMonths[0]];
              if (oldest > 0) {
                // Scale to annual if we have less than 12 months
                const monthSpan = sortedMonths.length;
                const rawGrowth = ((latest - oldest) / oldest) * 100;
                actualYOYGrowth = parseFloat((rawGrowth * (12 / Math.max(monthSpan - 1, 1))).toFixed(1));
              }
            }

            const targetGrowthPercent = target.targetGrowthPercent;
            const gap = actualYOYGrowth !== undefined
              ? parseFloat((actualYOYGrowth - targetGrowthPercent).toFixed(1))
              : undefined;
            const status = gap === undefined ? 'no_target'
              : gap >= 0 ? 'exceeding'
              : gap >= -2 ? 'on_target'
              : gap >= -5 ? 'slightly_behind'
              : 'significantly_behind';

            liveRevenueTarget = {
              targetGrowthPercent,
              actualYOYGrowth,
              gap,
              status,
              adjustmentApplied: gap !== undefined && gap < 0 ? Math.min(Math.abs(gap) * 0.003, 0.02) : 0,
            };
          } else {
            liveRevenueTarget = { status: 'no_target' };
          }
        } else {
          liveRevenueTarget = { status: 'no_target' };
        }
      } catch (e) {
        console.error('[ai-calculation] revenue target lookup error:', e);
        liveRevenueTarget = { status: 'no_target' };
      }
      
      // Use stored calculation details if available AND they include the guardrailWasApplied
      // marker (added in the v2 format). Old cached entries lack this field and may have
      // a stale aiSuggestedRate that is inconsistent with the stored totalAdjustment, which
      // causes the dialog to show a false "guardrail applied" warning. Skipping them forces
      // a fresh recompute and overwrites the stale cache.
      if (unit.aiCalculationDetails) {
        try {
          const storedDetails = JSON.parse(unit.aiCalculationDetails);
          if (storedDetails.guardrailWasApplied !== undefined) {
            // v2 format — data is self-consistent, safe to return as-is
            storedDetails.revenueTarget = liveRevenueTarget;
            return res.json({
              unitId: unit.id,
              roomType: unit.roomType,
              streetRate: unit.streetRate,
              aiSuggestedRate: unit.aiSuggestedRate,
              calculation: storedDetails
            });
          }
          // else: old format — fall through to recompute
        } catch (e) {
          console.error('Error parsing stored AI calculation details:', e);
        }
      }
      
      // Import sophisticated algorithm and explanations
      const { calculateModuloPrice } = await import('./moduloPricingAlgorithm');
      const { getSentenceExplanation, generateOverallExplanation } = await import('./sentenceExplanations');
      
      // Fallback to dynamic calculation if no stored details (or old-format cache)
      const streetRate = unit.streetRate || 3185;
      
      // Get AI-specific weights - more aggressive than Modulo
      const aiWeights = await storage.getAiPricingWeights() || {
        occupancyPressure: 30,
        daysVacantDecay: 25,
        competitorRates: 10,
        seasonality: 5,
        stockMarket: 5,
        inquiryTourVolume: 10
      };
      
      // Calculate service-line-specific occupancy from room_type_occupancy_history (authoritative)
      // Falls back to rent_roll_data occupied_yn counts if RTO has no data.
      const rtoSLRes = await pool.query(`
        SELECT service_line, SUM(occ_units) AS occ, SUM(available_units) AS avail
        FROM room_type_occupancy_history
        WHERE client_id = $1
          AND (year * 100 + month) = (
            SELECT MAX(year * 100 + month) FROM room_type_occupancy_history WHERE client_id = $1
          )
        GROUP BY service_line
      `, [clientId]);
      const serviceLineOccupancy: Record<string, number> = {};
      if (rtoSLRes.rows.length > 0) {
        // Accumulate occ/avail per SL token (handling combined SL strings like "AL, AL/MC")
        const slAgg: Record<string, { occ: number; avail: number }> = {};
        for (const r of rtoSLRes.rows) {
          const o  = parseFloat(r.occ   || '0');
          const av = parseFloat(r.avail || '0');
          const toks = String(r.service_line || '').split(',').map((t: string) => t.trim());
          for (const tok of toks) {
            if (!slAgg[tok]) slAgg[tok] = { occ: 0, avail: 0 };
            slAgg[tok].occ   += o;
            slAgg[tok].avail += av;
          }
        }
        for (const [sl, v] of Object.entries(slAgg)) {
          serviceLineOccupancy[sl] = v.avail > 0 ? v.occ / v.avail : 0.87;
        }
      } else {
        // Fallback: rent_roll_data occupied_yn
        const occRows = await pool.query<{ service_line: string; total: string; occupied: string }>(`
          SELECT service_line, COUNT(*)::text AS total,
                 COUNT(*) FILTER (WHERE occupied_yn = true)::text AS occupied
          FROM rent_roll_data WHERE client_id = $1 GROUP BY service_line
        `, [clientId]);
        for (const row of occRows.rows) {
          const total = parseInt(row.total, 10);
          const occupied = parseInt(row.occupied, 10);
          serviceLineOccupancy[row.service_line] = total > 0 ? occupied / total : 0.87;
        }
      }

      // Use service-line-specific occupancy for this unit
      const serviceLineOcc = serviceLineOccupancy[unit.serviceLine ?? 'Unknown'] || 0.87;
      
      // Prepare inputs for sophisticated AI algorithm (more aggressive than Modulo)
      const daysVacant = unit.daysVacant || 0;
      
      // Calculate attribute score
      let attrScore = 0.5;
      if (unit.attributes) {
        if (unit.attributes.view) attrScore += 0.1;
        if (unit.attributes.renovated) attrScore += 0.15;
        if (unit.attributes.corner) attrScore += 0.1;
      }
      if (unit.roomType === 'Private') attrScore += 0.1;
      attrScore = Math.min(1.0, attrScore);
      
      const monthIndex = new Date().getMonth() + 1;
      const competitorPrices = unit.competitorBenchmarkRate ? 
        [unit.competitorBenchmarkRate] : 
        [streetRate * 0.95, streetRate * 1.05];
      
      // Mock demand data - AI sees higher volatility
      const demandHistory = [15, 20, 30, 18, 35, 22, 28, 16];
      const demandCurrent = 32;
      
      const aiInputs = {
        occupancy: serviceLineOcc,
        daysVacant,
        attrScore,
        monthIndex,
        competitorPrices,
        marketReturn: 0.03, // AI is more optimistic
        demandCurrent,
        demandHistory,
        serviceLine: unit.serviceLine  // Pass service line for market positioning targets
      };
      
      // Convert AI weights to algorithm format
      const algorithmWeights = {
        occupancy: aiWeights.occupancyPressure || 30,
        daysVacant: aiWeights.daysVacantDecay || 25,
        seasonality: aiWeights.seasonality || 5,
        competitors: aiWeights.competitorRates || 10,
        market: aiWeights.stockMarket || 5,
        demand: aiWeights.inquiryTourVolume || 10
      };
      
      // Calculate using sophisticated algorithm
      const result = calculateModuloPrice(streetRate, algorithmWeights, aiInputs);

      // ── Guardrail application ───────────────────────────────────────────────
      const preGuardrailRate  = result.finalPrice;
      const preGuardrailAdjustment = result.totalAdjustment;

      const guardrailsData = await storage.getCurrentGuardrails();
      let clampedRate = preGuardrailRate;
      let freshGuardrailWasApplied = false;
      let guardrailMinAllowed = 0;
      let guardrailMaxAllowed = Infinity;
      let guardrailLimitPct: number | null = null;
      if (guardrailsData) {
        const clamp = clampRateWithGuardrails(preGuardrailRate, streetRate, guardrailsData);
        guardrailMinAllowed = clamp.minAllowed;
        guardrailMaxAllowed = clamp.maxAllowed;
        if (clamp.wasAdjusted && Math.abs(clamp.finalRate - preGuardrailRate) > 0.5) {
          clampedRate = clamp.finalRate;
          freshGuardrailWasApplied = true;
          guardrailLimitPct = preGuardrailRate > guardrailMaxAllowed
            ? (guardrailsData.maxPriceChangePct ?? 15)
            : Math.abs(guardrailsData.minPriceChangePct ?? -5);
        }
      }

      // ── Use stored DB rate as the authoritative displayed rate ──────────────
      // The fresh recompute uses mock demand inputs that differ from the original
      // batch inputs, so its rate and totalAdjustment will legitimately differ
      // from the stored values.  Always show the stored rate so the dialog
      // headline matches the rate card exactly.  The fresh computation drives
      // the individual factor breakdown only.
      const storedRate = (unit.aiSuggestedRate && unit.aiSuggestedRate > 0) ? unit.aiSuggestedRate : null;
      const displayRate = storedRate ?? Math.round(clampedRate);

      // The effective adjustment is always derived from the stored rate so that
      // Step 0 "Total Adjustment" and Step 3 "Pass 1 Total" agree.
      const displayEffectiveAdj = streetRate > 0 ? (displayRate / streetRate) - 1 : preGuardrailAdjustment;

      // We cannot reliably detect guardrails from old-format stored data —
      // the difference between stored rate and fresh-compute rate reflects
      // different inputs, not a guardrail.  Set guardrailWasApplied=false so
      // the dialog doesn't show a spurious guardrail warning.
      // If the fresh computation itself hit a guardrail flag it for reference.
      const displayGuardrailWasApplied = false;
      const displayGuardrailTrigger: string | null = null;
      const displayGuardrailLimitPct: number | null = null;

      // Build adjustments with both formulas and sentence explanations
      const adjustments = result.adjustments?.map((adj: any) => ({
        ...adj,
        formula: adj.calculation,
        description: getSentenceExplanation(adj.factor.toLowerCase(), aiInputs, adj)
      })) || [];
      
      const calculationPayload = {
        baseRate: streetRate,
        adjustments,
        weights: {
          occupancyPressure: algorithmWeights.occupancy,
          daysVacantDecay: algorithmWeights.daysVacant,
          seasonality: algorithmWeights.seasonality,
          competitorRates: algorithmWeights.competitors,
          stockMarket: algorithmWeights.market,
          inquiryTourVolume: algorithmWeights.demand
        },
        // v2 guardrail fields — preGuardrailAdjustment is set to displayEffectiveAdj
        // (derived from the stored rate) so Step 3 "Pass 1 Total" agrees with the
        // Step 0 "Total Adjustment" headline. The fresh computation's raw total is
        // preserved in freshComputeTotalAdj for reference only.
        preGuardrailAdjustment: displayEffectiveAdj,
        effectiveAdjustment: displayEffectiveAdj,
        guardrailWasApplied: displayGuardrailWasApplied,
        guardrailTrigger: displayGuardrailTrigger,
        guardrailLimitPct: displayGuardrailLimitPct,
        guardrailMinAllowed: Math.round(guardrailMinAllowed),
        guardrailMaxAllowed: guardrailMaxAllowed === Infinity ? null : Math.round(guardrailMaxAllowed),
        totalAdjustment: displayEffectiveAdj,
        freshComputeTotalAdj: preGuardrailAdjustment,
        // Individual factor breakdown came from a fresh recompute with default
        // inputs — totals match the stored rate but factor rows are illustrative.
        breakdownIsApproximate: storedRate !== null,
        preOverrideTotalAdj: result.preOverrideTotalAdj,
        finalRate: displayRate,
        signals: result.signals,
        blendedSignal: result.blendedSignal,
        explanation: generateOverallExplanation(result, aiInputs),
        actualOccupancyRate: serviceLineOcc,
        serviceLine: unit.serviceLine,
        revenueTarget: liveRevenueTarget,
        unitData: {
          unitId: unit.id,
          isOccupied: unit.occupiedYN,
          daysVacant: unit.daysVacant,
          competitorRate: unit.competitorBenchmarkRate
        }
      };

      // Persist — keep stored rate unchanged so rate card stays consistent
      pool.query(
        `UPDATE rent_roll_data SET ai_calculation_details = $1 WHERE id = $2`,
        [JSON.stringify(calculationPayload), unit.id]
      ).catch((e: any) => console.error('[ai-calculation] persist error:', e.message));

      res.json({
        unitId: unit.id,
        roomType: unit.roomType,
        streetRate: streetRate,
        aiSuggestedRate: displayRate,
        calculation: calculationPayload
      });
    } catch (error) {
      console.error('AI calculation fetch error:', error);
      res.status(500).json({ error: 'Failed to fetch AI calculation details' });
    }
  });

