  /**
   * GET /api/metrics/ih-street-variance
   * Returns stored IH-to-Street variance rows for a campus.
   * Query params: locationId (required)
   */
  app.get("/api/metrics/ih-street-variance", async (req: any, res) => {
    try {
      const clientId = req.clientId || 'demo';
      const { locationId } = req.query;
      if (!locationId) return res.status(400).json({ error: "locationId is required" });

      const rows = await db
        .select()
        .from(ihStreetVariance)
        .where(
          and(
            eq(ihStreetVariance.clientId, clientId),
            eq(ihStreetVariance.locationId, locationId as string)
          )
        )
        .orderBy(ihStreetVariance.serviceLine);

      res.json(rows);
    } catch (error) {
      console.error("Error fetching IH-to-street variance:", error);
      res.status(500).json({ error: "Failed to fetch IH-to-street variance" });
    }
  });

  /**
   * POST /api/metrics/ih-street-variance/recalculate
   * Calculates IH-to-Street Rate Variance for single-occupant units at a campus.
   *
   * Single-occupant definition:
   *   - SH (AL, AL/MC, SL, VIL): occupied + roomType != 'Companion'
   *   - HC (HC, HC/MC):           occupied + payorType ILIKE '%PRIVATE%'
   *
   * HC rates are stored daily → converted to monthly (×30.44) before blending.
   * Upserts one row per service line + one 'ALL' row (campus blended total).
   *
   * Query params: locationId (required)
   */
  app.post("/api/metrics/ih-street-variance/recalculate", async (req: any, res) => {
    try {
      const clientId = req.clientId || 'demo';
      const { locationId } = req.query as { locationId?: string };
      if (!locationId) return res.status(400).json({ error: "locationId is required" });

      const HC_DAILY_SL = new Set(['HC', 'HC/MC']);
      const DAYS_PER_MONTH = 30.44;

      // Fetch all occupied single-occupant units for the campus
      const units = await pool.query<{
        service_line: string;
        in_house_rate: number;
        street_rate: number;
      }>(
        `SELECT service_line, in_house_rate, street_rate
         FROM rent_roll_data
         WHERE location_id = $1
           AND client_id = $2
           AND occupied_yn = true
           AND in_house_rate > 0
           AND street_rate > 0
           AND (
             (service_line IN ('AL', 'AL/MC', 'SL', 'VIL') AND room_number !~* '/[B-Zb-z]$')
             OR
             (service_line IN ('HC', 'HC/MC') AND UPPER(COALESCE(payor_type, '')) LIKE '%PRIVATE%')
           )`,
        [locationId, clientId]
      );

      if (units.rows.length === 0) {
        return res.json({ message: "No single-occupant occupied units found", rows: [] });
      }

      // Convert each row to monthly
      const monthly = units.rows.map(u => ({
        serviceLine: u.service_line,
        ihMonthly:  HC_DAILY_SL.has(u.service_line) ? u.in_house_rate * DAYS_PER_MONTH : u.in_house_rate,
        stMonthly:  HC_DAILY_SL.has(u.service_line) ? u.street_rate * DAYS_PER_MONTH   : u.street_rate,
      }));

      // Group by service line
      const bySlMap = new Map<string, { ih: number[]; st: number[] }>();
      for (const row of monthly) {
        if (!bySlMap.has(row.serviceLine)) bySlMap.set(row.serviceLine, { ih: [], st: [] });
        bySlMap.get(row.serviceLine)!.ih.push(row.ihMonthly);
        bySlMap.get(row.serviceLine)!.st.push(row.stMonthly);
      }

      const avg = (arr: number[]) => arr.reduce((s, v) => s + v, 0) / arr.length;

      const results: Array<{ serviceLine: string; variancePct: number; avgIH: number; avgSt: number; count: number }> = [];

      // Per service line
      for (const [sl, { ih, st }] of bySlMap) {
        const avgIH = avg(ih);
        const avgSt = avg(st);
        results.push({ serviceLine: sl, variancePct: ((avgIH - avgSt) / avgSt) * 100, avgIH, avgSt, count: ih.length });
      }

      // Campus total (ALL)
      const allIH = monthly.map(r => r.ihMonthly);
      const allSt = monthly.map(r => r.stMonthly);
      const avgAllIH = avg(allIH);
      const avgAllSt = avg(allSt);
      results.push({ serviceLine: 'ALL', variancePct: ((avgAllIH - avgAllSt) / avgAllSt) * 100, avgIH: avgAllIH, avgSt: avgAllSt, count: monthly.length });

      // Upsert all rows
      const now = new Date();
      for (const r of results) {
        await db
          .insert(ihStreetVariance)
          .values({
            locationId,
            serviceLine: r.serviceLine,
            variancePct: r.variancePct,
            avgInHouseMonthly: r.avgIH,
            avgStreetMonthly: r.avgSt,
            unitCount: r.count,
            clientId,
            calculatedAt: now,
          })
          .onConflictDoUpdate({
            target: [ihStreetVariance.clientId, ihStreetVariance.locationId, ihStreetVariance.serviceLine],
            set: {
              variancePct: r.variancePct,
              avgInHouseMonthly: r.avgIH,
              avgStreetMonthly: r.avgSt,
              unitCount: r.count,
              calculatedAt: now,
            },
          });
      }

      // Sync cache in adjustmentRulesService
      const { preloadIhStreetVariance } = await import('./services/adjustmentRulesService');
      preloadIhStreetVariance(results.map(r => ({
        clientId,
        locationId,
        serviceLine: r.serviceLine,
        variancePct: r.variancePct,
      })));

      res.json({
        message: `Calculated IH-to-Street variance for ${results.length} service lines`,
        rows: results.map(r => ({
          serviceLine: r.serviceLine,
          variancePct: Math.round(r.variancePct * 10) / 10,
          avgInHouseMonthly: Math.round(r.avgIH),
          avgStreetMonthly: Math.round(r.avgSt),
          unitCount: r.count,
        })),
      });
    } catch (error) {
      console.error("Error recalculating IH-to-street variance:", error);
      res.status(500).json({ error: "Failed to recalculate IH-to-street variance" });
    }
  });

  // ============================================
  // CAMPUS METRICS SNAPSHOT (Rule Designer reference data)
  // ============================================

  // GET /api/metrics/campus-snapshot?locationId=xxx
  // Returns all stored campus_metrics rows shaped into a structured snapshot.
  app.get("/api/metrics/campus-snapshot", async (req, res) => {
    try {
      const clientId: string = (req.session as any)?.clientId || 'demo';
      const { locationId } = req.query as { locationId?: string };
      if (!locationId) return res.status(400).json({ error: "locationId is required" });

      const rows = await pool.query<{
        service_line: string | null; room_type: string | null;
        metric_name: string; value: number | null; calculated_at: string | null;
      }>(
        `SELECT service_line, room_type, metric_name, value, calculated_at
         FROM campus_metrics WHERE client_id=$1 AND location_id=$2
         ORDER BY metric_name, service_line NULLS FIRST, room_type NULLS FIRST`,
        [clientId, locationId]
      );

      if (rows.rows.length === 0) return res.json(null);

      const snapshot: any = {
        locationId,
        calculatedAt: rows.rows[0].calculated_at,
        occupancy:          { campus: null, byServiceLine: {} as Record<string,number>, byRoomType: {} as Record<string,number> },
        vacantUnits:        { campus: null, byServiceLine: {} as Record<string,number>, byRoomType: {} as Record<string,number> },
        totalUnits:         { campus: null, byServiceLine: {} as Record<string,number>, byRoomType: {} as Record<string,number> },
        avgDaysVacant:      { campus: null, byServiceLine: {} as Record<string,number>, byRoomType: {} as Record<string,number> },
        competitorVariance: { campus: null, byServiceLine: {} as Record<string,number>, byRoomType: {} as Record<string,number> },
        payerMix: {
          campus: { privatePay: null, medicaid: null, medicare: null },
          byServiceLine: {} as Record<string, { privatePay: number|null; medicaid: number|null; medicare: number|null }>,
        },
        inquiryVolume: {
          campus: { inquiries: null, tours: null },
          byServiceLine: {} as Record<string, { inquiries: number|null; tours: number|null }>,
        },
      };

      const simpleMap: Record<string, string> = {
        occupancy_pct: 'occupancy', vacant_units: 'vacantUnits', total_units: 'totalUnits',
        avg_days_vacant: 'avgDaysVacant', competitor_variance_pct: 'competitorVariance',
      };

      for (const r of rows.rows) {
        const sl = r.service_line; const rt = r.room_type; const v = r.value;
        if (v === null) continue;

        if (simpleMap[r.metric_name]) {
          const obj = snapshot[simpleMap[r.metric_name]];
          if (!sl && !rt) obj.campus = v;
          else if (sl && !rt) obj.byServiceLine[sl] = v;
          else if (!sl && rt) obj.byRoomType[rt] = v;
        }

        if (['private_pay_pct','medicaid_pct','medicare_pct'].includes(r.metric_name)) {
          const field = r.metric_name === 'private_pay_pct' ? 'privatePay'
                      : r.metric_name === 'medicaid_pct' ? 'medicaid' : 'medicare';
          if (!sl && !rt) (snapshot.payerMix.campus as any)[field] = v;
          else if (sl && !rt) {
            if (!snapshot.payerMix.byServiceLine[sl]) snapshot.payerMix.byServiceLine[sl] = { privatePay: null, medicaid: null, medicare: null };
            (snapshot.payerMix.byServiceLine[sl] as any)[field] = v;
          }
        }

        if (['inquiry_count','tour_count'].includes(r.metric_name)) {
          const field = r.metric_name === 'inquiry_count' ? 'inquiries' : 'tours';
          if (!sl && !rt) (snapshot.inquiryVolume.campus as any)[field] = v;
          else if (sl && !rt) {
            if (!snapshot.inquiryVolume.byServiceLine[sl]) snapshot.inquiryVolume.byServiceLine[sl] = { inquiries: null, tours: null };
            (snapshot.inquiryVolume.byServiceLine[sl] as any)[field] = v;
          }
        }
      }

      res.json(snapshot);
    } catch (error) {
      console.error("Error fetching campus snapshot:", error);
      res.status(500).json({ error: "Failed to fetch campus snapshot" });
    }
  });

  // POST /api/metrics/campus-snapshot/recalculate?locationId=xxx
  // Recalculates all campus metrics from rent_roll_data + inquiry_metrics and stores them.
  app.post("/api/metrics/campus-snapshot/recalculate", async (req, res) => {
    try {
      const clientId: string = (req.session as any)?.clientId || 'demo';
      const { locationId } = req.query as { locationId?: string };
      if (!locationId) return res.status(400).json({ error: "locationId is required" });

      // Get latest upload_month for this campus
      const latestRes = await pool.query<{ month: string }>(
        `SELECT MAX(upload_month) AS month FROM rent_roll_data WHERE location_id=$1 AND client_id=$2`,
        [locationId, clientId]
      );
      const latestMonth = latestRes.rows[0]?.month;
      if (!latestMonth) return res.json({ message: "No rent roll data found for this campus", rows: 0 });

      // Fetch all units for the latest month
      const unitsRes = await pool.query<{
        service_line: string; room_type: string; room_number: string; occupied_yn: boolean;
        days_vacant: number; street_rate: number; competitor_final_rate: number; payor_type: string;
      }>(
        `SELECT service_line, room_type, room_number, occupied_yn, days_vacant,
                street_rate, competitor_final_rate, payor_type
         FROM rent_roll_data WHERE location_id=$1 AND client_id=$2 AND upload_month=$3`,
        [locationId, clientId, latestMonth]
      );
      const units = unitsRes.rows;

      // Fetch inquiry/tour volume from the inquiry_metrics table (aggregated)
      const inqRes = await pool.query<{ service_line: string; inq: string; tour: string }>(
        `SELECT service_line, SUM(inquiry_count) AS inq, SUM(tour_count) AS tour
         FROM inquiry_metrics WHERE location_id=$1 AND client_id=$2 GROUP BY service_line`,
        [locationId, clientId]
      );

      // ── Compute metrics ──────────────────────────────────────────────────
      const avgArr = (arr: number[]) => arr.length ? arr.reduce((s, v) => s + v, 0) / arr.length : 0;
      const pctOf  = (n: number, d: number) => d > 0 ? (n / d) * 100 : 0;
      type MetricRow = { sl: string | null; rt: string | null; name: string; val: number };
      const metrics: MetricRow[] = [];

      function pushGroup(sl: string | null, rt: string | null, group: typeof units) {
        const total = group.length;
        if (!total) return;
        const occupied = group.filter(u => u.occupied_yn).length;
        metrics.push({ sl, rt, name: 'total_units',   val: total });
        metrics.push({ sl, rt, name: 'vacant_units',  val: total - occupied });
        metrics.push({ sl, rt, name: 'occupancy_pct', val: pctOf(occupied, total) });

        const vacDays = group.filter(u => !u.occupied_yn && (u.days_vacant || 0) > 0).map(u => u.days_vacant);
        if (vacDays.length) metrics.push({ sl, rt, name: 'avg_days_vacant', val: avgArr(vacDays) });

        const SH_SLS_SNAP = new Set(['AL', 'AL/MC', 'SL', 'VIL']);
        // Apply consistent B-bed exclusion to both sides of the competitor variance
        // so the street rate and competitor rate averages compare identical populations.
        const compUnits = group
          .filter(u => (u.competitor_final_rate || 0) > 100 && (u.street_rate || 0) > 100)
          .filter(u => !(SH_SLS_SNAP.has(u.service_line) && /\/[B-Zb-z]$/.test(u.room_number || '')));
        if (compUnits.length) {
          const avgSt = avgArr(compUnits.map(u => u.street_rate));
          const avgC  = avgArr(compUnits.map(u => u.competitor_final_rate));
          if (avgC > 0) {
            metrics.push({ sl, rt, name: 'competitor_variance_pct',  val: (avgSt - avgC) / avgC * 100 });
            // Street rate to top adjusted comp rate var % — raw % (e.g. 15 means 15% above comp)
            metrics.push({ sl, rt, name: 'street_to_comp_var_pct', val: (avgSt - avgC) / avgC * 100 });
          }
        }

        // Payer mix — campus/SL level only (not RT breakdown)
        if (rt === null) {
          const occ = group.filter(u => u.occupied_yn);
          const n = occ.length;
          if (n > 0) {
            const up = (s: string) => (s || '').toUpperCase();
            metrics.push({ sl, rt, name: 'private_pay_pct', val: pctOf(occ.filter(u => up(u.payor_type).includes('PRIVATE')).length,  n) });
            metrics.push({ sl, rt, name: 'medicaid_pct',    val: pctOf(occ.filter(u => up(u.payor_type).includes('MEDICAID')).length, n) });
            metrics.push({ sl, rt, name: 'medicare_pct',    val: pctOf(occ.filter(u => up(u.payor_type).includes('MEDICARE')).length, n) });
          }
        }
      }

      // Campus level
      pushGroup(null, null, units);

      // Per service line
      const slMap = new Map<string, typeof units>();
      for (const u of units) { const k = u.service_line || 'Other'; if (!slMap.has(k)) slMap.set(k, []); slMap.get(k)!.push(u); }
      for (const [sl, g] of slMap) pushGroup(sl, null, g);

      // Per room type
      const rtMap = new Map<string, typeof units>();
      for (const u of units) { const k = u.room_type || 'Other'; if (!rtMap.has(k)) rtMap.set(k, []); rtMap.get(k)!.push(u); }
      for (const [rt, g] of rtMap) pushGroup(null, rt, g);

      // Inquiry/tour from inquiry_metrics
      const campInq  = inqRes.rows.reduce((s, r) => s + (Number(r.inq)  || 0), 0);
      const campTour = inqRes.rows.reduce((s, r) => s + (Number(r.tour) || 0), 0);
      metrics.push({ sl: null, rt: null, name: 'inquiry_count', val: campInq });
      metrics.push({ sl: null, rt: null, name: 'tour_count',    val: campTour });
      for (const r of inqRes.rows) {
        if (r.service_line) {
          metrics.push({ sl: r.service_line, rt: null, name: 'inquiry_count', val: Number(r.inq)  || 0 });
          metrics.push({ sl: r.service_line, rt: null, name: 'tour_count',    val: Number(r.tour) || 0 });
        }
      }

      // ── Persist: delete old + bulk insert new ────────────────────────────
      await pool.query(`DELETE FROM campus_metrics WHERE client_id=$1 AND location_id=$2`, [clientId, locationId]);
      if (metrics.length > 0) {
        const now = new Date().toISOString();
        const vals: any[] = [];
        const placeholders = metrics.map((m, i) => {
          const b = i * 7;
          vals.push(locationId, m.sl, m.rt, m.name, m.val, clientId, now);
          return `($${b+1},$${b+2},$${b+3},$${b+4},$${b+5},$${b+6},$${b+7})`;
        });
        await pool.query(
          `INSERT INTO campus_metrics (location_id,service_line,room_type,metric_name,value,client_id,calculated_at) VALUES ${placeholders.join(',')}`,
          vals
        );
      }

      // Sync in-memory cache for rule evaluator
      const { preloadCampusMetrics } = await import('./services/adjustmentRulesService');
      preloadCampusMetrics(metrics.map(m => ({
        clientId, locationId, serviceLine: m.sl, roomType: m.rt, metricName: m.name, value: m.val,
      })));

      log(`[campus-snapshot] Calculated ${metrics.length} metric data points for ${locationId}`);
      res.json({ message: `Calculated ${metrics.length} metric data points`, rows: metrics.length });
    } catch (error) {
      console.error("Error recalculating campus snapshot:", error);
      res.status(500).json({ error: "Failed to recalculate campus snapshot" });
    }
  });

  // GET /api/metrics/t3-moveins?locationId=xxx
  // Returns trailing-3-month average unique move-ins per service line.
  // HC and HC/MC are filtered to private pay only.
  // Handles both YYYY-MM-DD and M/D/YYYY date formats.
  app.get("/api/metrics/t3-moveins", async (req, res) => {
    try {
      const clientId: string = (req.session as any)?.clientId || 'demo';
      const { locationId } = req.query as { locationId?: string };
      if (!locationId) return res.status(400).json({ error: "locationId is required" });

      // Resolve location name for clients whose rows use location name not location_id
      const locRes = await pool.query<{ name: string }>(
        `SELECT name FROM locations WHERE id=$1 LIMIT 1`, [locationId]
      );
      const locationName: string | null = locRes.rows[0]?.name || null;

      const result = await pool.query<{
        service_line: string;
        avg_monthly: string;
        months_counted: string;
        latest_month: string | null;
      }>(`
        WITH movein_events AS (
          SELECT DISTINCT ON (location, room_number, move_in_date, service_line)
            service_line,
            payor_type,
            CASE
              WHEN move_in_date ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
                THEN TO_DATE(move_in_date, 'YYYY-MM-DD')
              WHEN move_in_date ~ '^[0-9]{1,2}/[0-9]{1,2}/[0-9]{4}$'
                THEN TO_DATE(move_in_date, 'MM/DD/YYYY')
              ELSE NULL
            END AS movein_dt
          FROM rent_roll_data
          WHERE client_id = $1
            AND (location_id = $2 OR ($3::text IS NOT NULL AND location = $3 AND location_id IS NULL))
            AND move_in_date IS NOT NULL AND move_in_date != ''
        ),
        valid_events AS (
          SELECT service_line, payor_type, movein_dt,
                 DATE_TRUNC('month', movein_dt) AS movein_month
          FROM movein_events
          WHERE movein_dt IS NOT NULL
            AND CASE
              WHEN service_line IN ('HC','HC/MC')
                THEN payor_type ILIKE '%private%' OR payor_type ILIKE '%pvt%'
              ELSE TRUE
            END
        ),
        recent_months AS (
          SELECT DISTINCT movein_month FROM valid_events
          ORDER BY movein_month DESC LIMIT 3
        ),
        monthly_counts AS (
          SELECT e.service_line, e.movein_month, COUNT(*) AS cnt
          FROM valid_events e
          JOIN recent_months r ON e.movein_month = r.movein_month
          GROUP BY e.service_line, e.movein_month
        )
        SELECT
          service_line,
          ROUND(AVG(cnt)::numeric, 2) AS avg_monthly,
          COUNT(DISTINCT movein_month)::text AS months_counted,
          MAX(movein_month)::text AS latest_month
        FROM monthly_counts
        GROUP BY service_line
        ORDER BY avg_monthly DESC
      `, [clientId, locationId, locationName]);

      const byServiceLine: Record<string, number> = {};
      let campus = 0;
      let monthsUsed = 0;
      let asOf: string | null = null;

      for (const row of result.rows) {
        const avg = parseFloat(row.avg_monthly) || 0;
        byServiceLine[row.service_line] = avg;
        campus += avg;
        monthsUsed = Math.max(monthsUsed, parseInt(row.months_counted) || 0);
        if (!asOf && row.latest_month) asOf = row.latest_month;
      }

      res.json({ byServiceLine, campus: parseFloat(campus.toFixed(2)), monthsUsed, asOf });
    } catch (error) {
      console.error("Error fetching T3 move-ins:", error);
      res.status(500).json({ error: "Failed to fetch T3 move-ins" });
    }
  });

  // ============================================
  // ── Manual Rate Overrides ──────────────────────────────────────────────────
  // GET  /api/manual-rate-overrides  — list all for current client
  // POST /api/manual-rate-override   — upsert override for a (location, sl, rt) segment
  // DELETE /api/manual-rate-override/:locationName/:serviceLine/:roomType — remove
  // ──────────────────────────────────────────────────────────────────────────

  app.get("/api/manual-rate-overrides", async (req: any, res) => {
    try {
      const clientId: string = req.session?.clientId || 'demo';
      const { rows } = await pool.query(
        `SELECT id, client_id, location_id, location_name, service_line, room_type, override_rate, notes, created_at, updated_at
         FROM manual_rate_overrides
         WHERE client_id = $1
         ORDER BY location_name, service_line, room_type`,
        [clientId]
      );
      res.json(rows);
    } catch (err) {
      console.error('[manual-rate-overrides] GET error:', err);
      res.status(500).json({ error: 'Failed to fetch manual rate overrides' });
    }
  });

  app.post("/api/manual-rate-override", async (req: any, res) => {
    try {
      const clientId: string = req.session?.clientId || 'demo';
      const { locationId, locationName, serviceLine, roomType, overrideRate, notes } = req.body;
      if (!locationName || !serviceLine || !roomType || overrideRate == null) {
        return res.status(400).json({ error: 'locationName, serviceLine, roomType, overrideRate are required' });
      }
      const rate = Number(overrideRate);
      if (isNaN(rate) || rate <= 0) {
        return res.status(400).json({ error: 'overrideRate must be a positive number' });
      }
      const { rows } = await pool.query(
        `INSERT INTO manual_rate_overrides (client_id, location_id, location_name, service_line, room_type, override_rate, notes, updated_at)
         VALUES ($1, $2, $3, $4, $5, $6, $7, now())
         ON CONFLICT (client_id, location_name, service_line, room_type)
         DO UPDATE SET override_rate = EXCLUDED.override_rate,
                       location_id   = EXCLUDED.location_id,
                       notes         = EXCLUDED.notes,
                       updated_at    = now()
         RETURNING *`,
        [clientId, locationId || null, locationName, serviceLine, roomType, rate, notes || null]
      );
      // Bust the server-side reference-data cache and the AI commentary cache
      // so the next GET reflects the new override immediately (not stale data).
      invalidateRefDataCache();
      warmRefDataCacheForClient(clientId);
      pool.query(`DELETE FROM ai_commentary_cache WHERE cache_key LIKE $1`, [`pc-commentary:${clientId}:%`])
        .catch((err: any) => console.error('[manual-rate-overrides] commentary cache purge error:', err));
      res.json(rows[0]);
    } catch (err) {
      console.error('[manual-rate-overrides] POST error:', err);
      res.status(500).json({ error: 'Failed to save manual rate override' });
    }
  });

  app.delete("/api/manual-rate-override/:locationName/:serviceLine/:roomType", async (req: any, res) => {
    try {
      const clientId: string = req.session?.clientId || 'demo';
      const { locationName, serviceLine, roomType } = req.params;
      await pool.query(
        `DELETE FROM manual_rate_overrides
         WHERE client_id = $1 AND location_name = $2 AND service_line = $3 AND room_type = $4`,
        [clientId, locationName, serviceLine, roomType]
      );
      invalidateRefDataCache();
      warmRefDataCacheForClient(clientId);
      pool.query(`DELETE FROM ai_commentary_cache WHERE cache_key LIKE $1`, [`pc-commentary:${clientId}:%`])
        .catch((err: any) => console.error('[manual-rate-overrides] commentary cache purge error:', err));
      res.json({ success: true });
    } catch (err) {
      console.error('[manual-rate-overrides] DELETE error:', err);
      res.status(500).json({ error: 'Failed to delete manual rate override' });
    }
  });

  // RULE PERFORMANCE OVER TIME
  // GET /api/rule-performance?start=YYYY-MM-DD&end=YYYY-MM-DD
  // One summary row per adjustment rule applied in the timeframe, with drill-down
  // detail rows at the (location, service line, room type) level.
  app.get("/api/rule-performance", async (req, res) => {
    try {
      // Allow internal warm-up requests to specify the client directly.
      // Accepts either the optional SEED_SECRET or the always-available INTERNAL_WARMUP_TOKEN.
      const warmupClient = req.headers['x-warmup-client'] as string | undefined;
      const warmupSecret = req.headers['x-seed-secret'] as string | undefined;
      const internalToken = req.headers['x-internal-warmup-token'] as string | undefined;
      const warmupOk = !!warmupClient && (
        (!!process.env.SEED_SECRET && warmupSecret === process.env.SEED_SECRET) ||
        (internalToken === INTERNAL_WARMUP_TOKEN)
      );
      const clientId: string = warmupOk ? warmupClient! : ((req.session as any)?.clientId || 'demo');
      const q = req.query as Record<string, string | undefined>;
      const dateRe = /^\d{4}-\d{2}-\d{2}$/;
      if ((q.start && !dateRe.test(q.start)) || (q.end && !dateRe.test(q.end))) {
        return res.status(400).json({ error: 'start and end must be YYYY-MM-DD dates' });
      }
      const now = new Date();
      const endDate = q.end ? new Date(q.end + 'T23:59:59') : now;
      const startDate = q.start ? new Date(q.start + 'T00:00:00') : new Date(now.getTime() - 180 * 24 * 3600 * 1000);
      if (isNaN(startDate.getTime()) || isNaN(endDate.getTime())) {
        return res.status(400).json({ error: 'Invalid start or end date' });
      }

      // Page-level filters (mirrors /api/reference-data): service line, regions,
      // divisions, locations.
      const csv = (v?: string) => (v ? v.split(',').map(s => s.trim()).filter(Boolean) : []);
      const serviceLine = q.serviceLine && q.serviceLine !== 'All' ? q.serviceLine : null;
      const regions     = csv(q.regions);
      const divisions   = csv(q.divisions);
      const locations   = csv(q.locations);

      // ── Cache check (purged by purgeRuleCaches on any rule mutation) ──
      const perfCacheKey = `rule-perf:${clientId}:${JSON.stringify({
        s: startDate.toISOString().slice(0, 10), e: endDate.toISOString().slice(0, 10),
        sl: serviceLine, r: regions, d: divisions, l: locations,
      })}`;
      const cachedPerf = getCachedAnalytics(perfCacheKey);
      if (cachedPerf) {
        res.setHeader('X-Cache', 'HIT');
        return res.json(cachedPerf);
      }

      const params: any[] = [clientId, startDate, endDate];
      let where = `rr.client_id = $1
          AND rr.applied_rule_name IS NOT NULL AND rr.rule_adjusted_rate > 0
          AND COALESCE(rr.rule_rate_calculated_at, TO_DATE(rr.upload_month || '-01', 'YYYY-MM-DD')) BETWEEN $2 AND $3`;
      if (serviceLine)      { params.push(serviceLine); where += ` AND rr.service_line = $${params.length}`; }
      if (locations.length) { params.push(locations);   where += ` AND rr.location = ANY($${params.length})`; }
      if (regions.length)   { params.push(regions);     where += ` AND loc.region = ANY($${params.length})`; }
      if (divisions.length) { params.push(divisions);   where += ` AND loc.division = ANY($${params.length})`; }

      // Units that had a rule applied at any point in the selected window, across ALL
      // upload months (not just the latest snapshot). The application date is
      // rule_rate_calculated_at when present; older imports lack that timestamp, so we
      // fall back to the row's own upload_month (first of month) — deterministic and
      // tenant-safe (no reliance on the global adjustment_rules table for dates).
      // Dedupe: one row per (location, room_number, applied_rule_name), keeping the
      // most recent upload_month so occupancy/move-in status is as current as possible.
      const unitRes = await pool.query(`
        SELECT DISTINCT ON (rr.location, rr.room_number, rr.applied_rule_name)
               rr.location, rr.service_line, rr.room_type, rr.room_number,
               rr.occupied_yn, rr.street_rate, rr.in_house_rate, rr.rule_adjusted_rate,
               rr.applied_rule_name, rr.move_in_date, rr.days_vacant, rr.upload_month,
               rr.payor_type,
               COALESCE(rr.rule_rate_calculated_at, TO_DATE(rr.upload_month || '-01', 'YYYY-MM-DD')) AS applied_at
        FROM rent_roll_data rr
        LEFT JOIN locations loc ON loc.client_id = rr.client_id AND loc.name = rr.location
        WHERE ${where}
        ORDER BY rr.location, rr.room_number, rr.applied_rule_name, rr.upload_month DESC
      `, params);

      // Expected days-to-sell baseline: avg historical days_vacant per (service_line, room_type)
      const baseParams: any[] = [clientId];
      let baseWhere = `rr.client_id = $1 AND rr.days_vacant > 0 AND rr.days_vacant < 730`;
      if (serviceLine)      { baseParams.push(serviceLine); baseWhere += ` AND rr.service_line = $${baseParams.length}`; }
      if (locations.length) { baseParams.push(locations);   baseWhere += ` AND rr.location = ANY($${baseParams.length})`; }
      if (regions.length)   { baseParams.push(regions);     baseWhere += ` AND loc.region = ANY($${baseParams.length})`; }
      if (divisions.length) { baseParams.push(divisions);   baseWhere += ` AND loc.division = ANY($${baseParams.length})`; }
      const [baseRes, activeRuleMetaRes] = await Promise.all([
        pool.query<{ service_line: string; room_type: string; avg_dv: number }>(`
          SELECT rr.service_line, rr.room_type, AVG(rr.days_vacant) AS avg_dv
          FROM rent_roll_data rr
          LEFT JOIN locations loc ON loc.client_id = rr.client_id AND loc.name = rr.location
          WHERE ${baseWhere}
          GROUP BY rr.service_line, rr.room_type
        `, baseParams),
        pool.query(`
          SELECT DISTINCT ON (name) id, name, action, trigger, service_line, service_lines, location_id, effective_date, created_at, is_active, priority
          FROM adjustment_rules
          WHERE is_historical IS NOT TRUE
            AND (
              (location_id IS NOT NULL AND location_id IN (SELECT id FROM locations WHERE client_id = $1))
              OR (location_id IS NULL AND client_id = $1)
            )
          ORDER BY name
        `, [clientId]),
      ]);

      // ---- Rule category map (push / hold / concession-al / concession-sl) ----
      // Shared module-level implementation (see computeRuleCategory above).
      const getRuleCategoryFn = computeRuleCategory;
      const categoryMap = new Map<string, string>();
      for (const ar of activeRuleMetaRes.rows) {
        categoryMap.set(ar.name, getRuleCategoryFn(ar.action, ar.trigger, ar.service_line || ''));
      }
      const baseline = new Map<string, number>();
      for (const b of baseRes.rows) baseline.set(`${b.service_line}|${b.room_type}`, Number(b.avg_dv));
      const slBaseline = new Map<string, { sum: number; n: number }>();
      for (const b of baseRes.rows) {
        const cur = slBaseline.get(b.service_line) || { sum: 0, n: 0 };
        cur.sum += Number(b.avg_dv); cur.n += 1;
        slBaseline.set(b.service_line, cur);
      }
      const expectedFor = (sl: string, rt: string): number | null => {
        const exact = baseline.get(`${sl}|${rt}`);
        if (exact != null) return exact;
        const s = slBaseline.get(sl);
        return s && s.n > 0 ? s.sum / s.n : null;
      };

      const parseMoveIn = (s: string | null): Date | null => {
        if (!s) return null;
        let m = s.match(/^(\d{4})-(\d{2})-(\d{2})/);
        if (m) return new Date(+m[1], +m[2] - 1, +m[3]);
        m = s.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})/);
        if (m) return new Date(+m[3], +m[1] - 1, +m[2]);
        return null;
      };
      // ---- T3 realized-revenue series ---------------------------------------
      // Monthly realized revenue per (location, service_line, room_type) group:
      // sum of in-house rates for OCCUPIED units in each upload_month snapshot
      // (HC / HC/MC daily rates converted to monthly). This captures both rate
      // AND occupancy changes, which the old street-rate-delta method did not.
      const revParams: any[] = [clientId];
      let revWhere = `rr.client_id = $1`;
      if (serviceLine)      { revParams.push(serviceLine); revWhere += ` AND rr.service_line = $${revParams.length}`; }
      if (locations.length) { revParams.push(locations);   revWhere += ` AND rr.location = ANY($${revParams.length})`; }
      if (regions.length)   { revParams.push(regions);     revWhere += ` AND loc.region = ANY($${revParams.length})`; }
      if (divisions.length) { revParams.push(divisions);   revWhere += ` AND loc.division = ANY($${revParams.length})`; }
      const revRes = await pool.query<{ upload_month: string; location: string; service_line: string; room_type: string; revenue: number; occ_count: number; occ_all: number; total_count: number }>(`
        SELECT rr.upload_month, rr.location, rr.service_line, rr.room_type,
               SUM(CASE WHEN rr.occupied_yn
                        AND (rr.service_line NOT IN ('HC','HC/MC')
                             OR rr.payor_type ILIKE '%private%' OR rr.payor_type ILIKE '%pvt%')
                        THEN CASE WHEN rr.service_line IN ('HC','HC/MC') THEN rr.in_house_rate * 30.4 ELSE rr.in_house_rate END
                        ELSE 0 END) AS revenue,
               COUNT(*) FILTER (WHERE rr.occupied_yn
                        AND (rr.service_line NOT IN ('HC','HC/MC')
                             OR rr.payor_type ILIKE '%private%' OR rr.payor_type ILIKE '%pvt%')) AS occ_count,
               COUNT(*) FILTER (WHERE rr.occupied_yn) AS occ_all,
               COUNT(*) AS total_count
        FROM rent_roll_data rr
        LEFT JOIN locations loc ON loc.client_id = rr.client_id AND loc.name = rr.location
        WHERE ${revWhere}
        GROUP BY rr.upload_month, rr.location, rr.service_line, rr.room_type
        ORDER BY rr.upload_month
      `, revParams);
      // groupKey -> sorted [{month, revenue, occ}]
      const revSeries = new Map<string, { month: string; revenue: number; occ: number; occAll: number; total: number }[]>();
      for (const r of revRes.rows) {
        const k = `${r.location}|${r.service_line}|${r.room_type}`;
        if (!revSeries.has(k)) revSeries.set(k, []);
        revSeries.get(k)!.push({ month: r.upload_month, revenue: Number(r.revenue), occ: Number(r.occ_count), occAll: Number(r.occ_all), total: Number(r.total_count) });
      }

      // ---- T3 move-in event series -------------------------------------------
      // Distinct move-in events per (location, service_line, room_type) by month:
      // each unique (room, move_in_date) counts once across all snapshots, so past
      // residents captured in older snapshots are included.
      // groupKey -> (YYYY-MM -> move-in count). Prefer imported move-in/out
      // event data (authoritative, from the Move Ins & Outs Detail upload);
      // fall back to distinct rent-roll move_in_date events otherwise.
      const { hasMoveInOutEvents: hasMioEvents, getMonthlyMoveInSeriesFromEvents } = await import('./services/moveInOutService');
      let miSeries = new Map<string, Map<string, number>>();

      const monthOf = (d: Date) => `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}`;
      if (await hasMioEvents(clientId)) {
        miSeries = await getMonthlyMoveInSeriesFromEvents(clientId);
      } else {
        const miRes = await pool.query<{ location: string; service_line: string; room_type: string; move_in_date: string }>(`
          SELECT DISTINCT rr.location, rr.service_line, rr.room_type, rr.room_number, rr.move_in_date
          FROM rent_roll_data rr
          LEFT JOIN locations loc ON loc.client_id = rr.client_id AND loc.name = rr.location
          WHERE ${revWhere} AND rr.move_in_date IS NOT NULL AND rr.move_in_date <> ''
        `, revParams);
        for (const r of miRes.rows) {
          const mi = parseMoveIn(r.move_in_date);
          if (!mi) continue;
          const k = `${r.location}|${r.service_line}|${r.room_type}`;
          const m = monthOf(mi);
          if (!miSeries.has(k)) miSeries.set(k, new Map());
          const mm = miSeries.get(k)!;
          mm.set(m, (mm.get(m) || 0) + 1);
        }
      }
      // Avg move-ins/month over the same T3 windows the revenue calc uses: the
      // group's snapshot months anchor the observable window (months with zero
      // move-ins count as zero only when a rent roll snapshot exists for them).
      const t3MoveInsFor = (groupKey: string, appliedMonth: string): { before: number; after: number } | null => {
        const snaps = revSeries.get(groupKey);
        if (!snaps || snaps.length === 0) return null;
        const beforeMonths = snaps.filter(p => p.month < appliedMonth).slice(-3).map(p => p.month);
        const afterMonths = snaps.filter(p => p.month >= appliedMonth).slice(0, 3).map(p => p.month);
        if (beforeMonths.length === 0 || afterMonths.length === 0) return null;
        const mm = miSeries.get(groupKey);
        const sum = (months: string[]) => months.reduce((s, m) => s + (mm?.get(m) || 0), 0);
        return { before: sum(beforeMonths) / beforeMonths.length, after: sum(afterMonths) / afterMonths.length };
      };
      // True occupancy % over the T3 "before" window: ALL occupied units ÷ ALL
      // units in the group's snapshots (matched numerator/denominator — never
      // mixes the private-pay-only revenue occ count with impacted-unit counts).
      const t3OccPctBefore = (groupKey: string, appliedMonth: string): number | null => {
        const snaps = revSeries.get(groupKey);
        if (!snaps || snaps.length === 0) return null;
        const before = snaps.filter(p => p.month < appliedMonth).slice(-3);
        const occ = before.reduce((s, p) => s + p.occAll, 0);
        const tot = before.reduce((s, p) => s + p.total, 0);
        return tot > 0 ? (occ / tot) * 100 : null;
      };
      type T3 = { before: number; after: number; occBefore: number; occAfter: number; occAdjusted: boolean; occEffect: number; monthsBefore: number; monthsAfter: number; delta: number; extrapolated: boolean };
      // T3 delta for a group: avg monthly revenue over the last 3 snapshot months
      // strictly BEFORE the applied month vs. avg over the (up to) first 3 snapshot
      // months FROM the applied month onward. If fewer than 3 post-change months
      // exist yet, the average of the elapsed months stands in for the 3-month
      // average (i.e. extrapolated to a monthly run-rate).
      // Also tracks avg occupied unit count before/after to distinguish rate vs occupancy changes.
      // When occupancy declined, adds 1 unit's revenue back to the "after" figure as a
      // conservative recovery assumption (occupancy loss may be unrelated to the rate change).
      const t3For = (groupKey: string, appliedMonth: string, isHistorical: boolean): T3 | null => {
        const series = revSeries.get(groupKey);
        if (!series || series.length === 0) return null;
        const before = series.filter(p => p.month < appliedMonth).slice(-3);
        const after = series.filter(p => p.month >= appliedMonth).slice(0, 3);
        if (before.length === 0 || after.length === 0) return null;
        const avg = (a: { revenue: number }[]) => a.reduce((s, p) => s + p.revenue, 0) / a.length;
        const avgOcc = (a: { occ: number }[]) => a.reduce((s, p) => s + p.occ, 0) / a.length;
        const b = avg(before), rawAft = avg(after);
        const occB = avgOcc(before), occA = avgOcc(after);
        // Decompose the revenue swing into a RATE effect and an OCCUPANCY effect and
        // attribute ONLY the rate effect to the rule. A pricing rule changes what a room
        // sells for, not how many rooms fill; census/turnover swings are worth far more
        // than any rate move, so a raw total-revenue delta measures occupancy, not pricing.
        // (That is why a concession rule could show a large gain and an increase rule a
        // large loss.) Holding occupancy constant at the pre-change level isolates price:
        //   rate effect = (revenue-per-occupied-unit after - before) x occupied units before
        // This matches the occupancy-adjusted basis the win-rate header already uses, so
        // the headline win rate and the impact column can no longer disagree.
        // If either window has no occupied units there is no realized rate to compare,
        // so no rate effect can be measured. Returning the raw revenue delta here would
        // silently reintroduce the occupancy-contaminated number this decomposition
        // exists to remove (a zero-before group would book every newly occupied unit as
        // "rate impact"; a zero-after group would book the whole vacancy loss). Report no
        // T3 result instead and let the caller fall back to the projected rate delta.
        if (occB <= 0 || occA <= 0) return null;
        const rateBefore = b / occB;
        const rateAfter  = rawAft / occA;
        // "after" is expressed at constant occupancy so that after - before == rate effect
        // and the before/after figures in the calc dialog reconcile with the impact shown.
        const aft = rateAfter * occB;
        const occEffect = (occA - occB) * rateAfter;
        return { before: b, after: aft, occBefore: occB, occAfter: occA, occAdjusted: false, occEffect, monthsBefore: before.length, monthsAfter: after.length, delta: aft - b, extrapolated: after.length < 3 };
      };

      // Build service-line move-in rates: only new admissions pay the adjusted rate,
      // so rate-delta impact = affectedUnits × moveInRate × Δrate (not sum of all units).
      const slMoveInRate = new Map<string, number>();
      {
        const ctxCacheKey = `ruleImpactCtx:${clientId}`;
        let impCtx = getCachedAnalytics(ctxCacheKey);
        if (!impCtx) {
          impCtx = await buildRuleImpactContext(clientId);
          if (impCtx) setCachedAnalytics(ctxCacheKey, impCtx);
        }
        if (impCtx?.slMoveInRate) {
          for (const [sl, rate] of Array.from((impCtx.slMoveInRate as Map<string,number>).entries())) {
            slMoveInRate.set(sl, rate);
          }
        }
      }

      type Agg = {
        unitsImpacted: number; unitsSold: number;
        dtsSum: number; dtsN: number;          // actual days-to-sell (sold units, post-rule)
        expSum: number; expN: number;          // expected baseline for sold units
        allExpSum: number; allExpN: number;    // expected baseline for ALL impacted units (fallback)
        earliestApplied: Date | null;
        projRateSum: number;                   // fallback: expected move-ins × Δrate (new admissions only)
        streetRateMirSum: number;              // expected move-ins × street rate (the "before" figure)
        moveInsTotal: number;                  // expected move-ins/mo for qualifying units
        projDtsSum: number;                    // fallback: sum of days_vacant for occupied units
        projDtsN: number;                      // fallback: count of occupied units with days_vacant
      };
      const newAgg = (): Agg => ({
        unitsImpacted: 0, unitsSold: 0, dtsSum: 0, dtsN: 0, expSum: 0, expN: 0,
        allExpSum: 0, allExpN: 0,
        earliestApplied: null, projRateSum: 0, streetRateMirSum: 0, moveInsTotal: 0, projDtsSum: 0, projDtsN: 0,
      });
      // ruleName -> summary agg; ruleName -> detailKey -> agg
      const summary = new Map<string, Agg>();
      const details = new Map<string, Map<string, Agg & { location: string; serviceLine: string; roomType: string }>>();
      // HC / HC/MC pricing only affects Private Pay residents — Medicare, Medicaid,
      // and Insurance payers are reimbursed at fixed rates set outside our control.
      const isHcSl = (sl: string | null) => sl === 'HC' || sl === 'HC/MC';
      const isPrivatePay = (p: string | null | undefined) => !!p && /private|pvt/i.test(p);

      // Stacking weights: when rules stack on a unit ("A + B"), each rule gets a
      // 1/n proportional share of that unit. Group T3 impact is then distributed
      // across the rules that touched the group by their share of impacted units.
      // ruleName|groupKey -> { weight, earliestApplied }
      const ruleGroupWeight = new Map<string, { weight: number; earliestApplied: Date }>();
      const groupTotalWeight = new Map<string, number>();

      for (const u of unitRes.rows) {
        const ruleNames: string[] = String(u.applied_rule_name).split(' + ').map((s: string) => s.trim()).filter(Boolean);
        if (ruleNames.length === 0) continue;
        const appliedAt = new Date(u.applied_at);
        const dKey = `${u.location}|${u.service_line}|${u.room_type}`;
        const share = 1 / ruleNames.length; // proportional split when rules stack
        // Projected monthly rate delta: rule_adjusted_rate - street_rate gives the
        // actual Δ imposed by the rule (both are derived from the same base).
        // Using in_house_rate (=0 for vacant units) would inflate the delta to the
        // full rate rather than just the rule's adjustment.
        const isDaily = ['HC', 'HC/MC'].includes(u.service_line);
        const rateMultiplier = isDaily ? 30.4 : 1;
        const streetRate = Number(u.street_rate) || 0;
        const ruleRate = Number(u.rule_adjusted_rate) || 0;
        const projRateDelta = (ruleRate - streetRate) * rateMultiplier;
        const daysVacant = u.days_vacant != null ? Number(u.days_vacant) : null;
        for (const rn of ruleNames) {
          const moveIn = parseMoveIn(u.move_in_date);
          const soldAfterRule = !!(u.occupied_yn && moveIn && moveIn >= appliedAt && moveIn <= endDate);
          const dts = soldAfterRule && moveIn ? Math.max(0, Math.round((moveIn.getTime() - appliedAt.getTime()) / 86400000)) : null;
          const expected = expectedFor(u.service_line, u.room_type);

          const bump = (a: Agg) => {
            a.unitsImpacted += 1;
            if (!a.earliestApplied || appliedAt < a.earliestApplied) a.earliestApplied = appliedAt;
            // Projected rate delta: only new admissions pay the adjusted rate.
            // For HC/HC/MC: occupied non-private-pay units (Medicare, Medicaid, Insurance)
            // are on fixed reimbursement — their rates are unaffected. Only private pay
            // occupied units and all vacant units (future payer unknown, move-in rate
            // already reflects private pay fraction) contribute to the impact.
            const payerOkForRate = !isHcSl(u.service_line) || !u.occupied_yn || isPrivatePay(u.payor_type);
            const mir = payerOkForRate ? (slMoveInRate.get(u.service_line) ?? 0) : 0;
            a.projRateSum      += projRateDelta * share * mir;
            a.streetRateMirSum += streetRate * rateMultiplier * share * mir;
            a.moveInsTotal     += share * mir;
            // Projected DTS: use days_vacant for currently-occupied units (their actual sell time)
            if (u.occupied_yn && daysVacant != null && daysVacant > 0 && daysVacant < 730) {
              a.projDtsSum += daysVacant;
              a.projDtsN += 1;
            }
            // Accumulate baseline expected DTS for ALL units (fallback when no sold-after-rule units)
            if (expected != null) { a.allExpSum += expected; a.allExpN += 1; }
            if (soldAfterRule) {
              a.unitsSold += 1;
              if (dts != null) { a.dtsSum += dts; a.dtsN += 1; }
              if (expected != null) { a.expSum += expected; a.expN += 1; }
            }
          };

          if (!summary.has(rn)) summary.set(rn, newAgg());
          bump(summary.get(rn)!);

          if (!details.has(rn)) details.set(rn, new Map());
          const dMap = details.get(rn)!;
          if (!dMap.has(dKey)) dMap.set(dKey, { ...newAgg(), location: u.location, serviceLine: u.service_line, roomType: u.room_type });
          bump(dMap.get(dKey)!);

          const rgKey = `${rn}|${dKey}`;
          const rg = ruleGroupWeight.get(rgKey);
          if (!rg) ruleGroupWeight.set(rgKey, { weight: share, earliestApplied: appliedAt });
          else { rg.weight += share; if (appliedAt < rg.earliestApplied) rg.earliestApplied = appliedAt; }
          groupTotalWeight.set(dKey, (groupTotalWeight.get(dKey) || 0) + share);
        }
      }

      // ---- Historical rules (imported pricing records) --------------------
      // Historical rules were never applied to rent roll rows, so they have no
      // applied_rule_name footprint. Synthesize performance rows by matching
      // units through the rule's scope (location + action.filters) and using
      // effective_date as the applied date.
      const histParams: any[] = [clientId, startDate, endDate];
      let histWhere = `ar.is_historical = true AND ar.effective_date BETWEEN $2 AND $3`;
      if (locations.length) { histParams.push(locations); histWhere += ` AND loc.name = ANY($${histParams.length})`; }
      if (regions.length)   { histParams.push(regions);   histWhere += ` AND loc.region = ANY($${histParams.length})`; }
      if (divisions.length) { histParams.push(divisions); histWhere += ` AND loc.division = ANY($${histParams.length})`; }
      const histRes = await pool.query(`
        SELECT ar.name, ar.effective_date, ar.action, ar.trigger,
               ar.service_line AS rule_service_line, ar.service_lines AS rule_service_lines,
               loc.name AS location_name
        FROM adjustment_rules ar
        JOIN locations loc ON loc.client_id = $1
          AND (
            (ar.location_id IS NOT NULL AND loc.id = ar.location_id)
            OR
            (ar.location_id IS NULL AND ar.name LIKE 'Historical: ' || loc.name || ' %')
          )
        WHERE ${histWhere}
      `, histParams);

      // Historical rules category: populate categoryMap from each rule's action+trigger
      for (const hr of histRes.rows) {
        if (!categoryMap.has(hr.name)) {
          const sls: string[] = Array.isArray(hr.rule_service_lines) && hr.rule_service_lines.length
            ? hr.rule_service_lines
            : (hr.rule_service_line ? [hr.rule_service_line] : []);
          const sl = sls[0] || '';
          // Timezone-safe cycle month: pg returns DATE as a local-midnight Date
          // object (monthOf reads local components); string fallback slices YYYY-MM.
          const cycle = hr.effective_date instanceof Date
            ? monthOf(hr.effective_date)
            : String(hr.effective_date).slice(0, 7);
          categoryMap.set(hr.name, getRuleCategoryFn(hr.action, hr.trigger, sl, cycle));
        }
      }

      // Historical rules use their OWN attribution pool so synthetic rows never
      // dilute the T3 credit of rules genuinely applied via applied_rule_name.
      const histRuleNames = new Set<string>();
      const groupTotalWeightHist = new Map<string, number>();

      if (histRes.rows.length > 0) {
        const histLocs = Array.from(new Set(histRes.rows.map((r: any) => r.location_name)));

        // Latest snapshot per unit — used for CURRENT occupancy / move-in status.
        const histUnitRes = await pool.query(`
          SELECT DISTINCT ON (rr.location, rr.room_number)
                 rr.location, rr.service_line, rr.room_type, rr.room_number,
                 rr.occupied_yn, rr.move_in_date, rr.in_house_rate, rr.street_rate, rr.days_vacant, rr.payor_type
          FROM rent_roll_data rr
          WHERE rr.client_id = $1 AND rr.location = ANY($2)
          ORDER BY rr.location, rr.room_number, rr.upload_month DESC
        `, [clientId, histLocs]);
        const latestByKey = new Map<string, any>();
        for (const u of histUnitRes.rows) latestByKey.set(`${u.location}|${u.room_number}`, u);

        // Time-aligned cohorts: units as they existed in the snapshot at (or just
        // before) each rule's effective month, so the matched population reflects
        // the units/attributes present when the pricing change took effect.
        const effMonths = Array.from(new Set(histRes.rows.map((r: any) => monthOf(new Date(r.effective_date)))));
        // effMonth -> location -> cohort units (attributes as of that snapshot)
        const cohortByMonth = new Map<string, Map<string, any[]>>();
        for (const em of effMonths) {
          const cRes = await pool.query(`
            SELECT rr.location, rr.service_line, rr.room_type, rr.room_number, rr.occupied_yn, rr.payor_type
            FROM rent_roll_data rr
            WHERE rr.client_id = $1 AND rr.location = ANY($2)
              AND rr.upload_month = (
                SELECT MAX(upload_month) FROM rent_roll_data
                WHERE client_id = $1 AND location = ANY($2) AND upload_month < $3
              )
          `, [clientId, histLocs, em]);
          const byLoc = new Map<string, any[]>();
          for (const u of cRes.rows) {
            if (!byLoc.has(u.location)) byLoc.set(u.location, []);
            byLoc.get(u.location)!.push(u);
          }
          cohortByMonth.set(em, byLoc);
        }

        for (const hr of histRes.rows) {
          const filters = (hr.action && hr.action.filters) || {};
          const ruleSLs: string[] = Array.isArray(filters.serviceLine) && filters.serviceLine.length
            ? filters.serviceLine
            : (hr.rule_service_line ? [hr.rule_service_line] : []);
          // Respect the page service-line filter
          if (serviceLine && ruleSLs.length && !ruleSLs.includes(serviceLine)) continue;
          // Normalize raw room types from the rule filter to match standardized DB values
          const ruleRTs: string[] = Array.isArray(filters.roomType) && filters.roomType.length
            ? [...new Set((filters.roomType as string[]).map(rt => normalizeRoomType(rt)))]
            : [];
          const appliedAt = new Date(hr.effective_date);
          const rn = hr.name as string;
          const cohort = cohortByMonth.get(monthOf(appliedAt))?.get(hr.location_name) || [];
          // HC / HC/MC pricing only affects Private Pay residents (isHcSl / isPrivatePay
          // defined above). Occupied non-private-pay units are excluded from the impacted set.
          const candidates = cohort.filter((u: any) =>
            (!ruleSLs.length || ruleSLs.includes(u.service_line)) &&
            (!ruleRTs.length || ruleRTs.includes(u.room_type)) &&
            (!serviceLine || u.service_line === serviceLine) &&
            (!isHcSl(u.service_line) || !u.occupied_yn || isPrivatePay(u.payor_type))
          );
          if (!candidates.length) continue;
          histRuleNames.add(rn);

          for (const u of candidates) {
            const dKey = `${u.location}|${u.service_line}|${u.room_type}`;
            // Current occupancy/move-in comes from the latest snapshot of the same unit
            const latest = latestByKey.get(`${u.location}|${u.room_number}`);
            const moveIn = parseMoveIn(latest?.move_in_date ?? null);
            // Primary: unit was vacant in the cohort snapshot but is now occupied = moved in after rule
            // Fallback: date-based check when move_in_date is reliable
            const wasVacantAtRule = !u.occupied_yn;
            const isNowOccupied = !!(latest?.occupied_yn);
            // HC / HC/MC: only Private Pay move-ins pay the adjusted street rate,
            // so move-ins by other payer types don't count toward realized impact.
            const payerOk = !isHcSl(u.service_line) || isPrivatePay(latest?.payor_type);
            const soldAfterRule = payerOk && ((wasVacantAtRule && isNowOccupied) ||
              !!(latest?.occupied_yn && moveIn && moveIn >= appliedAt && moveIn <= endDate));
            const dts = soldAfterRule && moveIn ? Math.max(0, Math.round((moveIn.getTime() - appliedAt.getTime()) / 86400000)) : null;
            const expected = expectedFor(u.service_line, u.room_type);
            // Projected fallback: compute actual rate delta from the rule's adjustment.
            // Use street_rate as the base (covers vacant units where in_house_rate is null).
            const isDaily = ['HC', 'HC/MC'].includes(u.service_line);
            const rawRate = latest
              ? (Number(latest.in_house_rate) || Number(latest.street_rate) || 0)
              : 0;
            const baseMonthlyRate = rawRate * (isDaily ? 30.4 : 1);
            // Support both action formats: new {adjustmentType,adjustmentValue} and old {type,value}
            const adjType: string = hr.action?.adjustmentType || hr.action?.type || 'percentage';
            const adjValue = Number(hr.action?.adjustmentValue ?? hr.action?.value ?? 0);
            const histProjRate = adjType === 'percentage'
              ? baseMonthlyRate * (adjValue / 100)
              : adjType === 'absolute'
                ? (isDaily ? adjValue * 30.4 : adjValue)
                : 0;
            const histDaysVacant = latest?.days_vacant != null ? Number(latest.days_vacant) : null;

            const bump = (a: Agg) => {
              a.unitsImpacted += 1;
              if (!a.earliestApplied || appliedAt < a.earliestApplied) a.earliestApplied = appliedAt;
              // Projected rate delta: only new admissions pay the adjusted rate.
              const mirH = slMoveInRate.get(u.service_line) ?? 0;
              a.projRateSum      += histProjRate * mirH;
              a.streetRateMirSum += baseMonthlyRate * mirH;
              a.moveInsTotal     += mirH;
              if (latest?.occupied_yn && histDaysVacant != null && histDaysVacant > 0 && histDaysVacant < 730) {
                a.projDtsSum += histDaysVacant;
                a.projDtsN += 1;
              }
              // Accumulate baseline expected DTS for ALL units (fallback when no sold-after-rule units)
              if (expected != null) { a.allExpSum += expected; a.allExpN += 1; }
              if (soldAfterRule) {
                a.unitsSold += 1;
                if (dts != null) { a.dtsSum += dts; a.dtsN += 1; }
                if (expected != null) { a.expSum += expected; a.expN += 1; }
              }
            };

            if (!summary.has(rn)) summary.set(rn, newAgg());
            bump(summary.get(rn)!);

            if (!details.has(rn)) details.set(rn, new Map());
            const dMap = details.get(rn)!;
            if (!dMap.has(dKey)) dMap.set(dKey, { ...newAgg(), location: u.location, serviceLine: u.service_line, roomType: u.room_type });
            bump(dMap.get(dKey)!);

            const rgKey = `${rn}|${dKey}`;
            const rg = ruleGroupWeight.get(rgKey);
            if (!rg) ruleGroupWeight.set(rgKey, { weight: 1, earliestApplied: appliedAt });
            else { rg.weight += 1; if (appliedAt < rg.earliestApplied) rg.earliestApplied = appliedAt; }
            groupTotalWeightHist.set(dKey, (groupTotalWeightHist.get(dKey) || 0) + 1);
          }
        }
      }

      // T3 revenue impact per (rule, group): group's T3 delta × the rule's
      // proportional share of the group's impacted units.
      type Calc = { monthly: number; occEffect: number; t3Before: number; t3After: number; occBefore: number; occAfter: number; miBefore: number; miAfter: number; hasMi: boolean; occPctNum: number; occPctDen: number; monthsBefore: number; monthsAfter: number; extrapolated: boolean; hasData: boolean };
      const newCalc = (): Calc => ({ monthly: 0, occEffect: 0, t3Before: 0, t3After: 0, occBefore: 0, occAfter: 0, miBefore: 0, miAfter: 0, hasMi: false, occPctNum: 0, occPctDen: 0, monthsBefore: 3, monthsAfter: 3, extrapolated: false, hasData: false });
      const summaryCalc = new Map<string, Calc>();
      const detailCalc = new Map<string, Calc>(); // ruleName|groupKey
      for (const [rgKey, rg] of Array.from(ruleGroupWeight.entries())) {
        const sep = rgKey.indexOf('|');
        const rn = rgKey.slice(0, sep);
        const gKey = rgKey.slice(sep + 1);
        const appliedMonth = monthOf(rg.earliestApplied);
        const t3 = t3For(gKey, appliedMonth, histRuleNames.has(rn));
        if (!t3) { if (!detailCalc.has(rgKey)) detailCalc.set(rgKey, newCalc()); continue; }
        const mi = t3MoveInsFor(gKey, appliedMonth);
        const occPct = t3OccPctBefore(gKey, appliedMonth);
        const total = (histRuleNames.has(rn) ? groupTotalWeightHist.get(gKey) : groupTotalWeight.get(gKey)) || 1;
        const frac = rg.weight / total;
        const impact = t3.delta * frac;
        const dc = detailCalc.get(rgKey) || newCalc();
        dc.monthly += impact; dc.occEffect += t3.occEffect * frac; dc.t3Before += t3.before * frac; dc.t3After += t3.after * frac;
        // Occupied counts: show the actual group count (not fractional) so the
        // user can see real unit numbers in the before/after dialog.
        dc.occBefore += t3.occBefore; dc.occAfter += t3.occAfter;
        if (mi) { dc.miBefore += mi.before * frac; dc.miAfter += mi.after * frac; dc.hasMi = true; }
        if (occPct != null) { const w = t3.occBefore > 0 ? t3.occBefore : 1; dc.occPctNum += occPct * w; dc.occPctDen += w; }
        dc.monthsBefore = t3.monthsBefore; dc.monthsAfter = t3.monthsAfter;
        dc.extrapolated = dc.extrapolated || t3.extrapolated; dc.hasData = true;
        detailCalc.set(rgKey, dc);
        const sc = summaryCalc.get(rn) || newCalc();
        sc.monthly += impact; sc.occEffect += t3.occEffect * frac; sc.t3Before += t3.before * frac; sc.t3After += t3.after * frac;
        sc.occBefore += t3.occBefore; sc.occAfter += t3.occAfter;
        if (mi) { sc.miBefore += mi.before * frac; sc.miAfter += mi.after * frac; sc.hasMi = true; }
        if (occPct != null) { const w = t3.occBefore > 0 ? t3.occBefore : 1; sc.occPctNum += occPct * w; sc.occPctDen += w; }
        sc.monthsBefore = Math.min(sc.hasData ? sc.monthsBefore : 3, t3.monthsBefore);
        sc.monthsAfter = Math.min(sc.hasData ? sc.monthsAfter : 3, t3.monthsAfter);
        sc.extrapolated = sc.extrapolated || t3.extrapolated; sc.hasData = true;
        summaryCalc.set(rn, sc);
      }

      const finish = (a: Agg, c: Calc | undefined, useT3 = false) => {
        const has = !!(c && c.hasData);
        // Days-to-sell: prefer post-rule-application actuals; fall back to days_vacant of occupied units
        const actualDts = a.dtsN > 0 ? a.dtsSum / a.dtsN : null;
        const projDts   = a.projDtsN > 0 ? a.projDtsSum / a.projDtsN : null;
        const avgDts    = actualDts ?? projDts;
        // Expected baseline: prefer sold-unit actuals; fall back to all-impacted-unit baseline
        const avgExp = a.expN > 0 ? a.expSum / a.expN
                     : a.allExpN > 0 ? a.allExpSum / a.allExpN
                     : null;
        // For historical rules: use T3 revenue delta (avg occupied-room revenue 3 months
        // before the effective date vs 3 months after). If fewer than 3 post-change months
        // exist the monthly average of elapsed months is used; annual = monthly × 12.
        // For active rules: fall back to rate-delta approach (projRateSum) which avoids
        // overstating impact with occupancy-driven revenue swings.
        const hasProjectedRate = Math.abs(a.projRateSum) > 0;
        const monthlyImpact = (useT3 && has) ? Math.round(c!.monthly)
                            : hasProjectedRate ? Math.round(a.projRateSum)
                            : has ? Math.round(c!.monthly)
                            : null;
        const annualImpact  = monthlyImpact != null ? Math.round(monthlyImpact * 12) : null;
        const projected = useT3 && !!(has && c!.extrapolated);
        const usedT3 = (useT3 && has) || (!hasProjectedRate && has);
        return {
          unitsImpacted: a.unitsImpacted,
          unitsSold: a.unitsSold,
          avgDaysToSell: avgDts != null ? Math.round(avgDts) : null,
          expectedDaysToSell: avgExp != null ? Math.round(avgExp) : null,
          daysFasterThanExpected: avgDts != null && avgExp != null ? Math.round(avgExp - avgDts) : null,
          monthlyRevenueImpact: monthlyImpact,
          annualRevenueImpact: annualImpact,
          moveInsPerMonth: Math.round(a.moveInsTotal * 10) / 10,
          rateDeltaBefore: hasProjectedRate ? Math.round(a.streetRateMirSum) : null,
          rateDeltaAfter: hasProjectedRate ? Math.round(a.streetRateMirSum + a.projRateSum) : null,
          projected,
          dateApplied: a.earliestApplied,
          method: usedT3 ? 't3' : 'rate-delta',
          calc: has ? {
            t3Before: Math.round(c!.t3Before),
            t3After: Math.round(c!.t3After),
            // Revenue swing caused by occupancy change over the same window. Reported
            // for context only — deliberately NOT part of the rule's attributed impact.
            occupancyEffect: Math.round(c!.occEffect),
            occBefore: Math.round(c!.occBefore * 10) / 10,
            occAfter: Math.round(c!.occAfter * 10) / 10,
            monthsBefore: c!.monthsBefore,
            monthsAfter: c!.monthsAfter,
            extrapolated: c!.extrapolated,
            moveInsT3Before: c!.hasMi ? Math.round(c!.miBefore * 10) / 10 : null,
            moveInsT3After: c!.hasMi ? Math.round(c!.miAfter * 10) / 10 : null,
            occPctBefore: c!.occPctDen > 0 ? Math.round((c!.occPctNum / c!.occPctDen) * 10) / 10 : null,
          } : null,
        };
      };

      const rows = Array.from(summary.entries()).map(([ruleName, agg]) => ({
        ruleName,
        category: categoryMap.get(ruleName) ?? 'hold',
        isHistorical: histRuleNames.has(ruleName),
        ...finish(agg, summaryCalc.get(ruleName), histRuleNames.has(ruleName)),
        detail: Array.from(details.get(ruleName)?.entries() || [])
          .map(([gKey, d]) => ({
            location: d.location, serviceLine: d.serviceLine, roomType: d.roomType,
            ...finish(d, detailCalc.get(`${ruleName}|${gKey}`), histRuleNames.has(ruleName)),
          }))
          .sort((x, y) => x.location.localeCompare(y.location) || x.serviceLine.localeCompare(y.serviceLine) || x.roomType.localeCompare(y.roomType)),
      }));

      // ---- Inject projected rows for active rules not yet applied to any unit ----
      // Active rules that have never been stamped into rent_roll_data (e.g. newly
      // created rules the daily engine hasn't run yet) are invisible to the history
      // query above. Pull their projected impact so every strategy group is visible.
      const appliedNames = new Set(rows.map(r => r.ruleName));
      const unapplied = activeRuleMetaRes.rows.filter((ar: any) => {
        if (!ar.is_active || appliedNames.has(ar.name)) return false;
        // Respect the selected date window: a rule whose effective date falls
        // after the window's end had not taken effect during that period, so
        // its (projected) impact must not appear for that range.
        if (ar.effective_date && new Date(ar.effective_date) > endDate) return false;
        return true;
      });
      if (unapplied.length > 0) {
        const ctxCacheKey = `ruleImpactCtx:${clientId}`;
        let impactCtx = getCachedAnalytics(ctxCacheKey);
        if (!impactCtx) {
          impactCtx = await buildRuleImpactContext(clientId);
          if (impactCtx) setCachedAnalytics(ctxCacheKey, impactCtx);
        }
        if (impactCtx) {
          // Deduplicate: targeted rules claim units first (mirrors /api/adjustment-rules logic).
          // Sort: specificity DESC → explicit priority DESC → effectiveDate DESC.
          const claimedIds = new Set<string>();
          const sorted = [...unapplied].sort((a: any, b: any) => {
            const ruleA = { locationId: a.location_id, serviceLine: a.service_line, serviceLines: a.service_lines, action: a.action };
            const ruleB = { locationId: b.location_id, serviceLine: b.service_line, serviceLines: b.service_lines, action: b.action };
            const specDiff = ruleSpecificityScore(ruleB) - ruleSpecificityScore(ruleA);
            if (specDiff !== 0) return specDiff;
            const priDiff = (b.priority ?? 0) - (a.priority ?? 0);
            if (priDiff !== 0) return priDiff;
            const da = a.effective_date ? new Date(a.effective_date).toISOString() : '';
            const db = b.effective_date ? new Date(b.effective_date).toISOString() : '';
            return db.localeCompare(da);
          });
          for (const ar of sorted) {
            // Build a minimal rule object matching what computeQualifiedRuleImpact expects
            const ruleObj = {
              action: ar.action,
              trigger: ar.trigger,
              serviceLine: ar.service_line || null,
              serviceLines: ar.service_lines || null,
              locationId: ar.location_id || null,
            };
            const impact = computeQualifiedRuleImpact(impactCtx, ruleObj, undefined, claimedIds);
            for (const id of Array.from(impact.qualifiedUnitIds ?? [])) claimedIds.add(id as string);
            if (impact.affectedUnits === 0) {
              // A blanket rule whose units are all claimed by targeted rules is
              // fully suppressed. Still emit a zero-impact projected row so the
              // suppressor-badge pass below can attach suppressedByRules and the
              // rule stays visible in the Rule Performance table.
              const isBlanket = ruleSpecificityScore(ruleObj) === 0;
              if (!isBlanket) continue;
              const wouldBe = computeQualifiedRuleImpact(impactCtx, ruleObj);
              if (wouldBe.affectedUnits === 0) continue;
            }

            const effDate = ar.effective_date ? new Date(ar.effective_date) : null;
            rows.push({
              ruleName: ar.name,
              category: categoryMap.get(ar.name) ?? 'hold',
              isHistorical: false,
              unitsImpacted: impact.affectedUnits,
              unitsSold: 0,
              avgDaysToSell: null,
              expectedDaysToSell: null,
              daysFasterThanExpected: null,
              monthlyRevenueImpact: impact.monthlyImpact,
              annualRevenueImpact: impact.annualImpact,
              projected: true,
              dateApplied: effDate,
              method: 'rate-delta' as const,
              calc: null,
              detail: [],
            });
          }
        }
      }

      // ---- Attach suppressedByRules for active blanket rules -------------------
      // Mirrors the same dedup logic in /api/adjustment-rules so the Rule
      // Performance table can name the specific targeted rule that is suppressing
      // a blanket rule, rather than just showing a generic badge.
      // The claim pass and "would-be" impact are both scoped to the same
      // location/region/division/serviceLine filters as the performance rows so
      // suppression is only reported when it occurs within the active view.
      {
        const activeByName = new Map<string, any>();
        for (const ar of activeRuleMetaRes.rows) {
          if (ar.is_active) activeByName.set(ar.name, ar);
        }
        // Identify performance rows that correspond to active blanket rules (specificity 0)
        const blanketRows = rows.filter(r => {
          const ar = activeByName.get(r.ruleName);
          if (!ar) return false;
          return ruleSpecificityScore({ locationId: ar.location_id, serviceLine: ar.service_line, serviceLines: ar.service_lines, action: ar.action }) === 0;
        });
        if (blanketRows.length > 0) {
          // Resolve the page filters to location IDs (same approach as /api/adjustment-rules)
          // so that suppression is evaluated within the same scope the user sees.
          let perfScopeLocationIds: string[] | null = null;
          if (locations.length || regions.length || divisions.length) {
            const locRows = await pool.query(
              `SELECT id, name, region, division FROM locations WHERE client_id = $1`,
              [clientId]
            );
            perfScopeLocationIds = locRows.rows
              .filter((l: any) =>
                (!locations.length || locations.includes(l.name)) &&
                (!regions.length   || (l.region   && regions.includes(l.region))) &&
                (!divisions.length || (l.division && divisions.includes(l.division))))
              .map((l: any) => l.id);
          }
          const perfScope = (serviceLine || perfScopeLocationIds)
            ? { serviceLine: serviceLine ?? undefined, locationIds: perfScopeLocationIds ?? undefined }
            : undefined;

          const ctxCacheKey = `ruleImpactCtx:${clientId}`;
          let impactCtx = getCachedAnalytics(ctxCacheKey);
          if (!impactCtx) {
            impactCtx = await buildRuleImpactContext(clientId);
            if (impactCtx) setCachedAnalytics(ctxCacheKey, impactCtx);
          }
          if (impactCtx) {
            // Run dedup pass (targeted first) scoped to the active filters.
            // Sort order mirrors the authoritative adjustment-rules dedup:
            // specificity DESC → priority DESC → effectiveDate DESC → createdAt DESC.
            const allActive = activeRuleMetaRes.rows.filter((ar: any) => ar.is_active);
            const sorted = [...allActive].sort((a: any, b: any) => {
              const rA = { locationId: a.location_id, serviceLine: a.service_line, serviceLines: a.service_lines, action: a.action };
              const rB = { locationId: b.location_id, serviceLine: b.service_line, serviceLines: b.service_lines, action: b.action };
              const specDiff = ruleSpecificityScore(rB) - ruleSpecificityScore(rA);
              if (specDiff !== 0) return specDiff;
              const priDiff = (b.priority ?? 0) - (a.priority ?? 0);
              if (priDiff !== 0) return priDiff;
              const da = a.effective_date ? new Date(a.effective_date).toISOString() : '';
              const db = b.effective_date ? new Date(b.effective_date).toISOString() : '';
              if (da !== db) return db.localeCompare(da);
              const ca = a.created_at ? new Date(a.created_at).toISOString() : '';
              const cb = b.created_at ? new Date(b.created_at).toISOString() : '';
              return cb.localeCompare(ca);
            });
            const claimedIds = new Set<string>();
            const unitClaimerMap = new Map<string, { id: string; name: string; specificity: number }>();
            for (const ar of sorted) {
              const ruleObj = { action: ar.action, trigger: ar.trigger, serviceLine: ar.service_line || null, serviceLines: ar.service_lines || null, locationId: ar.location_id || null };
              const spec = ruleSpecificityScore(ruleObj);
              const impact = computeQualifiedRuleImpact(impactCtx, ruleObj, perfScope, claimedIds);
              for (const id of Array.from(impact.qualifiedUnitIds ?? [])) {
                if (!claimedIds.has(id as string)) {
                  unitClaimerMap.set(id as string, { id: ar.id || ar.name, name: ar.name, specificity: spec });
                }
                claimedIds.add(id as string);
              }
            }
            // For each blanket row, compute which targeted rules suppress it within scope
            for (const row of blanketRows) {
              const ar = activeByName.get(row.ruleName);
              if (!ar) continue;
              const ruleObj = { action: ar.action, trigger: ar.trigger, serviceLine: ar.service_line || null, serviceLines: ar.service_lines || null, locationId: ar.location_id || null };
              const wouldBeImpact = computeQualifiedRuleImpact(impactCtx, ruleObj, perfScope);
              const claimerById = new Map<string, { id: string; name: string }>();
              for (const uid of Array.from(wouldBeImpact.qualifiedUnitIds ?? [])) {
                const claimer = unitClaimerMap.get(uid as string);
                if (claimer && claimer.specificity > 0 && claimer.id !== (ar.id || ar.name)) {
                  claimerById.set(claimer.id, { id: claimer.id, name: claimer.name });
                }
              }
              if (claimerById.size > 0) {
                (row as any).suppressedByRules = Array.from(claimerById.values());
              }
            }
          }
        }
      }

      rows.sort((x, y) => (y.annualRevenueImpact || 0) - (x.annualRevenueImpact || 0));

      const payload = { rows, start: startDate, end: endDate };
      setCachedAnalytics(perfCacheKey, payload, 10 * 60 * 1000);
      res.json(payload);
    } catch (err) {
      console.error('[rule-performance] error:', err);
      res.status(500).json({ error: 'Failed to compute rule performance' });
    }
  });

  // GET /api/rule-performance/room-detail
  // Occupied-room verification list for the T3 impact calculation: for one
  // (location, service line[, room types]) group and an applied month, returns
  // the occupied rooms counted in each of the 3 snapshot months before and
  // (up to) 3 months after the change, with the same revenue semantics as the
  // T3 series (HC/HC-MC private-pay only, daily rates × 30.4).
  app.get("/api/rule-performance/room-detail", async (req, res) => {
    try {
      const clientId: string = (req.session as any)?.clientId || 'demo';
      const q = req.query as Record<string, string | undefined>;
      const location = q.location;
      const serviceLine = q.serviceLine;
      const month = q.month; // applied month, YYYY-MM
      if (!location || !serviceLine || !month || !/^\d{4}-\d{2}$/.test(month)) {
        return res.status(400).json({ error: 'location, serviceLine and month (YYYY-MM) are required' });
      }
      const roomTypes = q.roomTypes ? q.roomTypes.split(',').map(s => s.trim()).filter(Boolean) : [];

      const params: any[] = [clientId, location, serviceLine];
      let where = `rr.client_id = $1 AND rr.location = $2 AND rr.service_line = $3`;
      if (roomTypes.length) { params.push(roomTypes); where += ` AND rr.room_type = ANY($${params.length})`; }
      const rowsRes = await pool.query(`
        SELECT rr.upload_month, rr.room_number, rr.room_type, rr.occupied_yn,
               rr.payor_type, rr.in_house_rate
        FROM rent_roll_data rr
        WHERE ${where}
        ORDER BY rr.upload_month, rr.room_number
      `, params);

      const isHc = serviceLine === 'HC' || serviceLine === 'HC/MC';
      const isPrivate = (p: string | null) => !!p && /private|pvt/i.test(p);

      const months = Array.from(new Set(rowsRes.rows.map((r: any) => r.upload_month))).sort();
      const beforeMonths = months.filter(m => m < month).slice(-3);
      const afterMonths = months.filter(m => m >= month).slice(0, 3);

      const buildMonth = (m: string) => {
        const units = rowsRes.rows
          .filter((r: any) => r.upload_month === m && r.occupied_yn && (!isHc || isPrivate(r.payor_type)))
          .map((r: any) => ({
            roomNumber: r.room_number,
            roomType: r.room_type,
            monthlyRate: Math.round(isHc ? Number(r.in_house_rate) * 30.4 : Number(r.in_house_rate)),
          }));
        const excluded = isHc
          ? rowsRes.rows.filter((r: any) => r.upload_month === m && r.occupied_yn && !isPrivate(r.payor_type)).length
          : 0;
        return {
          month: m,
          units,
          occupiedCount: units.length,
          totalRevenue: units.reduce((s: number, u: any) => s + u.monthlyRate, 0),
          excludedNonPrivatePay: excluded,
        };
      };

      res.json({
        location, serviceLine, roomTypes, appliedMonth: month,
        before: beforeMonths.map(buildMonth),
        after: afterMonths.map(buildMonth),
      });
    } catch (err) {
      console.error('[rule-performance/room-detail] error:', err);
      res.status(500).json({ error: 'Failed to load room detail' });
    }
  });

  // REFERENCE DATA — wide Excel-like metric grid
  // Warm the cache for ALL client tenants shortly after startup so the first
  // page visit for any logged-in user is served instantly.
  const KNOWN_CLIENTS = ['demo', 'trilogy', 'glm', 'ssmg'];

  // An ephemeral token generated at startup that lets in-process code warm the
  // reference-data cache for any client without requiring SEED_SECRET to be
  // configured in the environment.  It is never exposed to clients.
  const INTERNAL_WARMUP_TOKEN = `__intl_${Date.now()}_${Math.random().toString(36).slice(2)}`;

  /** Re-warm reference-data (grouped + unit-level) for a single client. Uses the
   *  internal warmup token so it works independently of the optional SEED_SECRET. */
  function warmRefDataCacheForClient(clientId: string) {
    const headers = {
      'x-warmup-client': clientId,
      'x-internal-warmup-token': INTERNAL_WARMUP_TOKEN,
    };
    fetch('http://localhost:5000/api/reference-data', { headers })
      .then(r => { if (r.ok) console.log(`[ref-data] cache warmed for ${clientId}`); })
      .catch(() => {});
    fetch('http://localhost:5000/api/reference-data/units', { headers })
      .then(r => { if (r.ok) console.log(`[ref-data/units] cache warmed for ${clientId}`); })
      .catch(() => {});
  }

  /** Re-warm reference-data (grouped + unit-level) for every known client — called at startup and after invalidation. */
  function warmRefDataCache() {
    for (const clientId of KNOWN_CLIENTS) {
      warmRefDataCacheForClient(clientId);
    }
  }

  // Explicit cache-bust endpoint for test harnesses.  Requires the same
  // SEED_SECRET used by warmup requests so it cannot be called by end users.
  app.post('/api/admin/bust-ref-data-cache', (req, res) => {
    const secret = req.headers['x-seed-secret'] as string | undefined;
    if (!process.env.SEED_SECRET || secret !== process.env.SEED_SECRET) {
      return res.status(403).json({ error: 'Forbidden' });
    }
    invalidateRefDataCache();
    res.json({ ok: true, invalidatedAt: Date.now() });
  });

  setTimeout(() => {
    // Warm reference-data for every client tenant
    warmRefDataCache();
    // Warm commentary for every client tenant
    for (const clientId of KNOWN_CLIENTS) {
      fetch('http://localhost:5000/api/pricing-controls/commentary', {
        headers: { 'x-warmup-client': clientId },
      })
        .then(r => { if (r.ok) console.log(`[commentary] cache warmed for ${clientId}`); })
        .catch(() => {});
    }
    // Warm rule-performance for every client tenant using the frontend's default
    // date window (180 days back through today) so the first page visit is instant.
    const warmEnd = new Date().toISOString().slice(0, 10);
    const warmStart = new Date(Date.now() - 180 * 24 * 3600 * 1000).toISOString().slice(0, 10);
    for (const clientId of KNOWN_CLIENTS) {
      fetch(`http://localhost:5000/api/rule-performance?start=${warmStart}&end=${warmEnd}`, {
        headers: { 'x-warmup-client': clientId, 'x-seed-secret': process.env.SEED_SECRET || '' },
      })
        .then(r => { if (r.ok) console.log(`[rule-perf] cache warmed for ${clientId}`); })
        .catch(() => {});
    }
  }, 8000);

  // Periodic re-warm: fires every 8 minutes so the reference-data cache (TTL=10 min)
  // never goes cold for any tenant between user visits.
  setInterval(() => {
    warmRefDataCache();
  }, 8 * 60 * 1000);

  // GET /api/reference-data?regions=&divisions=&locations=&serviceLine=
  // One row per (Division, Campus, Service Line, Room Type) with Spot/T3/T6/T12
  // metrics computed across the latest 12 upload_months of rent_roll_data.
  // ============================================
  app.get("/api/reference-data", async (req, res) => {
    try {
      // Allow server-side warm-up requests to specify a client without a session.
      // Accepts either the optional SEED_SECRET or the always-available INTERNAL_WARMUP_TOKEN
      // so post-import warming works even when SEED_SECRET is not configured.
      const warmupClient = req.headers['x-warmup-client'] as string | undefined;
      const warmupSecret = req.headers['x-seed-secret'] as string | undefined;
      const internalToken = req.headers['x-internal-warmup-token'] as string | undefined;
      const warmupOk = !!warmupClient && (
        (!!process.env.SEED_SECRET && warmupSecret === process.env.SEED_SECRET) ||
        (internalToken === INTERNAL_WARMUP_TOKEN)
      );
      const clientId: string = warmupOk ? warmupClient! : ((req.session as any)?.clientId || 'demo');
      const q = req.query as Record<string, string | undefined>;
      const csv = (v?: string) => (v ? v.split(',').map(s => s.trim()).filter(Boolean) : []);
      const regions     = csv(q.regions);
      const divisions   = csv(q.divisions);
      const locations   = csv(q.locations);
      const serviceLine = q.serviceLine && q.serviceLine !== 'All' ? q.serviceLine : null;

      // ── Cache check ──
      // Key is prefixed with "grouped:" so it cannot collide with the "units:" key
      // used by /api/reference-data/units for an identical filter combination.
      const cacheKey = `grouped:${JSON.stringify({ clientId, serviceLine, regions, divisions, locations })}`;
      const cachedPayload = getRefDataCache(cacheKey);
      if (cachedPayload) {
        res.setHeader('X-Cache', 'HIT');
        res.set('Cache-Control', 'no-store');
        return res.json(cachedPayload);
      }
      const computeStart = Date.now();

      // 1) Latest 24 upload months for this client (12 for summary windows + 12 more for history drill-down)
      const monthsRes = await pool.query<{ m: string }>(
        `SELECT DISTINCT upload_month AS m FROM rent_roll_data WHERE client_id=$1 AND upload_month IS NOT NULL ORDER BY upload_month DESC LIMIT 24`,
        [clientId]
      );
      const months = monthsRes.rows.map(r => r.m);
      if (months.length === 0) return res.json({ rows: [], months: [], calculatedAt: null });
      const spotMonth = months[0];
      const t3Months  = months.slice(0, 3);
      const t6Months  = months.slice(0, 6);
      const t12Months = months.slice(0, 12);

      // 2) Build all filter params synchronously before launching parallel queries
      const params: any[] = [clientId, months];
      let where = `rr.client_id = $1 AND rr.upload_month = ANY($2)`;
      if (serviceLine) { params.push(serviceLine); where += ` AND rr.service_line = $${params.length}`; }
      if (locations.length)  { params.push(locations);  where += ` AND rr.location = ANY($${params.length})`; }
      if (regions.length)    { params.push(regions);    where += ` AND loc.region = ANY($${params.length})`; }
      if (divisions.length)  { params.push(divisions);  where += ` AND loc.division = ANY($${params.length})`; }

      // 4) Inquiry params (built here so it's ready for the parallel Promise.all below)
      // NOTE: inquiry_metrics uses a different location naming scheme (e.g. "Battle Creek SL") vs
      // rent_roll_data ("Battle Creek - 501"), so we CANNOT filter by location/region/division here —
      // the JS-side normalization (normInqLoc / normCampus) handles the matching after the fetch.
      // We only filter by client, months, and optionally service_line (which is consistent).
      const inqParams: any[] = [clientId, months];
      let inqWhere = `client_id = $1 AND upload_month = ANY($2)`;
      if (serviceLine) { inqParams.push(serviceLine); inqWhere += ` AND service_line = $${inqParams.length}`; }

      // 5) Move-in params
      const moveParams: any[] = [clientId, t3Months];
      let moveWhere = `rr.client_id = $1`;
      if (serviceLine) { moveParams.push(serviceLine); moveWhere += ` AND rr.service_line = $${moveParams.length}`; }
      if (locations.length) { moveParams.push(locations); moveWhere += ` AND rr.location = ANY($${moveParams.length})`; }
      if (regions.length)   { moveParams.push(regions);   moveWhere += ` AND loc.region = ANY($${moveParams.length})`; }
      if (divisions.length) { moveParams.push(divisions); moveWhere += ` AND loc.division = ANY($${moveParams.length})`; }

      // 3-5) Run all three heavy queries in parallel — they are independent of each other
      const [aggRes, inqRes, moveRes] = await Promise.all([
        // 3) Per-month per-combo aggregation
        pool.query(`
          SELECT
            loc.id                                           AS location_id,
            rr.location                                      AS campus,
            COALESCE(loc.division, '—')                      AS division,
            COALESCE(loc.region, '—')                        AS region,
            rr.service_line                                  AS service_line,
            COALESCE(rtg.group_name, rr.room_type)           AS room_type,
            rr.upload_month                                  AS month,
            COUNT(DISTINCT CASE WHEN rr.service_line IN ('AL', 'AL/MC', 'SL', 'VIL') THEN REGEXP_REPLACE(rr.room_number, '/[A-Za-z]+$', '') ELSE rr.room_number END) AS total,
            COUNT(DISTINCT CASE WHEN rr.service_line IN ('AL', 'AL/MC', 'SL', 'VIL') AND rr.occupied_yn THEN REGEXP_REPLACE(rr.room_number, '/[A-Za-z]+$', '') WHEN rr.service_line NOT IN ('AL', 'AL/MC', 'SL', 'VIL') AND rr.occupied_yn THEN rr.room_number ELSE NULL END) AS occupied,
            AVG(rr.days_vacant) FILTER (WHERE NOT rr.occupied_yn AND rr.days_vacant > 0) AS avg_days_vacant,
            -- Street rate is the published SINGLE-OCCUPANT asking rate, which should be uniform
            -- per room type. Use the mode (most common value) rather than AVG so that
            -- second-occupant entries and data-entry anomalies (e.g. a stray $159 on a Studio
            -- Deluxe) do not drag the representative street rate below the true single-occupant rate.
            mode() WITHIN GROUP (ORDER BY rr.street_rate) FILTER (WHERE rr.street_rate > 0
              AND NOT (rr.service_line IN ('AL', 'AL/MC', 'SL', 'VIL') AND rr.room_number ~* '/[B-Zb-z]$')
            ) AS avg_street,
            AVG(rr.in_house_rate) FILTER (WHERE rr.occupied_yn AND rr.in_house_rate > 0)   AS avg_ih,
            AVG(rr.competitor_base_rate) FILTER (WHERE rr.competitor_base_rate > 0)        AS avg_comp_base,
            AVG(rr.competitor_final_rate) FILTER (WHERE rr.competitor_final_rate > 100)    AS avg_comp_adj,
            -- Underlying normalised room type (most common among units in this group).
            -- Used to validate comp rates against the live survey without relying on
            -- stale competitor_base_rate values that may have been set when different
            -- survey data existed.
            mode() WITHIN GROUP (ORDER BY rr.room_type) FILTER (WHERE rr.room_type IS NOT NULL) AS mode_room_type,
            -- Rules-only pivot: the proposed rate is the rule-adjusted rate ONLY.
            -- No Modulo fallback — when no rule applies the proposed rate is NULL.
            AVG(rr.rule_adjusted_rate) FILTER (WHERE rr.rule_adjusted_rate > 0) AS avg_proposed,
            -- HC private-pay census: occupied units with a private/PVT payor type
            COUNT(*) FILTER (WHERE rr.occupied_yn AND (rr.payor_type ILIKE '%private%' OR rr.payor_type ILIKE '%pvt%')) AS hc_private_pay
          FROM rent_roll_data rr
          LEFT JOIN locations loc ON loc.client_id = rr.client_id AND loc.name = rr.location
          LEFT JOIN room_type_groupings rtg
            ON rtg.client_id = rr.client_id AND rtg.location = rr.location
           AND rtg.service_line = rr.service_line AND rtg.source_room_type = rr.source_room_type
          WHERE ${where}
          GROUP BY loc.id, rr.location, loc.division, loc.region, rr.service_line, COALESCE(rtg.group_name, rr.room_type), rr.upload_month
        `, params),
        // 4) Inquiry / tour by location+serviceLine+month
        pool.query(`
          SELECT location, service_line, upload_month AS month,
                 SUM(inquiry_count) AS inq, SUM(tour_count) AS tour
          FROM inquiry_metrics WHERE ${inqWhere}
          GROUP BY location, service_line, upload_month
        `, inqParams),
        // 5) T3 move-ins per (location, service_line) — distinct move-in events in last 3 months
        pool.query(`
          WITH ev AS (
            SELECT DISTINCT ON (rr.location, rr.room_number, rr.move_in_date, rr.service_line, rr.room_type)
              rr.location, rr.service_line,
              COALESCE(rtg.group_name, rr.room_type) AS room_type, rr.payor_type,
              CASE
                WHEN rr.move_in_date ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' THEN TO_DATE(rr.move_in_date,'YYYY-MM-DD')
                WHEN rr.move_in_date ~ '^[0-9]{1,2}/[0-9]{1,2}/[0-9]{4}$' THEN TO_DATE(rr.move_in_date,'MM/DD/YYYY')
                ELSE NULL END AS dt
            FROM rent_roll_data rr
            LEFT JOIN locations loc ON loc.client_id = rr.client_id AND loc.name = rr.location
            LEFT JOIN room_type_groupings rtg
              ON rtg.client_id = rr.client_id AND rtg.location = rr.location
             AND rtg.service_line = rr.service_line AND rtg.source_room_type = rr.source_room_type
            WHERE ${moveWhere} AND rr.move_in_date IS NOT NULL AND rr.move_in_date != ''
            ORDER BY rr.location, rr.room_number, rr.move_in_date, rr.service_line, rr.room_type,
                     (rr.payor_type ILIKE '%private%' OR rr.payor_type ILIKE '%pvt%') DESC, rr.payor_type
          ),
          valid AS (
            SELECT location, service_line, room_type, TO_CHAR(dt,'YYYY-MM') AS mm
            FROM ev
            WHERE dt IS NOT NULL
              AND (CASE WHEN service_line IN ('HC','HC/MC') THEN (payor_type ILIKE '%private%' OR payor_type ILIKE '%pvt%') ELSE TRUE END)
          )
          SELECT location, service_line, room_type, mm, COUNT(*)::int AS n
          FROM valid WHERE mm = ANY($2)
          GROUP BY location, service_line, room_type, mm
        `, moveParams),
      ]);

      // 6a) Pre-compute spot-month occupancy per (campus, SL) from aggRes (rent_roll_data fallback)
      //     then override from room_type_occupancy_history (the authoritative source).
      //     refSlOcc / refCampusOcc are used by the rule trigger evaluator below.
      const refSlOcc     = new Map<string, number>(); // key: "campus||sl" -> occ% (0-1)
      const refCampusOcc = new Map<string, number>(); // key: "campus"     -> occ% (0-1)
      {
        const _slT    = new Map<string, { total: number; occ: number }>();
        const _campT  = new Map<string, { total: number; occ: number }>();
        for (const r of aggRes.rows as any[]) {
          if (r.month !== spotMonth) continue;
          const loc = r.campus || '';
          const sl  = r.service_line || '';
          const tot = Number(r.total) || 0;
          const occ = Number(r.occupied) || 0;
          const slKey = `${loc}||${sl}`;
          const se = _slT.get(slKey) || { total: 0, occ: 0 };
          se.total += tot; se.occ += occ; _slT.set(slKey, se);
          const ce = _campT.get(loc) || { total: 0, occ: 0 };
          ce.total += tot; ce.occ += occ; _campT.set(loc, ce);
        }
        _slT.forEach((v, k)   => refSlOcc.set(k,     v.total ? v.occ / v.total : 0));
        _campT.forEach((v, k) => refCampusOcc.set(k, v.total ? v.occ / v.total : 0));
      }

      // ── Room Type Occupancy History: fetch all months in T12 window ──
      // Used to override ALL occupancy stats below (spot + T3/T6/T12 windows).
      // Key structures: campus||sl||rt  /  campus||sl  /  campus  → YYYY-MM → {occ, avail}
      // RtoEntry type and helpers (rtoOccWindow, physVacWindow, lookupRtPhysMap, lookupRtOccWindow)
      // are imported from server/services/rtOccupancyHistory.ts so tests can couple to the same code.
      const rtoRTMap     = new Map<string, Map<string, RtoEntry>>(); // campus||sl||rt
      const rtoSLMap     = new Map<string, Map<string, RtoEntry>>(); // campus||sl
      const rtoCampusMap = new Map<string, Map<string, RtoEntry>>(); // campus
      const rtoMonthSet = new Set<string>();

      {
        // Convert YYYY-MM strings to (year, month) pairs for the query
        const rtoMonths = months.map(m => ({ year: parseInt(m.slice(0, 4)), month: parseInt(m.slice(5, 7)), ym: m }));
        if (rtoMonths.length > 0) {
          const yearMonthPairs = rtoMonths.map((_, i) => `($${i * 2 + 2}::int, $${i * 2 + 3}::int)`).join(', ');
          const rtoParams: any[] = [clientId, ...rtoMonths.flatMap(r => [r.year, r.month])];
          const rtoRes = await pool.query(`
            SELECT location_name, service_line, normalized_room_type,
                   month, year,
                   SUM(occ_units)        AS occ_units,
                   SUM(available_units)  AS avail_units
            FROM room_type_occupancy_history
            WHERE client_id = $1
              AND (year::int, month::int) IN (${yearMonthPairs})
            GROUP BY location_name, service_line, normalized_room_type, month, year
          `, rtoParams);

          for (const r of rtoRes.rows as any[]) {
            const ym     = `${r.year}-${String(r.month).padStart(2, '0')}`;
            rtoMonthSet.add(ym);
            const campus = r.location_name || '';
            const sl     = r.service_line  || '';
            const rt     = r.normalized_room_type || '';
            const occ    = Number(r.occ_units)   || 0;
            const avail  = Number(r.avail_units)  || 0;
            // per RT combo
            const rtKey  = `${campus}||${sl}||${rt}`;
            if (!rtoRTMap.has(rtKey)) rtoRTMap.set(rtKey, new Map());
            const rtE = rtoRTMap.get(rtKey)!.get(ym) || { occ: 0, avail: 0 };
            rtE.occ += occ; rtE.avail += avail; rtoRTMap.get(rtKey)!.set(ym, rtE);
            // per SL
            const slKey  = `${campus}||${sl}`;
            if (!rtoSLMap.has(slKey)) rtoSLMap.set(slKey, new Map());
            const slE = rtoSLMap.get(slKey)!.get(ym) || { occ: 0, avail: 0 };
            slE.occ += occ; slE.avail += avail; rtoSLMap.get(slKey)!.set(ym, slE);
            // per campus
            if (!rtoCampusMap.has(campus)) rtoCampusMap.set(campus, new Map());
            const cE = rtoCampusMap.get(campus)!.get(ym) || { occ: 0, avail: 0 };
            cE.occ += occ; cE.avail += avail; rtoCampusMap.get(campus)!.set(ym, cE);
          }
        }
      }

      // ── Physical room vacancy from history (authoritative, excludes B-bed double-counting) ──
      // Rent-roll counts every occupant slot (A and B beds) as a separate row, so vacant
      // companion/studio B beds inflate the apparent vacancy. History stores physical room
      // counts (available_units / occ_units), so avail - occ gives the true vacant room count.
      // rtoRTMap is already keyed campus||combined_sl||rt — each service line has its own
      // history entry, so we look up directly by SL rather than collapsing across SLs.
      // physVacWindow and rtoOccWindow are imported from server/services/rtOccupancyHistory.ts.

      // Occupancy data can lag the rent-roll upload (e.g. rent roll has July but the
      // occupancy table's latest month is June). Anchor the occupancy "spot" window
      // to the latest month that actually HAS occupancy data, capped at spot month.
      const rtoSpotMonth = Array.from(rtoMonthSet).filter(m => m <= spotMonth).sort().reverse()[0] ?? spotMonth;
      const rtoSpotWindow = [rtoSpotMonth];

      // Override refSlOcc / refCampusOcc from the RTO anchored spot month
      // (sum occ / sum avail). Anchoring (not exact spotMonth) keeps rule-trigger
      // occupancy on the authoritative occupancy table even when it lags the
      // rent-roll upload — matching the displayed occupancy columns below.
      rtoSLMap.forEach((monthMap, slKey) => {
        const e = monthMap.get(rtoSpotMonth);
        if (e && e.avail > 0) refSlOcc.set(slKey, e.occ / e.avail);
      });
      rtoCampusMap.forEach((monthMap, campus) => {
        const e = monthMap.get(rtoSpotMonth);
        if (e && e.avail > 0) refCampusOcc.set(campus, e.occ / e.avail);
      });


      // 6b) Per-rule rates (spot month only): shared rule-preview pipeline
      //     (buildGroupRulePreviewRates) evaluates triggers and computes adjusted
      //     rates for every active rule × group combination in a single pass.
      const { fetchActiveRules, buildGroupRulePreviewRates, buildPreviewTrailingOccMap } = await import('./services/ruleImpactService');
      const [activeRules, refTrailingOccMap] = await Promise.all([
        fetchActiveRules(clientId),
        buildPreviewTrailingOccMap(clientId),
      ]);

      // IH-to-street variance % per (campus, SL) from spot-month rows, occupied-weighted.
      // Mirrors the rule engine's methodology: Companion units excluded, occupied in-house
      // rates vs street rates. Used to evaluate ih_street_variance trigger conditions.
      const refIhVar = new Map<string, number>();
      {
        const _ihAcc = new Map<string, { ih: number; st: number }>();
        for (const r of aggRes.rows as any[]) {
          if (r.month !== spotMonth) continue;
          if (r.room_type === 'Companion') continue;
          const st = Number(r.avg_street) || 0, ih = Number(r.avg_ih) || 0;
          const occ = Number(r.occupied) || 0;
          if (st <= 0 || ih <= 0 || occ <= 0) continue;
          const k = `${r.campus}||${r.service_line}`;
          const e = _ihAcc.get(k) || { ih: 0, st: 0 };
          e.ih += ih * occ; e.st += st * occ;
          _ihAcc.set(k, e);
        }
        _ihAcc.forEach((e, k) => { if (e.st > 0) refIhVar.set(k, (e.ih - e.st) / e.st * 100); });
      }

      // Build one GroupRateInput per (campus, SL, RT) from spot-month aggRes rows.
      // avg_street is uniform per room type in aggRes (the SQL uses mode()), so it equals
      // the mode rate — same base as the units endpoint's groupModeStreet.
      const _ruleGroups: { campus: string; sl: string; rt: string; sourceRt?: string; locationId: string|null; modeStreetRate: number; avgIhRate: number; total: number; occ: number }[] = [];
      {
        const _gAgg = new Map<string, { campus: string; sl: string; rt: string; sourceRt?: string; locationId: string|null; avgStreet: number; avgIh: number; total: number; occ: number }>();
        for (const r of aggRes.rows as any[]) {
          if (r.month !== spotMonth) continue;
          const campus = r.campus || '', sl = r.service_line || '', rt = r.room_type || '';
          const key = `${campus}||${sl}||${rt}`;
          // mode_room_type is mode() WITHIN GROUP (ORDER BY rr.room_type) — the canonical
          // pre-grouping room type. When RTG renames "Studio" → "Legacy Lane - Studio",
          // rt holds the branded name and sourceRt holds the canonical "Studio".
          const g = _gAgg.get(key) || { campus, sl, rt, sourceRt: r.mode_room_type ?? undefined, locationId: r.location_id ?? null, avgStreet: 0, avgIh: 0, total: 0, occ: 0 };
          if (Number(r.avg_street) > 0) g.avgStreet = Number(r.avg_street);
          if (Number(r.avg_ih) > 0) g.avgIh = Number(r.avg_ih);
          g.total += Number(r.total) || 0;
          g.occ   += Number(r.occupied) || 0;
          _gAgg.set(key, g);
        }
        for (const g of Array.from(_gAgg.values())) {
          _ruleGroups.push({ campus: g.campus, sl: g.sl, rt: g.rt, sourceRt: g.sourceRt, locationId: g.locationId, modeStreetRate: g.avgStreet, avgIhRate: g.avgIh, total: g.total, occ: g.occ });
        }
      }

      // Load the live survey benchmark (uses ALL survey months for rule-trigger
      // evaluation) and separately build a LATEST-month-only coverage set used
      // to gate comp-rate display.  The two are intentionally different: rule
      // triggers benefit from historical averaging, but the comp-rate column
      // should only show when the most recent survey covers that room type.
      const { loadCompBenchmark: _loadCB, SL_TO_COMP: _SL_TO_COMP } = await import('./services/compBenchmark');
      const [refCompBench, _latestCovRes] = await Promise.all([
        _loadCB(pool, clientId),
        pool.query<{ keystats_location: string; competitor_type: string; room_type: string }>(
          `SELECT DISTINCT csd.keystats_location, csd.competitor_type, csd.room_type
           FROM competitive_survey_data csd
           INNER JOIN (
             SELECT keystats_location, competitor_type, MAX(survey_month) AS latest_month
             FROM competitive_survey_data
             WHERE (client_id = $1 OR client_id IS NULL) AND monthly_rate_avg > 0
             GROUP BY keystats_location, competitor_type
           ) lm ON lm.keystats_location = csd.keystats_location
              AND lm.competitor_type    = csd.competitor_type
              AND csd.survey_month      = lm.latest_month
           WHERE (csd.client_id = $1 OR csd.client_id IS NULL) AND csd.monthly_rate_avg > 0
             AND csd.room_type IS NOT NULL AND csd.room_type <> ''`,
          [clientId],
        ),
      ]);
      // Keyed by "location|||compType|||roomType" — only latest-month rows.
      const refLatestSurveyCov = new Set(_latestCovRes.rows.map(
        r => `${r.keystats_location}|||${r.competitor_type}|||${r.room_type}`
      ));

      // Build street-to-comp variance map for trigger evaluation, keyed by both
      // campus||sl||rt (room-type-specific, preferred) and campus||sl (SL-level
      // fallback).  Uses the live survey benchmark — room-type-specific when the
      // survey has that room type (e.g. Studio Dlx vs Studio Dlx competitor rate),
      // falling back to the SL-level blended benchmark otherwise.  This replaces
      // the stale campus_metrics.competitor_final_rate approach which blended all
      // room types together and produced misleading variances.
      const refCompVarMap = new Map<string, number>();
      {
        // Accumulate SL-level weighted averages for the campus||sl fallback key.
        const slAcc = new Map<string, { wSum: number; wN: number }>();
        for (const g of _ruleGroups) {
          if (!g.modeStreetRate || !g.campus || !g.sl || !g.rt) continue;
          // Use RT-specific benchmark; fall back to SL-level for trigger evaluation only.
          const bench = refCompBench.benchmarkForRT(g.campus, g.sl, g.rt)
                     ?? refCompBench.benchmarkFor(g.campus, g.sl);
          if (!bench || bench.adjusted <= 0) continue;
          const pct = (g.modeStreetRate - bench.adjusted) / bench.adjusted * 100;
          refCompVarMap.set(`${g.campus}||${g.sl}||${g.rt}`, pct);
          // Accumulate unit-weighted SL-level variance for the fallback key.
          const slKey = `${g.campus}||${g.sl}`;
          const acc = slAcc.get(slKey) || { wSum: 0, wN: 0 };
          acc.wSum += pct * g.total; acc.wN += g.total;
          slAcc.set(slKey, acc);
        }
        slAcc.forEach(({ wSum, wN }, k) => { if (wN > 0) refCompVarMap.set(k, wSum / wN); });
      }

      const { ruleRatesMap } = buildGroupRulePreviewRates(_ruleGroups, activeRules, refCampusOcc, refSlOcc, refIhVar, refCompVarMap, refTrailingOccMap);

      // ── Roll up in JS ────────────────────────────────────────────────
      const avg = (a: number[]) => a.length ? a.reduce((s, v) => s + v, 0) / a.length : 0;
      const num = (v: any): number | null => (v === null || v === undefined ? null : Number(v));

      type Agg = { month: string; total: number; occupied: number; avgDaysVacant: number|null; avgStreet: number|null; avgIh: number|null; avgCompBase: number|null; avgCompAdj: number|null; avgProposed: number|null; hcPrivatePay: number|null };
      // combo key
      const comboMap = new Map<string, { division: string; region: string; campus: string; serviceLine: string; roomType: string; modeRoomType: string; locationId: string|null; campusKey: string; byMonth: Map<string, Agg> }>();
      // campus & service-line monthly occupancy: key -> month -> {total, occupied}
      const campusOcc = new Map<string, Map<string, { total: number; occupied: number }>>();
      const slOcc     = new Map<string, Map<string, { total: number; occupied: number }>>();

      for (const r of aggRes.rows as any[]) {
        const division = r.division || '—';
        const campus = r.campus || '—';
        const sl = r.service_line || 'Other';
        const rt = r.room_type || 'Other';
        // Stable campus identity: location_id disambiguates same-named campuses across divisions/imports
        const campusKey = `${r.location_id ?? ''}||${division}||${campus}`;
        const key = `${campusKey}||${sl}||${rt}`;
        if (!comboMap.has(key)) comboMap.set(key, { division, region: r.region || '—', campus, serviceLine: sl, roomType: rt, modeRoomType: r.mode_room_type ?? rt, locationId: r.location_id ?? null, campusKey, byMonth: new Map() });
        comboMap.get(key)!.byMonth.set(r.month, {
          month: r.month,
          total: Number(r.total) || 0,
          occupied: Number(r.occupied) || 0,
          avgDaysVacant: num(r.avg_days_vacant),
          avgStreet: num(r.avg_street),
          avgIh: num(r.avg_ih),
          avgCompBase: num(r.avg_comp_base),
          avgCompAdj: num(r.avg_comp_adj),
          avgProposed: num(r.avg_proposed),
          hcPrivatePay: r.hc_private_pay !== null && r.hc_private_pay !== undefined ? Number(r.hc_private_pay) : null,
        });
        // campus rollup
        const cKey = campusKey;
        if (!campusOcc.has(cKey)) campusOcc.set(cKey, new Map());
        const cm = campusOcc.get(cKey)!;
        const cEntry = cm.get(r.month) || { total: 0, occupied: 0 };
        cEntry.total += Number(r.total) || 0; cEntry.occupied += Number(r.occupied) || 0;
        cm.set(r.month, cEntry);
        // service-line rollup
        const sKey = `${campusKey}||${sl}`;
        if (!slOcc.has(sKey)) slOcc.set(sKey, new Map());
        const sm = slOcc.get(sKey)!;
        const sEntry = sm.get(r.month) || { total: 0, occupied: 0 };
        sEntry.total += Number(r.total) || 0; sEntry.occupied += Number(r.occupied) || 0;
        sm.set(r.month, sEntry);
      }

      // inquiry_metrics uses location names like "Battle Creek SL" while rent_roll uses "Battle Creek - 501".
      // Normalize by: (a) stripping the trailing service-line suffix word from inquiry locations,
      //               (b) stripping the " - NNN" numeric campus-code suffix from rent_roll campus names.
      const INQ_SL_SUFFIXES = new Set(['SL','HC','AL','MC','VIL','ALF','AL/MC','HC/MC']);
      const normInqLoc = (loc: string): string => {
        const trimmed = loc.trim();
        // Demo inquiry locations share rent_roll's "Name - NNN" format → strip the numeric
        // campus-code suffix (same logic as normCampus below) so the keys line up.
        // Trilogy inquiry locations use a "Name SL"/"Name HC" format → strip the trailing
        // service-line suffix word instead. Detect which format applies per-location.
        if (/-\s*\d/.test(trimmed)) {
          return trimmed.replace(/\s*-\s*\d+.*$/, '').trim().toLowerCase();
        }
        const parts = trimmed.split(/\s+/);
        const last = parts[parts.length - 1];
        return (INQ_SL_SUFFIXES.has(last) ? parts.slice(0, -1).join(' ') : trimmed).toLowerCase();
      };
      const normCampus = (campus: string): string =>
        campus.replace(/\s*-\s*\d+.*$/, '').trim().toLowerCase();

      // inquiry/tour map: `${normInqLoc}||${sl}` -> month -> {inq, tour}
      // Skip blank-location rows (failed imports can write rows with empty
      // location and zero counts — they'd pollute the map without adding data).
      const inqMap = new Map<string, Map<string, { inq: number; tour: number }>>();
      const inqMonthSet = new Set<string>();
      for (const r of inqRes.rows as any[]) {
        if (!r.location || !String(r.location).trim()) continue;
        const key = `${normInqLoc(r.location)}||${r.service_line || 'Other'}`;
        if (!inqMap.has(key)) inqMap.set(key, new Map());
        const existing = inqMap.get(key)!.get(r.month) || { inq: 0, tour: 0 };
        inqMap.get(key)!.set(r.month, {
          inq: existing.inq + (Number(r.inq) || 0),
          tour: existing.tour + (Number(r.tour) || 0),
        });
        inqMonthSet.add(r.month);
      }
      // Inquiry uploads can lag the rent-roll (or a bad import can leave the
      // rent-roll spot month with no usable inquiry rows). Anchor inquiry/tour
      // windows to the latest month that actually HAS inquiry data, capped at
      // the rent-roll spot month.
      const inqMonths = Array.from(inqMonthSet).filter(m => m <= spotMonth).sort().reverse();
      const inqSpotMonth = inqMonths[0] ?? spotMonth;
      const inqT3Months  = inqMonths.slice(0, 3);
      const inqT12Months = inqMonths.slice(0, 12);
      // move-ins map: `${location}||${sl}||${rt}` -> t3 move-ins/month.
      // Uses the shared getGroupedT3MoveInsMap which applies room-type groupings
      // and selects events vs rent-roll consistently with /api/reference-data/units,
      // so revMonthlyImpact always matches on both views.
      const { getGroupedT3MoveInsMap: _getGroupedT3MI } = await import('./services/ruleImpactService');
      const moveMap = await _getGroupedT3MI(clientId, {
        serviceLine: serviceLine || undefined,
        locations:  locations.length  ? locations  : undefined,
        regions:    regions.length    ? regions    : undefined,
        divisions:  divisions.length  ? divisions  : undefined,
      });
      // Latest-month move-in / move-out counts per grouped `${loc}||${sl}||${rt}` key.
      // hasMoveInData/hasMoveOutData distinguish "0 events" from "no data source at all"
      // (demo rent-roll has move-in dates but no move-out dates → outs/net stay null).
      const miLatestMap = new Map<string, number>();
      const moLatestMap = new Map<string, number>();
      let hasMoveInData = false;
      let hasMoveOutData = false;
      {
        const {
          hasMoveInOutEvents: hasMioEvents,
          getT3MoveInsMapFromEvents,
          getMonthlyMoveInSeriesFromEvents,
          getMonthlyMoveOutSeriesFromEvents,
        } = await import('./services/moveInOutService');
        if (await hasMioEvents(clientId)) {
          const evMap = await getT3MoveInsMapFromEvents(clientId, t3Months, { serviceLine });
          // Apply location/region/division filters (event map is client-wide)
          let allowedLocs: Set<string> | null = null;
          if (locations.length) {
            allowedLocs = new Set(locations);
          } else if (regions.length || divisions.length) {
            const p: any[] = [clientId];
            let w = `client_id = $1`;
            if (regions.length)   { p.push(regions);   w += ` AND region = ANY($${p.length})`; }
            if (divisions.length) { p.push(divisions); w += ` AND division = ANY($${p.length})`; }
            const lr = await pool.query(`SELECT name FROM locations WHERE ${w}`, p);
            allowedLocs = new Set(lr.rows.map((r: any) => r.name));
          }
          // Apply room-type groupings so event keys match the grouped
          // room types used by the reference-data rows (rtg.group_name).
          const rtgRes = await pool.query(`
            SELECT DISTINCT rtg.location, rtg.service_line, rr.room_type, rtg.group_name
            FROM room_type_groupings rtg
            JOIN rent_roll_data rr
              ON rr.client_id = rtg.client_id AND rr.location = rtg.location
             AND rr.service_line = rtg.service_line AND rr.source_room_type = rtg.source_room_type
            WHERE rtg.client_id = $1
          `, [clientId]);
          const rtgMap = new Map<string, string>();
          for (const r of rtgRes.rows as any[]) {
            rtgMap.set(`${r.location}||${r.service_line}||${r.room_type}`, r.group_name);
          }
          // moveMap is built by getGroupedT3MoveInsMap above; no re-assignment needed.

          // Latest-month move-ins & move-outs from the monthly event series.
          // Event data can lag the rent-roll spot month, so anchor to the latest
          // event month ≤ spotMonth (same anchoring pattern as inquiries/tours).
          const [miSeries, moSeries] = await Promise.all([
            getMonthlyMoveInSeriesFromEvents(clientId, { keySep: '||', allPayers: true }),
            getMonthlyMoveOutSeriesFromEvents(clientId, { keySep: '||' }),
          ]);
          const evMonthSet = new Set<string>();
          for (const s of [miSeries, moSeries]) {
            for (const mMap of Array.from(s.values())) {
              for (const mm of Array.from(mMap.keys())) if (mm <= spotMonth) evMonthSet.add(mm);
            }
          }
          const mioSpotMonth = Array.from(evMonthSet).sort().reverse()[0] ?? spotMonth;
          const fillLatest = (series: Map<string, Map<string, number>>, target: Map<string, number>) => {
            for (const [k, mMap] of Array.from(series.entries())) {
              const parts = k.split('||');
              if (allowedLocs && !allowedLocs.has(parts[0])) continue;
              if (serviceLine && parts[1] !== serviceLine) continue;
              const v = mMap.get(mioSpotMonth);
              if (!v) continue;
              const grouped = rtgMap.get(k);
              const key = grouped ? `${parts[0]}||${parts[1]}||${grouped}` : k;
              target.set(key, (target.get(key) || 0) + v);
            }
          };
          fillLatest(miSeries, miLatestMap);
          fillLatest(moSeries, moLatestMap);
          hasMoveInData = true;
          hasMoveOutData = true;
        } else {
          // Rent-roll fallback: moveMap already built by getGroupedT3MoveInsMap above.
          // moveRes provides latest-month move-in counts for the miLatestMap display column.
          for (const r of moveRes.rows as any[]) {
            const key = `${r.location}||${r.service_line}||${r.room_type}`;
            if (r.mm === spotMonth) {
              miLatestMap.set(key, (miLatestMap.get(key) || 0) + (Number(r.n) || 0));
            }
          }
          hasMoveInData = moveRes.rows.length > 0;
        }
      }

      // occupancy % helper across a window of months for a rollup map entry
      const occPctWindow = (m: Map<string, { total: number; occupied: number }> | undefined, window: string[]): number | null => {
        if (!m) return null;
        const pcts = window.map(mm => m.get(mm)).filter(Boolean).map(e => e!.total > 0 ? (e!.occupied / e!.total) * 100 : 0);
        return pcts.length ? avg(pcts) : null;
      };
      const rateWindow = (byMonth: Map<string, Agg>, window: string[], field: keyof Agg): number | null => {
        const vals = window.map(mm => byMonth.get(mm)?.[field]).filter(v => v !== null && v !== undefined) as number[];
        return vals.length ? avg(vals) : null;
      };
      const vacWindow = (byMonth: Map<string, Agg>, window: string[]): number | null => {
        const vals = window.map(mm => { const a = byMonth.get(mm); return a ? a.total - a.occupied : null; }).filter(v => v !== null) as number[];
        return vals.length ? avg(vals) : null;
      };
      const occWindowCombo = (byMonth: Map<string, Agg>, window: string[]): number | null => {
        const vals = window.map(mm => { const a = byMonth.get(mm); return a && a.total > 0 ? (a.occupied / a.total) * 100 : null; }).filter(v => v !== null) as number[];
        return vals.length ? avg(vals) : null;
      };
      const incPct = (spot: number | null, trailing: number | null): number | null =>
        (spot !== null && trailing !== null && trailing !== 0) ? (spot - trailing) / trailing : null;

      // Elasticity metrics (learned per campus||sl||rt) + per-segment revenue growth targets.
      const { getElasticityMap, toDailyRate, predictDaysToSellChange, calculateElasticityRevenueImpact } =
        await import('./services/elasticityService');
      const elasticityMap = await getElasticityMap(clientId);
      // Strictly tenant-scoped: only targets belonging to THIS client's locations.
      // (revenue_growth_targets is keyed by location_id, which is client-owned;
      // there is no client-global target concept elsewhere in the app.)
      const growthTargetsRes = await pool.query<{ location_id: string; service_line: string; target_growth_percent: number }>(
        `SELECT rgt.location_id, rgt.service_line, rgt.target_growth_percent
         FROM revenue_growth_targets rgt
         INNER JOIN locations loc ON loc.id = rgt.location_id
         WHERE loc.client_id = $1`,
        [clientId]
      );
      const growthTargetMap = new Map<string, number>(); // `${locationId}||${sl}` -> pct
      for (const g of growthTargetsRes.rows) {
        growthTargetMap.set(`${g.location_id}||${g.service_line}`, Number(g.target_growth_percent));
      }

      // Load manual rate overrides for this client (keyed by campus||sl||rt)
      const manualOverridesRes = await pool.query<{ location_name: string; service_line: string; room_type: string; override_rate: number; notes: string | null }>(
        `SELECT location_name, service_line, room_type, override_rate, notes FROM manual_rate_overrides WHERE client_id = $1`,
        [clientId]
      );
      const manualOverrideMap = new Map<string, { rate: number; notes: string | null }>();
      for (const o of manualOverridesRes.rows) {
        manualOverrideMap.set(`${o.location_name}||${o.service_line}||${o.room_type}`, { rate: Number(o.override_rate), notes: o.notes ?? null });
      }

      const rows = Array.from(comboMap.values()).map(c => {
        const bm = c.byMonth;
        const spot = bm.get(spotMonth);
        const cOcc = campusOcc.get(c.campusKey);
        const sOcc = slOcc.get(`${c.campusKey}||${c.serviceLine}`);
        const inq  = inqMap.get(`${normCampus(c.campus)}||${c.serviceLine}`);

        // inquiries/tours — anchored to the latest month with actual inquiry data
        const inqPrev = inq?.get(inqSpotMonth)?.inq ?? null;
        const tourPrev = inq?.get(inqSpotMonth)?.tour ?? null;
        const inqT3Avg = inq ? avg(inqT3Months.map(m => inq.get(m)?.inq).filter(v => v != null) as number[]) : null;
        const inqT12Avg = inq ? avg(inqT12Months.map(m => inq.get(m)?.inq).filter(v => v != null) as number[]) : null;
        const tourT3Avg = inq ? avg(inqT3Months.map(m => inq.get(m)?.tour).filter(v => v != null) as number[]) : null;
        const tourT12Avg = inq ? avg(inqT12Months.map(m => inq.get(m)?.tour).filter(v => v != null) as number[]) : null;

        const streetSpot = spot?.avgStreet ?? null;
        const ihSpot = spot?.avgIh ?? null;
        // Gate comp rate display on LATEST-survey-month coverage.  Only show
        // when the most recent survey for this location includes the group's
        // underlying normalised room type.  Stale competitor_base_rate values
        // written by the job under old survey data are suppressed.
        // The stored DB values are kept when valid — they reflect the
        // competitor rate job's weighted-selection methodology.
        const _compTypes = _SL_TO_COMP[c.serviceLine] || [c.serviceLine];
        const _hasLatestCov = _compTypes.some(ct =>
          refLatestSurveyCov.has(`${c.campus}|||${ct}|||${c.modeRoomType}`)
        );
        const compBase = _hasLatestCov ? (spot?.avgCompBase ?? null) : null;
        const compAdj  = _hasLatestCov ? (spot?.avgCompAdj ?? null) : null;
        const proposed = spot?.avgProposed ?? null;
        const totalUnits = spot?.total ?? rateWindow(bm, t3Months, 'total') ?? 0;

        // Try branded display name first, then fall back to canonical (pre-grouping) room type.
        // manual_rate_overrides stores room_type as the canonical name (e.g. "Studio"), but when
        // room_type_groupings renames it to a branded name (e.g. "Legacy Lane - Studio"), the
        // display key (c.roomType) won't match.  c.modeRoomType holds the canonical name computed
        // by mode() WITHIN GROUP (ORDER BY rr.room_type) in the aggRes SQL.
        const manualOverrideEntry = manualOverrideMap.get(`${c.campus}||${c.serviceLine}||${c.roomType}`)
          ?? manualOverrideMap.get(`${c.campus}||${c.serviceLine}||${c.modeRoomType}`)
          ?? null;
        const manualRate = manualOverrideEntry?.rate ?? null;
        const manualOverrideNote = manualOverrideEntry?.notes ?? null;
        // Rule preview fallback: when no rate is stored in rent_roll_data (engine not
        // yet run), use the preview rate of the first matching active rule so the
        // Proposed Rates + Revenue Impact columns populate as soon as a rule matches.
        let rulePreviewRate: number | null = null;
        for (const rule of activeRules) {
          const rr = ruleRatesMap.get(`${c.campus}||${c.serviceLine}||${c.roomType}||${rule.id}`);
          if (rr !== null && rr !== undefined) { rulePreviewRate = rr; break; }
        }
        const effectiveProposed = manualRate ?? proposed ?? rulePreviewRate;
        // Revenue impact: (proposed rate − current street rate) × T3 move-ins/month.
        // Only move-ins are affected by street-rate changes; existing residents keep their rates.
        const t3MoveInsForImpact = moveMap.get(`${c.campus}||${c.serviceLine}||${c.roomType}`) ?? null;
        const monthlyImpact = (effectiveProposed !== null && streetSpot !== null && t3MoveInsForImpact !== null)
          ? (effectiveProposed - streetSpot) * t3MoveInsForImpact
          : null;

        // ── Year-to-date growth ────────────────────────────────────────────────
        // Baseline = earliest available month in the spot year; growth = (spot − base) / base.
        //
        // Three related measures, all sharing the same baseline month so they
        // decompose cleanly:
        //   revYtdGrowth    — in-house REVENUE growth  (avg IH rate × occupied units)
        //   ihYtdGrowth     — in-house RATE growth     (avg IH rate alone)
        //   streetYtdGrowth — street RATE growth       (avg street rate alone)
        // Revenue growth ≈ rate growth + census growth, so publishing rate growth
        // next to revenue growth shows how much of the revenue move came from
        // pricing versus occupancy.
        //
        // Every measure also emits its raw spot/base components. Group roll-ups
        // MUST re-derive the percentage from summed components — averaging the
        // per-row percentages weights a 4-unit room type the same as a 40-unit one.
        const spotYear = spotMonth.slice(0, 4);
        const yearMonths = months.filter(mm => mm.startsWith(spotYear)).sort();
        let revYtdGrowth: number | null = null;
        let ytdRevSpot: number | null = null;
        let ytdRevBase: number | null = null;
        let ihYtdGrowth: number | null = null;
        let ytdIhUnitsSpot: number | null = null;
        let ytdIhUnitsBase: number | null = null;
        let streetYtdGrowth: number | null = null;
        let ytdStreetSpot: number | null = null;
        let ytdStreetBase: number | null = null;
        let ytdStreetUnitsSpot: number | null = null;
        let ytdStreetUnitsBase: number | null = null;
        if (yearMonths.length >= 2 && spot) {
          const baseMonth = yearMonths[0];
          const base = bm.get(baseMonth);
          if (base && baseMonth !== spotMonth) {
            // In-house revenue + in-house rate. Weighted by OCCUPIED units: an
            // in-house rate only exists where somebody is paying it.
            if (spot.avgIh !== null && base.avgIh !== null
                && spot.occupied > 0 && base.occupied > 0 && base.avgIh > 0) {
              const spotRev = spot.avgIh * spot.occupied;
              const baseRev = base.avgIh * base.occupied;
              if (baseRev > 0) {
                revYtdGrowth = (spotRev - baseRev) / baseRev;
                ytdRevSpot = spotRev;
                ytdRevBase = baseRev;
                ytdIhUnitsSpot = spot.occupied;
                ytdIhUnitsBase = base.occupied;
                ihYtdGrowth = (spot.avgIh - base.avgIh) / base.avgIh;
              }
            }
            // Street rate. Weighted by TOTAL units — a street rate is published
            // for vacant units too, so occupancy must not gate it.
            if (spot.avgStreet !== null && base.avgStreet !== null
                && spot.total > 0 && base.total > 0 && base.avgStreet > 0) {
              ytdStreetSpot = spot.avgStreet * spot.total;
              ytdStreetBase = base.avgStreet * base.total;
              ytdStreetUnitsSpot = spot.total;
              ytdStreetUnitsBase = base.total;
              streetYtdGrowth = (spot.avgStreet - base.avgStreet) / base.avgStreet;
            }
          }
        }

        return {
          division: c.division,
          region: c.region,
          campus: c.campus,
          serviceLine: c.serviceLine,
          roomType: c.roomType,
          locationId: c.locationId,
          totalUnits,
          // Vacant units — sourced from room_type_occupancy_history (physical rooms,
          // excludes B-bed double-counting in rent-roll). Each service line has its own
          // history row keyed campus||combined_sl||rt, so AL and HC (and AL/MC, HC/MC)
          // are always looked up independently — no cross-SL merging or proportional split.
          // Falls back to rent-roll when history is absent.
          ...((): { vacantSpot: number|null; vacantT3: number|null; vacantT6: number|null; vacantT12: number|null } => {
            // Try branded group name first, then raw normalised room type (modeRoomType) as
            // a fallback — the RTO history is keyed by normalized_room_type, not group_name.
            // lookupRtPhysMap (server/services/rtOccupancyHistory.ts) encapsulates this
            // two-key pattern so tests can import and exercise the same logic.
            const physMap = lookupRtPhysMap(rtoRTMap, c.campus, c.serviceLine, c.roomType, c.modeRoomType);
            if (!physMap) {
              return {
                vacantSpot: spot ? spot.total - spot.occupied : null,
                vacantT3: vacWindow(bm, t3Months),
                vacantT6: vacWindow(bm, t6Months),
                vacantT12: vacWindow(bm, t12Months),
              };
            }
            return {
              // Spot anchored to the latest month with occupancy data (rtoSpotWindow),
              // falling back to rent-roll counts when history has no usable month.
              vacantSpot: physVacWindow(physMap, rtoSpotWindow) ?? (spot ? spot.total - spot.occupied : null),
              vacantT3:   physVacWindow(physMap, t3Months)  ?? vacWindow(bm, t3Months),
              vacantT6:   physVacWindow(physMap, t6Months)  ?? vacWindow(bm, t6Months),
              vacantT12:  physVacWindow(physMap, t12Months) ?? vacWindow(bm, t12Months),
            };
          })(),
          // Campus occupancy — from the occupancy data table (RTO history), spot anchored
          // to the latest month with occupancy data; rent-roll counts only as last resort
          // (rent roll counts B beds separately and understates occupancy).
          campusOccSpot: rtoOccWindow(rtoCampusMap.get(c.campus), rtoSpotWindow) ?? occPctWindow(cOcc, [spotMonth]),
          campusOccT3:   rtoOccWindow(rtoCampusMap.get(c.campus), t3Months)   ?? occPctWindow(cOcc, t3Months),
          campusOccT6:   rtoOccWindow(rtoCampusMap.get(c.campus), t6Months)   ?? occPctWindow(cOcc, t6Months),
          campusOccT12:  rtoOccWindow(rtoCampusMap.get(c.campus), t12Months)  ?? occPctWindow(cOcc, t12Months),
          // Service line occupancy — from the occupancy data table (anchored spot)
          slOccSpot: rtoOccWindow(rtoSLMap.get(`${c.campus}||${c.serviceLine}`), rtoSpotWindow) ?? occPctWindow(sOcc, [spotMonth]),
          slOccT3:   rtoOccWindow(rtoSLMap.get(`${c.campus}||${c.serviceLine}`), t3Months)   ?? occPctWindow(sOcc, t3Months),
          slOccT6:   rtoOccWindow(rtoSLMap.get(`${c.campus}||${c.serviceLine}`), t6Months)   ?? occPctWindow(sOcc, t6Months),
          slOccT12:  rtoOccWindow(rtoSLMap.get(`${c.campus}||${c.serviceLine}`), t12Months)  ?? occPctWindow(sOcc, t12Months),
          // Room type occupancy — from the occupancy data table (anchored spot)
          // RT Occ: prefer RT-level RTO history, fall back to SL-level RTO, then campus-level.
          // Never fall back to raw spot.occupied/spot.total — that includes B-beds for senior housing
          // (VIL, AL, SL, AL/MC) and produces falsely-low occupancy when no RT-level RTO row exists.
          // The RTO history is keyed by normalized_room_type; c.roomType may be a branded group name
          // (e.g. "Legacy Lane - Studio") that won't match. Try c.modeRoomType (raw rr.room_type
          // mode, e.g. "studio") as a secondary key before falling to SL-level.
          rtOccSpot: lookupRtOccWindow(rtoRTMap, c.campus, c.serviceLine, c.roomType, c.modeRoomType, rtoSpotWindow)
            ?? rtoOccWindow(rtoSLMap.get(`${c.campus}||${c.serviceLine}`), rtoSpotWindow)
            ?? occPctWindow(sOcc, [spotMonth]),
          rtOccT3:   lookupRtOccWindow(rtoRTMap, c.campus, c.serviceLine, c.roomType, c.modeRoomType, t3Months)
            ?? rtoOccWindow(rtoSLMap.get(`${c.campus}||${c.serviceLine}`), t3Months)
            ?? occPctWindow(sOcc, t3Months),
          rtOccT6:   lookupRtOccWindow(rtoRTMap, c.campus, c.serviceLine, c.roomType, c.modeRoomType, t6Months)
            ?? rtoOccWindow(rtoSLMap.get(`${c.campus}||${c.serviceLine}`), t6Months)
            ?? occPctWindow(sOcc, t6Months),
          rtOccT12:  lookupRtOccWindow(rtoRTMap, c.campus, c.serviceLine, c.roomType, c.modeRoomType, t12Months)
            ?? rtoOccWindow(rtoSLMap.get(`${c.campus}||${c.serviceLine}`), t12Months)
            ?? occPctWindow(sOcc, t12Months),
          // Days vacant avg
          daysVacantSpot: spot?.avgDaysVacant ?? null,
          daysVacantT3: rateWindow(bm, t3Months, 'avgDaysVacant'),
          daysVacantT6: rateWindow(bm, t6Months, 'avgDaysVacant'),
          daysVacantT12: rateWindow(bm, t12Months, 'avgDaysVacant'),
          // HC private-pay census (spot month only; only meaningful for HC / HC/MC rows)
          hcPrivatePaySpot: ['HC', 'HC/MC'].includes(c.serviceLine) ? (spot?.hcPrivatePay ?? null) : null,
          // Inquiries
          inqPrevMonth: inqPrev,
          inqVsT3: (inqPrev !== null && inqT3Avg !== null) ? inqPrev - inqT3Avg : null,
          inqVsT12: (inqPrev !== null && inqT12Avg !== null) ? inqPrev - inqT12Avg : null,
          // Tours
          tourPrevMonth: tourPrev,
          tourVsT3: (tourPrev !== null && tourT3Avg !== null) ? tourPrev - tourT3Avg : null,
          tourVsT12: (tourPrev !== null && tourT12Avg !== null) ? tourPrev - tourT12Avg : null,
          // Move-ins / move-outs (latest month with data; 0 when data source exists but no events)
          ...((): { moveInsLatest: number|null; moveOutsLatest: number|null; moveNetLatest: number|null } => {
            const key = `${c.campus}||${c.serviceLine}||${c.roomType}`;
            const mi = hasMoveInData ? (miLatestMap.get(key) ?? 0) : null;
            const mo = hasMoveOutData ? (moLatestMap.get(key) ?? 0) : null;
            return { moveInsLatest: mi, moveOutsLatest: mo, moveNetLatest: (mi !== null && mo !== null) ? mi - mo : null };
          })(),
          // Street rates - single occupant
          streetSpot,
          streetT3avg: rateWindow(bm, t3Months, 'avgStreet'),
          streetT12avg: rateWindow(bm, t12Months, 'avgStreet'),
          streetIncT3: incPct(streetSpot, rateWindow(bm, t3Months, 'avgStreet')),
          streetIncT6: incPct(streetSpot, rateWindow(bm, t6Months, 'avgStreet')),
          streetIncT12: incPct(streetSpot, rateWindow(bm, t12Months, 'avgStreet')),
          // Comp rates - top comp
          compBase,
          compAdjusted: compAdj,
          compVarDollar: (compAdj !== null && streetSpot !== null) ? compAdj - streetSpot : null,
          compVarPct: (compAdj !== null && streetSpot !== null && streetSpot !== 0) ? (compAdj - streetSpot) / streetSpot : null,
          // In-house rates
          ihSpot,
          ihVarStreetDollar: (ihSpot !== null && streetSpot !== null) ? ihSpot - streetSpot : null,
          ihVarStreetPct: (ihSpot !== null && streetSpot !== null && streetSpot !== 0) ? (ihSpot - streetSpot) / streetSpot : null,
          ihT3avg: rateWindow(bm, t3Months, 'avgIh'),
          ihT12avg: rateWindow(bm, t12Months, 'avgIh'),
          ihIncT3: incPct(ihSpot, rateWindow(bm, t3Months, 'avgIh')),
          ihIncT6: incPct(ihSpot, rateWindow(bm, t6Months, 'avgIh')),
          ihIncT12: incPct(ihSpot, rateWindow(bm, t12Months, 'avgIh')),
          // Proposed rates — manual override takes precedence when present
          proposedRule: effectiveProposed,
          hasManualOverride: manualRate !== null,
          manualOverrideNote: manualOverrideNote,
          // The rule-calculated rate before any manual override; null when no rule applies.
          // Used by the UI tooltip: "Manual override — rule rate was $X".
          ruleRate: manualRate !== null ? (proposed ?? rulePreviewRate) : null,
          proposedVarDollar: (effectiveProposed !== null && streetSpot !== null) ? effectiveProposed - streetSpot : null,
          proposedVarPct: (effectiveProposed !== null && streetSpot !== null && streetSpot !== 0) ? (effectiveProposed - streetSpot) / streetSpot : null,
          // Revenue impact: (proposed − street) × T3 move-ins/mo; annual =
          // first-year cumulative (monthly × 78, stacked move-in cohorts) so it
          // matches the rules API / Strategy Report annualization.
          revT3MoveIns: t3MoveInsForImpact,
          revMonthlyImpact: monthlyImpact,
          revAnnualImpact: monthlyImpact !== null ? monthlyImpact * 78 : null,
          revSteadyStateImpact: monthlyImpact !== null ? monthlyImpact * 144 : null,
          // % impact: first-year annual delta (monthly × 78) / annual IH revenue (monthly × 12)
          // Uses the same 78-month first-year multiplier as revAnnualImpact so that
          // revAnnualImpact / (ihSpot × occupied × 12) === revImpactPct.
          revImpactPct: (monthlyImpact !== null && ihSpot !== null && ihSpot > 0 && (spot?.occupied ?? 0) > 0)
            ? (monthlyImpact * 78) / (ihSpot * spot!.occupied * 12)
            : null,
          // ── Price elasticity + days-to-sell metrics + elasticity-based impact ──
          ...(() => {
            const elas = elasticityMap.get(`${c.campus}||${c.serviceLine}||${c.roomType}`) ?? null;
            const elasticity = elas?.elasticity ?? null;
            const daysToSellBefore = elas?.daysToSellBefore ?? null;
            const daysToSellAfter = elas?.daysToSellAfter ?? null;
            const daysToSellChange = elas?.daysToSellChange ?? null;
            // Rate delta from applying rules to the street (asking) rate.
            const deltaRate = (effectiveProposed !== null && streetSpot !== null) ? effectiveProposed - streetSpot : null;
            const predictedDaysToSellChange = predictDaysToSellChange(
              elasticity, daysToSellAfter, streetSpot, deltaRate
            );
            const moveInsMonthly = moveMap.get(`${c.campus}||${c.serviceLine}||${c.roomType}`) ?? null;
            const dailyRate = streetSpot !== null ? toDailyRate(streetSpot, c.serviceLine) : null;
            const elasticImpact = calculateElasticityRevenueImpact({
              moveInsMonthly,
              deltaRate,
              deltaDaysToSell: predictedDaysToSellChange,
              dailyRate,
            });
            return {
              elasticity,
              elasticityConfidence: elas?.confidence ?? null,
              elasticitySampleSize: elas?.sampleSize ?? 0,
              daysToSellBefore,
              daysToSellAfter,
              daysToSellChange,
              predictedDaysToSellChange,
              elasticityMonthlyImpact: elasticImpact.monthly,
              elasticityAnnualImpact: elasticImpact.annual,
            };
          })(),
          // Revenue growth target (% annual) for this campus's location + service line
          revenueGrowthTarget:
            (c.locationId ? growthTargetMap.get(`${c.locationId}||${c.serviceLine}`) : undefined)
            ?? null,
          // YTD growth (all fractions, e.g. 0.023 = +2.3%). The *Spot/*Base
          // components are the raw numerator/denominator pieces the client sums
          // when rolling rows up — never average the percentages themselves.
          revYtdGrowth,
          ytdRevSpot,
          ytdRevBase,
          // YTD in-house RATE growth (rate only, census removed)
          ihYtdGrowth,
          ytdIhUnitsSpot,
          ytdIhUnitsBase,
          // YTD street RATE growth
          streetYtdGrowth,
          ytdStreetSpot,
          ytdStreetBase,
          ytdStreetUnitsSpot,
          ytdStreetUnitsBase,
          // Monthly history for expandable column drill-down (up to 24 months)
          campusOccHistory: Object.fromEntries(
            months.map(mm => [mm, rtoOccWindow(rtoCampusMap.get(c.campus), [mm]) ?? occPctWindow(cOcc, [mm])])
          ),
          slOccHistory: Object.fromEntries(
            months.map(mm => [mm, rtoOccWindow(rtoSLMap.get(`${c.campus}||${c.serviceLine}`), [mm]) ?? occPctWindow(sOcc, [mm])])
          ),
          rtOccHistory: Object.fromEntries(
            months.map(mm => [mm, lookupRtOccWindow(rtoRTMap, c.campus, c.serviceLine, c.roomType, c.modeRoomType, [mm]) ?? occWindowCombo(bm, [mm])])
          ),
          ihHistory: Object.fromEntries(
            months.map(mm => [mm, bm.get(mm)?.avgIh ?? null])
          ),
          streetHistory: Object.fromEntries(
            months.map(mm => [mm, bm.get(mm)?.avgStreet ?? null])
          ),
          // Per-rule rates (avg rate for units where each rule was applied, spot month)
          ruleRates: (() => {
            const rr: Record<string, number | null> = {};
            for (const rule of activeRules) {
              const key = `${c.campus}||${c.serviceLine}||${c.roomType}||${rule.id}`;
              rr[rule.id] = ruleRatesMap.get(key) ?? null;
            }
            return rr;
          })(),
        };
      });

      // Drop stale combos: no units present in the trailing 3 months (all-blank rows)
      const activeRows = rows.filter(r => (r.totalUnits || 0) > 0);

      // Sort: division, campus, service line, room type
      activeRows.sort((a, b) =>
        a.division.localeCompare(b.division) || a.campus.localeCompare(b.campus) ||
        a.serviceLine.localeCompare(b.serviceLine) || a.roomType.localeCompare(b.roomType));

      const payload = { rows: activeRows, months, spotMonth, calculatedAt: new Date().toISOString(), rules: activeRules };
      setRefDataCache(cacheKey, payload, computeStart);
      res.setHeader('X-Cache', 'MISS');
      res.set('Cache-Control', 'no-store');
      res.json(payload);
    } catch (error) {
      console.error("Error building reference data:", error);
      res.status(500).json({ error: "Failed to build reference data" });
    }
  });

  // GET /api/reference-data/units — Room Detail grouping level for the
  // Reference Data table: one row per unit at the spot (latest) month.
  app.get("/api/reference-data/units", async (req, res) => {
    try {
      // Allow server-side warm-up requests to specify a client without a session.
      // Accepts either the optional SEED_SECRET or the always-available INTERNAL_WARMUP_TOKEN.
      const warmupClient = req.headers['x-warmup-client'] as string | undefined;
      const warmupSecret = req.headers['x-seed-secret'] as string | undefined;
      const internalToken = req.headers['x-internal-warmup-token'] as string | undefined;
      const warmupOk = !!warmupClient && (
        (!!process.env.SEED_SECRET && warmupSecret === process.env.SEED_SECRET) ||
        (internalToken === INTERNAL_WARMUP_TOKEN)
      );
      const clientId: string = warmupOk ? warmupClient! : ((req.session as any)?.clientId || 'demo');
      const q = req.query as Record<string, string | undefined>;
      const csv = (v?: string) => (v ? v.split(',').map(s => s.trim()).filter(Boolean) : []);
      const regions     = csv(q.regions);
      const divisions   = csv(q.divisions);
      const locations   = csv(q.locations);
      const serviceLine = q.serviceLine && q.serviceLine !== 'All' ? q.serviceLine : null;

      // ── Cache check ──
      const cacheKey = `units:${JSON.stringify({ clientId, serviceLine, regions, divisions, locations })}`;
      const cachedPayload = getRefDataCache(cacheKey);
      if (cachedPayload) {
        res.setHeader('X-Cache', 'HIT');
        res.set('Cache-Control', 'no-store');
        return res.json(cachedPayload);
      }
      const computeStart = Date.now();

      const spotRes = await pool.query<{ m: string }>(
        `SELECT MAX(upload_month) AS m FROM rent_roll_data WHERE client_id=$1`,
        [clientId]
      );
      const spotMonth = spotRes.rows[0]?.m ?? null;
      if (!spotMonth) return res.json({ rows: [], spotMonth: null });

      const params: any[] = [clientId, spotMonth];
      let where = `rr.client_id = $1 AND rr.upload_month = $2`;
      if (serviceLine) { params.push(serviceLine); where += ` AND rr.service_line = $${params.length}`; }
      if (locations.length)  { params.push(locations);  where += ` AND rr.location = ANY($${params.length})`; }
      if (regions.length)    { params.push(regions);    where += ` AND loc.region = ANY($${params.length})`; }
      if (divisions.length)  { params.push(divisions);  where += ` AND loc.division = ANY($${params.length})`; }

      const unitsRes = await pool.query(`
        SELECT
          loc.id AS location_id,
          COALESCE(loc.division, '—') AS division,
          COALESCE(loc.region, '—')   AS region,
          rr.location                 AS campus,
          rr.service_line,
          COALESCE(rtg.group_name, rr.room_type) AS room_type,
          rr.room_type AS source_room_type,
          rr.room_number,
          rr.occupied_yn,
          rr.days_vacant,
          NULLIF(rr.street_rate, 0)          AS street_rate,
          NULLIF(rr.in_house_rate, 0)        AS in_house_rate,
          NULLIF(rr.competitor_base_rate, 0) AS comp_base,
          CASE WHEN rr.competitor_final_rate > 100 THEN rr.competitor_final_rate END AS comp_adj,
          NULLIF(rr.rule_adjusted_rate, 0)   AS proposed_rate
        FROM rent_roll_data rr
        LEFT JOIN locations loc ON loc.client_id = rr.client_id AND loc.name = rr.location
        LEFT JOIN room_type_groupings rtg
          ON rtg.client_id = rr.client_id AND rtg.location = rr.location
         AND rtg.service_line = rr.service_line AND rtg.source_room_type = rr.source_room_type
        WHERE ${where}
        ORDER BY loc.division, rr.location, rr.service_line, COALESCE(rtg.group_name, rr.room_type), rr.room_number
      `, params);

      // T3 move-ins per grouped `${campus}||${sl}||${roomType}` — uses the shared
      // getGroupedT3MoveInsMap which applies room-type groupings and selects the
      // same move-in source (events or rent-roll) as /api/reference-data, so
      // revMonthlyImpact always sums identically across both views.
      const { getGroupedT3MoveInsMap } = await import('./services/ruleImpactService');
      const t3Map = await getGroupedT3MoveInsMap(clientId, {
        serviceLine: serviceLine || undefined,
        locations:  locations.length  ? locations  : undefined,
        regions:    regions.length    ? regions    : undefined,
        divisions:  divisions.length  ? divisions  : undefined,
      });
      // Group unit counts keyed the same way as row output below.
      const groupUnitCount = new Map<string, number>();
      for (const r of unitsRes.rows as any[]) {
        const key = `${r.campus}||${r.service_line || 'Other'}||${r.room_type || 'Other'}`;
        groupUnitCount.set(key, (groupUnitCount.get(key) || 0) + 1);
      }
      // Manual rate overrides take precedence over stored rule-adjusted rates,
      // matching the main reference-data endpoint's effectiveProposed behavior.
      const unitOverrideMap = new Map<string, number>();
      {
        const ovRes = await pool.query(
          `SELECT location_name, service_line, room_type, override_rate
           FROM manual_rate_overrides WHERE client_id = $1`,
          [clientId]
        );
        for (const o of ovRes.rows as any[]) {
          unitOverrideMap.set(`${o.location_name}||${o.service_line}||${o.room_type}`, Number(o.override_rate));
        }
      }

      // Mode street rate per group — matches the grouped endpoint's
      //   mode() WITHIN GROUP (ORDER BY street_rate) FILTER (WHERE street_rate > 0)
      // Tie-breaking: ascending sort → smallest value wins (PostgreSQL behaviour).
      // Computed here (before rulePreviewMap) so the rule-preview base rate uses
      // the same mode as the grouped endpoint, not a simple average.
      const groupModeStreet = new Map<string, number>();
      {
        const SH_SLS_MODE = new Set(['AL', 'AL/MC', 'SL', 'VIL']);
        const freq = new Map<string, Map<number, number>>();
        for (const r of unitsRes.rows as any[]) {
          const st = Number(r.street_rate) || 0;
          if (st <= 0) continue;
          // Exclude B-bed companion rows for senior housing SLs so the mode
          // reflects only the primary (single-occupant) unit rate.
          if (SH_SLS_MODE.has(r.service_line) && /\/[B-Zb-z]$/.test(r.room_number || '')) continue;
          const key = `${r.campus}||${r.service_line || 'Other'}||${r.room_type || 'Other'}`;
          if (!freq.has(key)) freq.set(key, new Map());
          const m = freq.get(key)!;
          m.set(st, (m.get(st) || 0) + 1);
        }
        for (const [key, m] of Array.from(freq.entries())) {
          // mode() WITHIN GROUP (ORDER BY street_rate ASC): most frequent;
          // ties → smallest value (first in ascending sort order).
          let maxCount = 0, modeRate = Infinity;
          for (const [rate, count] of Array.from(m.entries())) {
            if (count > maxCount || (count === maxCount && rate < modeRate)) {
              maxCount = count; modeRate = rate;
            }
          }
          if (isFinite(modeRate)) groupModeStreet.set(key, modeRate);
        }
      }

      // Rule-preview fallback per group (campus||sl||rt) — uses the shared
      // buildGroupRulePreviewRates pipeline so trigger semantics stay in sync
      // with the grouped endpoint.
      const rulePreviewMap = new Map<string, number>();
      {
        const { fetchActiveRules, buildGroupRulePreviewRates, buildPreviewTrailingOccMap } = await import('./services/ruleImpactService');
        const [activeRules2, trailingOccMap2] = await Promise.all([
          fetchActiveRules(clientId),
          buildPreviewTrailingOccMap(clientId),
        ]);
        if (activeRules2.length) {
          // Build per-group aggregates from unit rows.
          const gAgg = new Map<string, { campus: string; sl: string; rt: string; sourceRt?: string; locationId: string|null; ihSum: number; ihN: number; total: number; occ: number }>();
          const campT = new Map<string, { total: number; occ: number }>();
          const slT   = new Map<string, { total: number; occ: number }>();
          const ihAcc = new Map<string, { ih: number; st: number }>();
          for (const r of unitsRes.rows as any[]) {
            const sl = r.service_line || 'Other';
            const rt = r.room_type || 'Other';
            const key = `${r.campus}||${sl}||${rt}`;
            // source_room_type is rr.room_type (canonical, pre-grouping). When RTG renames
            // "Studio" → "Legacy Lane - Studio", rt is the branded name and source_room_type
            // is "Studio". Both are needed for rule-filter matching in buildGroupRulePreviewRates.
            const g = gAgg.get(key) || { campus: r.campus, sl, rt, sourceRt: r.source_room_type ?? undefined, locationId: r.location_id ?? null, ihSum: 0, ihN: 0, total: 0, occ: 0 };
            const ih = Number(r.in_house_rate) || 0;
            if (ih > 0) { g.ihSum += ih; g.ihN += 1; }
            g.total += 1; if (r.occupied_yn) g.occ += 1;
            gAgg.set(key, g);
            const ce = campT.get(r.campus) || { total: 0, occ: 0 };
            ce.total += 1; if (r.occupied_yn) ce.occ += 1; campT.set(r.campus, ce);
            const sk = `${r.campus}||${sl}`;
            const se = slT.get(sk) || { total: 0, occ: 0 };
            se.total += 1; if (r.occupied_yn) se.occ += 1; slT.set(sk, se);
            const st = Number(r.street_rate) || 0;
            if (rt !== 'Companion' && r.occupied_yn && st > 0 && ih > 0) {
              const e = ihAcc.get(sk) || { ih: 0, st: 0 };
              e.ih += ih; e.st += st; ihAcc.set(sk, e);
            }
          }
          const campOcc2 = new Map<string, number>();
          campT.forEach((v, k) => campOcc2.set(k, v.total ? v.occ / v.total : 0));
          const slOcc2 = new Map<string, number>();
          slT.forEach((v, k) => slOcc2.set(k, v.total ? v.occ / v.total : 0));
          // Override with authoritative occupancy history (anchored to the
          // latest history month ≤ spot month) — same as the grouped endpoint, so
          // rule triggers evaluate against identical occupancy metrics.
          {
            const rtoRes2 = await pool.query(`
              WITH anchored AS (
                SELECT MAX(year::int * 100 + month::int) AS ym
                FROM room_type_occupancy_history
                WHERE client_id = $1
                  AND (year::int * 100 + month::int) <= $2
              )
              SELECT location_name, service_line,
                     SUM(occ_units) AS occ_units, SUM(available_units) AS avail_units
              FROM room_type_occupancy_history, anchored
              WHERE client_id = $1 AND (year::int * 100 + month::int) = anchored.ym
              GROUP BY location_name, service_line
            `, [clientId, Number(spotMonth.slice(0, 4)) * 100 + Number(spotMonth.slice(5, 7))]);
            const campAcc = new Map<string, { occ: number; avail: number }>();
            for (const r of rtoRes2.rows as any[]) {
              const occ = Number(r.occ_units) || 0, avail = Number(r.avail_units) || 0;
              if (avail > 0) slOcc2.set(`${r.location_name}||${r.service_line}`, occ / avail);
              const ce = campAcc.get(r.location_name) || { occ: 0, avail: 0 };
              ce.occ += occ; ce.avail += avail; campAcc.set(r.location_name, ce);
            }
            campAcc.forEach((e, k) => { if (e.avail > 0) campOcc2.set(k, e.occ / e.avail); });
          }
          const ihVar2 = new Map<string, number>();
          ihAcc.forEach((e, k) => { if (e.st > 0) ihVar2.set(k, (e.ih - e.st) / e.st * 100); });

          // Build GroupRateInput array using pre-computed mode street rates so the
          // base rate matches the grouped endpoint's mode() WITHIN GROUP SQL value.
          const groupInputs = Array.from(gAgg.values()).map(g => ({
            campus: g.campus, sl: g.sl, rt: g.rt, sourceRt: g.sourceRt, locationId: g.locationId,
            modeStreetRate: groupModeStreet.get(`${g.campus}||${g.sl}||${g.rt}`) ?? 0,
            avgIhRate: g.ihN ? g.ihSum / g.ihN : 0,
            total: g.total, occ: g.occ,
          }));

          // Street-to-comp variance map: survey-based, RT-specific where available.
          // Mirrors the logic in the grouped Reference Data endpoint.
          const compVarMap2 = new Map<string, number>();
          {
            const { loadCompBenchmark: _loadCB2 } = await import('./services/compBenchmark');
            const refCompBench2 = await _loadCB2(pool, clientId);
            const slAcc2 = new Map<string, { wSum: number; wN: number }>();
            for (const g of groupInputs) {
              if (!g.modeStreetRate || !g.campus || !g.sl || !g.rt) continue;
              // RT-specific benchmark; fall back to SL-level for trigger evaluation only.
              const bench = refCompBench2.benchmarkForRT(g.campus, g.sl, g.rt)
                         ?? refCompBench2.benchmarkFor(g.campus, g.sl);
              if (!bench || bench.adjusted <= 0) continue;
              const pct = (g.modeStreetRate - bench.adjusted) / bench.adjusted * 100;
              compVarMap2.set(`${g.campus}||${g.sl}||${g.rt}`, pct);
              const slKey = `${g.campus}||${g.sl}`;
              const acc = slAcc2.get(slKey) || { wSum: 0, wN: 0 };
              acc.wSum += pct * g.total; acc.wN += g.total;
              slAcc2.set(slKey, acc);
            }
            slAcc2.forEach(({ wSum, wN }, k) => { if (wN > 0) compVarMap2.set(k, wSum / wN); });
          }

          const { rulePreviewMap: preview } = buildGroupRulePreviewRates(groupInputs, activeRules2, campOcc2, slOcc2, ihVar2, compVarMap2, trailingOccMap2);
          for (const [k, v] of Array.from(preview.entries())) rulePreviewMap.set(k, v);
        }
      }

      // ── Group-level revenue impact for parity with grouped /api/reference-data ──
      // groupModeStreet was already computed above (before rulePreviewMap) so the
      // rule-preview base rate uses the same mode as the grouped endpoint.

      // Group effective proposed — mirrors the grouped endpoint's precedence:
      //   manual override ?? AVG(rule_adjusted_rate) for units with a stored rate ?? rule preview.
      const groupEffectiveProposedMap = new Map<string, number | null>();
      {
        const storedSums = new Map<string, { sum: number; count: number }>();
        for (const r of unitsRes.rows as any[]) {
          const stored = Number(r.proposed_rate) || 0;
          if (stored > 0) {
            const key = `${r.campus}||${r.service_line || 'Other'}||${r.room_type || 'Other'}`;
            const e = storedSums.get(key) || { sum: 0, count: 0 };
            e.sum += stored; e.count += 1;
            storedSums.set(key, e);
          }
        }
        for (const key of Array.from(groupUnitCount.keys())) {
          const manualRate = unitOverrideMap.get(key) ?? null;
          if (manualRate !== null) {
            groupEffectiveProposedMap.set(key, manualRate);
            continue;
          }
          const stored = storedSums.get(key);
          if (stored && stored.count > 0) {
            groupEffectiveProposedMap.set(key, stored.sum / stored.count);
            continue;
          }
          groupEffectiveProposedMap.set(key, rulePreviewMap.get(key) ?? null);
        }
      }

      // Step 3: Pre-compute group monthly impact — (groupProposed − modeStreet) × groupT3.
      // Distributing this evenly to each unit row guarantees exact summation parity.
      const groupMonthlyImpactMap = new Map<string, number | null>();
      for (const key of Array.from(groupUnitCount.keys())) {
        const groupStreet   = groupModeStreet.get(key) ?? null;
        const groupProposed = groupEffectiveProposedMap.get(key) ?? null;
        const groupT3       = t3Map.get(key) ?? null;
        const gMonthly = (groupProposed !== null && groupStreet !== null && groupT3 !== null)
          ? (groupProposed - groupStreet) * groupT3
          : null;
        groupMonthlyImpactMap.set(key, gMonthly);
      }

      // Step 4: Pre-compute group elasticity-based revenue impact — uses T3 move-ins
      // as the volume denominator (matching the revenue impact model) and passes
      // predictedDTS unchanged so groups without elasticity data return null rather
      // than a naive non-elasticity-adjusted figure. Distributed evenly across units.
      const groupElasticityMonthlyImpactMap = new Map<string, number | null>();
      // Raw elasticity/DTS values per group — repeated on each unit row (same pattern as occupancy).
      const groupElasticityDataMap = new Map<string, {
        elasticity: number | null;
        daysToSellBefore: number | null;
        daysToSellAfter: number | null;
        daysToSellChange: number | null;
        elasticityConfidence: number | null;
        elasticitySampleSize: number;
      }>();
      {
        const { getElasticityMap, toDailyRate, predictDaysToSellChange, calculateElasticityRevenueImpact } =
          await import('./services/elasticityService');
        const elasticityMap = await getElasticityMap(clientId);

        for (const key of Array.from(groupUnitCount.keys())) {
          const parts = key.split('||');
          const campus = parts[0], sl = parts[1], rt = parts[2];
          const groupProposed = groupEffectiveProposedMap.get(key) ?? null;
          const groupStreet   = groupModeStreet.get(key) ?? null;

          const elas = elasticityMap.get(`${campus}||${sl}||${rt}`) ?? null;
          const elasticity      = elas?.elasticity ?? null;
          const daysToSellAfter = elas?.daysToSellAfter ?? null;
          const daysToSellBefore = elas?.daysToSellBefore ?? null;
          const daysToSellChange = elas?.daysToSellChange ?? null;
          const deltaRate       = (groupProposed !== null && groupStreet !== null) ? groupProposed - groupStreet : null;
          const predictedDTS    = predictDaysToSellChange(elasticity, daysToSellAfter, groupStreet, deltaRate);
          const dailyRate       = groupStreet !== null ? toDailyRate(groupStreet, sl) : null;
          // Use T3 move-ins (not unit count) as move-in volume — same basis as revMonthlyImpact.
          // Pass predictedDTS as-is: null → calculateElasticityRevenueImpact returns null,
          // so groups without elasticity data correctly show blank rather than a naive figure.
          const groupT3MoveIns  = t3Map.get(key) ?? null;
          const elasticImpact   = calculateElasticityRevenueImpact({
            moveInsMonthly: groupT3MoveIns,
            deltaRate,
            deltaDaysToSell: predictedDTS,
            dailyRate,
          });
          groupElasticityMonthlyImpactMap.set(key, elasticImpact.monthly);
          // Store raw elasticity/DTS per group so unit rows can display them.
          groupElasticityDataMap.set(key, { elasticity, daysToSellBefore, daysToSellAfter, daysToSellChange, elasticityConfidence: elas?.confidence ?? null, elasticitySampleSize: elas?.sampleSize ?? 0 });
        }
      }

      const num = (v: any) => (v === null || v === undefined ? null : Number(v));
      const rows = unitsRes.rows.map((r: any) => {
        const ihSpot = num(r.in_house_rate);
        const streetSpot = num(r.street_rate);
        const compBase = num(r.comp_base);
        const compAdj = num(r.comp_adj);
        const unitGroupKey = `${r.campus}||${r.service_line || 'Other'}||${r.room_type || 'Other'}`;
        const manualOverride = unitOverrideMap.get(`${r.campus}||${r.service_line}||${r.room_type}`) ?? null;
        const proposed = manualOverride ?? num(r.proposed_rate) ?? rulePreviewMap.get(unitGroupKey) ?? null;
        return {
          division: r.division,
          region: r.region,
          campus: r.campus,
          serviceLine: r.service_line || 'Other',
          roomType: r.room_type || 'Other',
          roomNumber: r.room_number,
          occupiedStatus: r.occupied_yn ? 'Occupied' : 'Vacant',
          locationId: r.location_id ?? null,
          totalUnits: 1,
          vacantSpot: r.occupied_yn ? 0 : 1,
          daysVacantSpot: !r.occupied_yn ? num(r.days_vacant) : null,
          streetSpot,
          compBase,
          compAdjusted: compAdj,
          compVarDollar: (compAdj !== null && streetSpot !== null) ? compAdj - streetSpot : null,
          compVarPct: (compAdj !== null && streetSpot !== null && streetSpot !== 0) ? (compAdj - streetSpot) / streetSpot : null,
          ihSpot,
          ihVarStreetPct: (ihSpot !== null && streetSpot !== null && streetSpot !== 0) ? (ihSpot - streetSpot) / streetSpot : null,
          proposedRule: proposed,
          proposedVarDollar: (proposed !== null && streetSpot !== null) ? proposed - streetSpot : null,
          proposedVarPct: (proposed !== null && streetSpot !== null && streetSpot !== 0) ? (proposed - streetSpot) / streetSpot : null,
          ...((): { revT3MoveIns: number | null; revMonthlyImpact: number | null; revAnnualImpact: number | null } => {
            const key = `${r.campus}||${r.service_line || 'Other'}||${r.room_type || 'Other'}`;
            const groupT3  = t3Map.get(key) ?? null;
            const n        = groupUnitCount.get(key) || 1;
            const unitT3   = groupT3 !== null ? groupT3 / n : null;
            // Distribute the pre-computed group-level impact evenly across units so that
            // sum(revMonthlyImpact for the group) == the grouped endpoint's revMonthlyImpact.
            // Group impact uses mode street rate + avg proposed (same as grouped endpoint).
            const gMonthly    = groupMonthlyImpactMap.get(key) ?? null;
            const unitMonthly = gMonthly !== null ? gMonthly / n : null;
            return {
              revT3MoveIns: unitT3,
              revMonthlyImpact: unitMonthly,
              // First-year cumulative (× 78) — must match the grouped endpoint.
              revAnnualImpact: unitMonthly !== null ? unitMonthly * 78 : null,
              // Fully ramped / steady-state (× 144) — 12 full cohorts paying all year.
              revSteadyStateImpact: unitMonthly !== null ? unitMonthly * 144 : null,
            };
          })(),
          // Elasticity-based revenue impact — group total distributed evenly per unit,
          // matching the parity guarantee used for revMonthlyImpact above.
          ...((): { elasticityMonthlyImpact: number | null; elasticityAnnualImpact: number | null; elasticitySteadyStateImpact: number | null } => {
            const key = `${r.campus}||${r.service_line || 'Other'}||${r.room_type || 'Other'}`;
            const n = groupUnitCount.get(key) || 1;
            const gElMonthly = groupElasticityMonthlyImpactMap.get(key) ?? null;
            const unitElMonthly = gElMonthly !== null ? gElMonthly / n : null;
            return {
              elasticityMonthlyImpact: unitElMonthly,
              // First-year cumulative (× 78) — matches calculateElasticityRevenueImpact.
              elasticityAnnualImpact: unitElMonthly !== null ? unitElMonthly * 78 : null,
              // Fully ramped / steady-state (× 144).
              elasticitySteadyStateImpact: unitElMonthly !== null ? unitElMonthly * 144 : null,
            };
          })(),
          // Raw elasticity / DTS metrics — group-level values repeated on each unit row,
          // same pattern as campusOccSpot / slOccSpot so the Room Detail view can
          // display them and they aggregate correctly in the grouping layers.
          ...((): { elasticity: number | null; daysToSellBefore: number | null; daysToSellAfter: number | null; daysToSellChange: number | null; elasticityConfidence: number | null; elasticitySampleSize: number } => {
            const key = `${r.campus}||${r.service_line || 'Other'}||${r.room_type || 'Other'}`;
            const d = groupElasticityDataMap.get(key) as any;
            return {
              elasticity: d?.elasticity ?? null,
              daysToSellBefore: d?.daysToSellBefore ?? null,
              daysToSellAfter: d?.daysToSellAfter ?? null,
              daysToSellChange: d?.daysToSellChange ?? null,
              elasticityConfidence: d?.elasticityConfidence ?? null,
              elasticitySampleSize: d?.elasticitySampleSize ?? 0,
            };
          })(),
        };
      });

      const payload = { rows, spotMonth };
      setRefDataCache(cacheKey, payload, computeStart);
      res.setHeader('X-Cache', 'MISS');
      res.set('Cache-Control', 'no-store');
      res.json(payload);
    } catch (error) {
      console.error("Error building unit detail reference data:", error);
      res.status(500).json({ error: "Failed to build unit detail data" });
    }
  });

